window.BANKS = window.BANKS || {};
window.BANKS.SSA101 = {"topics":[{"name":"Tổng hợp"}],"questions":[{"id":"SSA101_Q001","t":"Which is a characteristic of analytical thinking?","o":[["A","Guessing outcomes","Đoán kết quả"],["B","Ignoring evidence","Bỏ qua bằng chứng"],["C","Verifying sources","Xác minh nguồn thông tin"],["D","Avoiding comparison","Tránh so sánh"]],"a":"C","s":0,"tv":"Đặc điểm nào là đặc trưng của tư duy phân tích?","e":"Analytical thinking requires checking and verifying information sources before drawing conclusions.","ev":"Tư duy phân tích yêu cầu kiểm tra và xác minh nguồn thông tin trước khi đưa ra kết luận.","g":"new"},{"id":"SSA101_Q002","t":"What is one common reason students procrastinate?","o":[["A","Tasks feel unimportant or overwhelming","Nhiệm vụ có vẻ không quan trọng hoặc quá sức"],["B","Instructors assign unclear deadlines","Giảng viên giao hạn chót không rõ ràng"],["C","Students lack intelligence and teamwork","Sinh viên thiếu thông minh và tinh thần đồng đội"],["D","College schedules are too flexible","Lịch học đại học quá linh hoạt"]],"a":"A","s":0,"tv":"Một lý do phổ biến mà students procrastinate là gì?","e":"When a task feels too difficult or unimportant, students tend to procrastinate.","ev":"Khi công việc quá khó hoặc không quan trọng, sinh viên dễ có xu hướng trì hoãn.","g":"new"},{"id":"SSA101_Q003","t":"Which concept focuses on identifying what tasks truly matter?","o":[["A","Multitasking","Làm nhiều việc cùng lúc"],["B","Time blocking","Chia khối thời gian"],["C","Prioritization","Xác định thứ tự ưu tiên"],["D","Delegation","Ủy quyền"]],"a":"C","s":0,"tv":"Khái niệm nào tập trung vào việc xác định những nhiệm vụ thực sự quan trọng?","e":"Prioritization helps identify tasks to focus on first.","ev":"Prioritization (ưu tiên công việc) giúp xác định nhiệm vụ cần tập trung trước tiên.","g":"new"},{"id":"SSA101_Q004","t":"Which habit most weakens critical thinking?","o":[["A","Seeking evidence","Tìm kiếm bằng chứng"],["B","Reflecting on assumptions and preconceptions","Suy ngẫm về các giả định và định kiến"],["C","Accepting information without evaluation","Chấp nhận thông tin mà không đánh giá"],["D","Comparing multiple sources","So sánh nhiều nguồn"]],"a":"C","s":0,"tv":"Thói quen nào làm suy yếu nhất tư duy phản biện?","e":"Accepting information without evaluating or verifying it reduces critical thinking ability.","ev":"Chấp nhận thông tin mà không đánh giá hoặc kiểm chứng sẽ làm giảm khả năng tư duy phản biện.","g":"new"},{"id":"SSA101_Q005","t":"Which Bloom's level requires learners to break information into parts?","o":[["A","Understand","Hiểu"],["B","Apply","Áp dụng"],["C","Analyze","Phân tích"],["D","Remember","Ghi nhớ"]],"a":"C","s":0,"tv":"Mức độ nào trong thang Bloom yêu cầu người học chia nhỏ thông tin thành các phần?","e":"“Analyze” focuses on analyzing and breaking down information to understand it better.","ev":"“Analyze” là mức độ tập trung vào việc phân tích và chia nhỏ thông tin để hiểu rõ hơn.","g":"new"},{"id":"SSA101_Q006","t":"Which behavior most strongly limits creative thinking?","o":[["A","Questioning assumptions","Đặt câu hỏi về các giả định"],["B","Fear of making mistakes","Sợ mắc sai lầm"],["C","Generating multiple solutions","Đưa ra nhiều giải pháp"],["D","Seeking alternative perspectives","Tìm kiếm các góc nhìn khác"]],"a":"B","s":0,"tv":"Hành vi nào hạn chế mạnh mẽ nhất tư duy sáng tạo?","e":"Fear of mistakes makes people reluctant to experiment and limits new creative ideas.","ev":"Nỗi sợ mắc sai lầm khiến con người ngại thử nghiệm và hạn chế ý tưởng sáng tạo mới.","g":"new"},{"id":"SSA101_Q007","t":"Which type of memory is primarily responsible for temporarily holding information while processing it?","o":[["A","Long-term memory","Trí nhớ dài hạn"],["B","Sensory memory","Trí nhớ giác quan"],["C","Working memory","Trí nhớ làm việc"],["D","Episodic memory","Trí nhớ theo từng sự kiện"]],"a":"C","s":0,"tv":"Loại trí nhớ nào chịu trách nhiệm chính cho việc temporarily holding information while processing it?","e":"Working memory helps store and process information in the short term.","ev":"Working memory (trí nhớ làm việc) giúp lưu trữ và xử lý thông tin ngắn hạn.","g":"new"},{"id":"SSA101_Q008","t":"Which step typically comes first in effective problem-solving?","o":[["A","Selecting a solution","Chọn một giải pháp"],["B","Clearly defining the problem","Xác định rõ vấn đề"],["C","Evaluating outcomes","Đánh giá kết quả"],["D","Implementing a plan immediately","Thực hiện kế hoạch ngay lập tức"]],"a":"B","s":0,"tv":"Bước nào thường đến đầu tiên trong quá trình giải quyết vấn đề hiệu quả?","e":"Effective problem-solving requires clearly defining the problem first.","ev":"Muốn giải quyết hiệu quả cần xác định rõ vấn đề trước tiên.","g":"new"},{"id":"SSA101_Q009","t":"Analytical thinking is especially useful when students need to:","o":[["A","Memorize large amounts of information","Ghi nhớ lượng lớn thông tin"],["B","Understand complex systems or arguments","Hiểu các hệ thống hoặc lập luận phức tạp"],["C","Express personal opinions creatively","Thể hiện ý kiến cá nhân một cách sáng tạo"],["D","Work under strict time pressure","Làm việc dưới áp lực thời gian chặt chẽ"]],"a":"B","s":0,"tv":"tư duy phân tích is especially useful when students need to:","e":"Analytical thinking helps in understanding complex systems or arguments.","ev":"Tư duy phân tích giúp hiểu các hệ thống hoặc lập luận phức tạp.","g":"new"},{"id":"SSA101_Q010","t":"A student accepts an online claim because it aligns with their beliefs. Which critical thinking skill is missing?","o":[["A","Creativity and problem solving","Sáng tạo và giải quyết vấn đề"],["B","Logical reasoning","Lập luận logic"],["C","Evaluation of evidence","Đánh giá bằng chứng"],["D","Time management","Quản lý thời gian"]],"a":"C","s":0,"tv":"A student accepts an online claim because it aligns with their beliefs. Which tư duy phản biện skill is missing?","e":"Evidence must be evaluated instead of believing something merely because it fits a personal viewpoint.","ev":"Cần đánh giá bằng chứng thay vì chỉ tin vì phù hợp với quan điểm cá nhân.","g":"new"},{"id":"SSA101_Q011","t":"Analytical thinking involves:","o":[["A","Trusting intuition","Tin vào trực giác"],["B","Breaking a whole into parts","Chia một tổng thể thành các phần"],["C","Following emotions","Làm theo cảm xúc"],["D","Avoiding structure","Tránh cấu trúc"]],"a":"B","s":0,"tv":"tư duy phân tích involves:","e":"Analytical thinking breaks a large problem into smaller parts to understand it better.","ev":"Tư duy phân tích là chia một vấn đề lớn thành các phần nhỏ để hiểu rõ hơn.","g":"new"},{"id":"SSA101_Q012","t":"According to Long & Magerko (2020), AI literacy enables individuals to:","o":[["A","Fully automate decision-making","Tự động hóa hoàn toàn việc ra quyết định"],["B","Critically evaluate AI technologies","Đánh giá một cách có phê phán các công nghệ AI"],["C","Eliminate bias in all AI systems","Loại bỏ thiên kiến trong mọi hệ thống AI"],["D","Replace teachers with AI","Thay thế giáo viên bằng AI"]],"a":"B","s":0,"tv":"Theo Long & Magerko (2020), năng lực AI enables individuals to:","e":"AI literacy helps people critically evaluate and use AI technologies.","ev":"AI literacy giúp đánh giá và sử dụng công nghệ AI một cách có phê phán.","g":"new"},{"id":"SSA101_Q013","t":"Critical thinking involves:","o":[["A","Guessing outcomes based on personal experiences","Đoán kết quả dựa trên kinh nghiệm cá nhân"],["B","Weighing options and data","Cân nhắc các lựa chọn và dữ liệu"],["C","Emotional reactions","Phản ứng theo cảm xúc"],["D","Blind trust","Tin tưởng mù quáng"]],"a":"B","s":0,"tv":"tư duy phản biện involves:","e":"Critical thinking requires weighing data and options before reaching a conclusion.","ev":"Tư duy phản biện yêu cầu cân nhắc dữ liệu và các lựa chọn trước khi kết luận.","g":"new"},{"id":"SSA101_Q014","t":"Creative thinking involves:","o":[["A","Memorization","Học thuộc lòng"],["B","Generating original ideas","Tạo ra ý tưởng độc đáo"],["C","Repeating tradition and exploring art","Lặp lại truyền thống và khám phá nghệ thuật"],["D","Avoiding risk","Tránh rủi ro"]],"a":"B","s":0,"tv":"tư duy sáng tạo involves:","e":"Creative thinking focuses on generating new and unique ideas.","ev":"Tư duy sáng tạo tập trung vào việc tạo ra ý tưởng mới và độc đáo.","g":"new"},{"id":"SSA101_Q015","t":"Cognitive presence in the Community of Inquiry refers mainly to:","o":[["A","Emotional engagement","Sự gắn kết về mặt cảm xúc"],["B","Knowledge construction through thinking","Xây dựng kiến thức thông qua tư duy"],["C","Instructor authority","Quyền uy của giảng viên"],["D","Social interaction","Tương tác xã hội"]],"a":"B","s":0,"tv":"“Sự hiện diện nhận thức” trong Community of Inquiry chủ yếu đề cập đến điều gì?","e":"Cognitive presence is the process of constructing knowledge through thinking and critical reflection.","ev":"Cognitive presence là quá trình xây dựng kiến thức thông qua tư duy và phản biện.","g":"new"},{"id":"SSA101_Q016","t":"Critical thinkers should:","o":[["A","Accept everything","Chấp nhận mọi thứ"],["B","Question everything","Đặt câu hỏi về mọi thứ"],["C","Avoid research","Tránh nghiên cứu"],["D","Being smart in all situations","Tỏ ra thông minh trong mọi tình huống"]],"a":"B","s":0,"tv":"Những người có tư duy phản biện nên:","e":"Critical thinking requires questioning and evaluating information instead of immediately accepting everything.","ev":"Tư duy phản biện yêu cầu đặt câu hỏi và đánh giá thông tin thay vì chấp nhận mọi thứ ngay lập tức.","g":"new"},{"id":"SSA101_Q017","t":"Goal setting is most effective when goals are:","o":[["A","Ambitious and open-ended","Tham vọng và không giới hạn"],["B","Flexible and undefined","Linh hoạt và không xác định"],["C","Specific, realistic, and measurable","Cụ thể, thực tế và đo lường được"],["D","Focused only on long-term outcomes","Chỉ tập trung vào kết quả dài hạn"]],"a":"C","s":0,"tv":"Việc đặt mục tiêu hiệu quả nhất khi các mục tiêu:","e":"Specific, realistic, and measurable goals are easier to implement and evaluate.","ev":"Mục tiêu cụ thể, thực tế và đo lường được sẽ dễ thực hiện và đánh giá kết quả hơn.","g":"new"},{"id":"SSA101_Q018","t":"In the Plan-Monitor-Evaluate cycle, monitoring mainly focuses on:","o":[["A","Setting learning goals","Đặt mục tiêu học tập"],["B","Checking understanding during learning","Kiểm tra mức độ hiểu bài trong quá trình học"],["C","Grading performance","Chấm điểm kết quả"],["D","Comparing results with peers","So sánh kết quả với bạn bè"]],"a":"B","s":0,"tv":"Trong chu trình Plan-Monitor-Evaluate, việc “monitoring” chủ yếu tập trung vào:","e":"Monitoring means tracking understanding and learning progress during study.","ev":"Monitoring là theo dõi mức độ hiểu bài và tiến trình học tập trong quá trình học.","g":"new"},{"id":"SSA101_Q019","t":"Successful students typically view challenges as:","o":[["A","Signs they chose the wrong major","Dấu hiệu cho thấy họ đã chọn sai ngành"],["B","Evidence of instructor bias","Bằng chứng về sự thiên vị của giảng viên"],["C","Opportunities for growth and adjustment","Cơ hội để phát triển và điều chỉnh"],["D","Reasons to withdraw from courses","Lý do để rút khỏi môn học"]],"a":"C","s":0,"tv":"Sinh viên thành công thường xem thử thách là:","e":"Challenges are seen as opportunities to develop and improve oneself.","ev":"Thử thách được xem như cơ hội để phát triển và cải thiện bản thân.","g":"new"},{"id":"SSA101_Q020","t":"What is one major difference between high school and college learning?","o":[["A","College instructors monitor students' progress more closely","Giảng viên đại học theo dõi tiến độ của sinh viên sát sao hơn"],["B","College requires greater student responsibility and self-advocacy","Đại học đòi hỏi sinh viên có trách nhiệm và biết tự lên tiếng bảo vệ quyền lợi nhiều hơn"],["C","College courses require fewer assessments but much more difficult","Các môn đại học có ít bài đánh giá hơn nhưng khó hơn nhiều"],["D","College learning focuses less on independent work","Việc học đại học ít tập trung vào làm việc độc lập hơn"]],"a":"B","s":0,"tv":"Một khác biệt lớn giữa việc học ở trung học và đại học là gì?","e":"College requires students to be more proactive and responsible for their own learning.","ev":"Học đại học yêu cầu sinh viên chủ động và chịu trách nhiệm nhiều hơn cho việc học của mình.","g":"new"},{"id":"SSA101_Q021","t":"What is the main purpose of self-directed learning in online education?","o":[["A","To reduce instructor workload","Giảm khối lượng công việc của giảng viên"],["B","To help students take control of their learning","Giúp sinh viên kiểm soát việc học của mình"],["C","To eliminate group work","Loại bỏ làm việc nhóm"],["D","To replace assessments with self-study activities","Thay thế bài đánh giá bằng các hoạt động tự học"]],"a":"B","s":0,"tv":"Mục đích chính của self-directed learning in online education là gì?","e":"Self-directed learning helps students actively manage their learning process.","ev":"Học tự định hướng giúp sinh viên chủ động quản lý quá trình học tập của mình.","g":"new"},{"id":"SSA101_Q022","t":"What role does environment play in effective studying?","o":[["A","It has minimal impact","Có tác động rất nhỏ"],["B","It only matters for group study","Chỉ quan trọng khi học nhóm"],["C","It can significantly affect focus and memory","Có thể ảnh hưởng đáng kể đến sự tập trung và trí nhớ"],["D","It replaces good study strategies and techniques","Thay thế các chiến lược và kỹ thuật học tập tốt"]],"a":"C","s":0,"tv":"Môi trường đóng vai trò gì trong việc học hiệu quả?","e":"The learning environment greatly affects concentration and memory.","ev":"Môi trường học tập ảnh hưởng lớn đến khả năng tập trung và ghi nhớ thông tin.","g":"new"},{"id":"SSA101_Q023","t":"Which skill is NOT explicitly included in digital literacy as described in the book?","o":[["A","Evaluating online information","Đánh giá thông tin trực tuyến"],["B","Communicating through digital platforms and social media","Giao tiếp qua các nền tảng số và mạng xã hội"],["C","Understanding neural network architecture in depth","Hiểu sâu kiến trúc mạng nơ-ron"],["D","Responsible engagement with digital content","Tham gia có trách nhiệm với nội dung số"]],"a":"C","s":0,"tv":"Which skill is NOT explicitly included in năng lực kỹ thuật số as described in the book?","e":"Digital literacy focuses on using and evaluating digital technology, without requiring deep understanding of neural network architecture.","ev":"Digital literacy tập trung vào sử dụng và đánh giá công nghệ số, không yêu cầu hiểu sâu kiến trúc mạng nơ-ron.","g":"new"},{"id":"SSA101_Q024","t":"Which of the following is NOT a component of metacognition?","o":[["A","Planning how to approach a task","Lên kế hoạch cách tiếp cận một nhiệm vụ"],["B","Monitoring understanding during learning","Theo dõi mức độ hiểu bài trong quá trình học"],["C","Evaluating outcomes after completing a task","Đánh giá kết quả sau khi hoàn thành nhiệm vụ"],["D","Memorizing facts without reflection","Ghi nhớ sự kiện mà không suy ngẫm"]],"a":"D","s":0,"tv":"Điều nào sau đây KHÔNG phải là a component of metacognition?","e":"Metacognition involves planning, monitoring, and evaluating learning, not rote memorization.","ev":"Metacognition liên quan đến lập kế hoạch, theo dõi và đánh giá việc học, không phải học thuộc máy móc.","g":"new"},{"id":"SSA101_Q025","t":"Which of the following is identified as a common barrier to effective communication?","o":[["A","Clear purpose and using technologies","Mục đích rõ ràng và sử dụng công nghệ"],["B","Cultural awareness and prejudice","Nhận thức văn hóa và định kiến"],["C","Assumptions and misinterpretations","Các giả định và sự hiểu sai"],["D","Active listening strategies","Các chiến lược lắng nghe chủ động"]],"a":"C","s":0,"tv":"Lựa chọn nào sau đây là identified as a common barrier to effective communication?","e":"Assumptions and misunderstandings often hinder effective communication.","ev":"Các giả định và hiểu sai thường gây cản trở giao tiếp hiệu quả.","g":"new"},{"id":"SSA101_Q026","t":"Which of the following best describes \"college culture\"?","o":[["A","A fixed set of rules identical across all academic institutions","Một bộ quy tắc cố định giống nhau ở mọi cơ sở giáo dục"],["B","A system focused only on academic performance and science of knowledge","Một hệ thống chỉ tập trung vào kết quả học tập và khoa học tri thức"],["C","Shared expectations, language, and norms within higher education","Những kỳ vọng, ngôn ngữ và chuẩn mực chung trong giáo dục đại học"],["D","A social environment unrelated to learning","Một môi trường xã hội không liên quan đến việc học"]],"a":"C","s":0,"tv":"Điều nào mô tả đúng nhất “văn hóa đại học”?","e":"College culture includes shared norms, expectations, and ways of communicating in higher education.","ev":"Văn hóa đại học bao gồm các chuẩn mực, kỳ vọng và cách giao tiếp chung trong môi trường giáo dục đại học.","g":"new"},{"id":"SSA101_Q027","t":"Which of the following best defines time-on-task?","o":[["A","The total time spent thinking about an assignment","Tổng thời gian dành để nghĩ về một bài tập"],["B","The actual time required to complete a specific task","Thời gian thực tế cần để hoàn thành một nhiệm vụ cụ thể"],["C","The time available before a deadline","Thời gian còn lại trước hạn chót"],["D","The amount of time scheduled for studying each week","Lượng thời gian được lên lịch để học mỗi tuần"]],"a":"B","s":0,"tv":"Điều nào mô tả đúng nhất “time-on-task”?","e":"Time-on-task is the actual time spent completing a task.","ev":"Time-on-task là khoảng thời gian thực tế dành để hoàn thành nhiệm vụ.","g":"new"},{"id":"SSA101_Q028","t":"Which of the following best describes retrieval in learning?","o":[["A","Re-reading notes repeatedly","Đọc lại ghi chú nhiều lần"],["B","Accessing and using stored knowledge when needed","Truy xuất và sử dụng kiến thức đã lưu trữ khi cần"],["C","Highlighting important sections of a text","Đánh dấu các phần quan trọng của văn bản"],["D","Uploading materials to an AI chatbot","Tải tài liệu lên chatbot AI"]],"a":"B","s":0,"tv":"Điều nào mô tả đúng nhất việc truy xuất thông tin (retrieval) trong học tập?","e":"Retrieval is the process of accessing stored knowledge when needed.","ev":"Retrieval là quá trình lấy lại kiến thức đã lưu trữ khi cần sử dụng.","g":"new"},{"id":"SSA101_Q029","t":"Which of the following best describes encoding in the learning process?","o":[["A","Storing information permanently without effort using long-term memory","Lưu trữ thông tin vĩnh viễn mà không cần nỗ lực nhờ trí nhớ dài hạn"],["B","Processing new information deeply so that memories are formed","Xử lý thông tin mới một cách sâu sắc để hình thành ký ức"],["C","Recalling information during an exam","Nhớ lại thông tin trong kỳ thi"],["D","Translating information into digital formats","Chuyển thông tin sang định dạng số"]],"a":"B","s":0,"tv":"Điều nào mô tả đúng nhất việc mã hóa thông tin (encoding) trong quá trình học tập?","e":"Encoding is processing new information to form memories.","ev":"Encoding là xử lý thông tin mới để tạo thành ký ức trong trí nhớ.","g":"new"},{"id":"SSA101_Q030","t":"Which of the following best distinguishes digital literacy from AI literacy?","o":[["A","Digital literacy focuses only on social media skills while AI literacy focuses on academic skills","Kỹ năng số chỉ tập trung vào mạng xã hội còn kỹ năng AI tập trung vào học thuật"],["B","AI literacy includes competencies for understanding and interacting with AI systems","Hiểu biết về AI bao gồm các năng lực để hiểu và tương tác với hệ thống AI"],["C","AI literacy excludes ethical considerations","Hiểu biết về AI loại trừ các vấn đề đạo đức"],["D","Digital literacy is limited to hardware usage","Kỹ năng số chỉ giới hạn ở việc sử dụng phần cứng"]],"a":"B","s":0,"tv":"Which of the following best distinguishes năng lực kỹ thuật số from năng lực AI?","e":"AI literacy focuses on understanding and interacting with AI systems, beyond basic digital skills.","ev":"AI literacy tập trung vào việc hiểu và tương tác với các hệ thống AI, vượt ngoài kỹ năng số cơ bản.","g":"new"},{"id":"SSA101_Q031","t":"Which of the following is a key step in analytical thinking?","o":[["A","Accepting information at face value and let it be there","Chấp nhận thông tin theo bề ngoài và để nó như vậy"],["B","Separating facts from assumptions before drawing conclusions","Tách biệt sự thật khỏi giả định trước khi rút ra kết luận"],["C","Generating as many ideas as possible regardless the quality of each idea","Tạo ra càng nhiều ý tưởng càng tốt bất kể chất lượng"],["D","Prioritizing emotional responses","Ưu tiên phản ứng cảm xúc"]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là a key step in tư duy phân tích?","e":"Analytical thinking requires distinguishing facts from assumptions before reaching a conclusion.","ev":"Tư duy phân tích yêu cầu phân biệt sự thật với giả định trước khi kết luận.","g":"new"},{"id":"SSA101_Q032","t":"Which activity best demonstrates metacognitive awareness?","o":[["A","Studying longer hours before exams to aim high grades","Học nhiều giờ hơn trước kỳ thi để đạt điểm cao"],["B","Recognizing which study strategies work best for you","Nhận ra chiến lược học nào hiệu quả nhất với bạn"],["C","Highlighting every paragraph in a textbook","Đánh dấu mọi đoạn văn trong sách giáo khoa"],["D","Copying notes from slides","Chép ghi chú từ slide"]],"a":"B","s":0,"tv":"Hoạt động nào thể hiện tốt nhất nhận thức siêu nhận thức (metacognitive awareness)?","e":"Metacognition is understanding and evaluating which learning methods work best for oneself.","ev":"Siêu nhận thức là hiểu và đánh giá cách học nào hiệu quả nhất với bản thân.","g":"new"},{"id":"SSA101_Q033","t":"Which factor most strongly affects how a message is interpreted?","o":[["A","The length of the message","Độ dài của thông điệp"],["B","The context in which communication occurs","Bối cảnh diễn ra giao tiếp"],["C","The communication technology used such as social media","Công nghệ giao tiếp được sử dụng, chẳng hạn mạng xã hội"],["D","The sender's educational background and attitude","Trình độ học vấn và thái độ của người gửi"]],"a":"B","s":0,"tv":"Yếu tố nào ảnh hưởng mạnh nhất đến cách một thông điệp được diễn giải?","e":"The communication context greatly affects how the recipient understands a message.","ev":"Ngữ cảnh giao tiếp ảnh hưởng lớn đến cách người nhận hiểu thông điệp.","g":"new"},{"id":"SSA101_Q034","t":"Which question best helps evaluate the credibility of a source?","o":[["A","Is the information easy to read and interpret?","Thông tin có dễ đọc và dễ hiểu không?"],["B","Does the author have relevant expertise?","Tác giả có chuyên môn liên quan không?"],["C","Is the source visually appealing?","Nguồn có hấp dẫn về mặt hình thức không?"],["D","Does the source confirm personal opinions?","Nguồn có xác nhận ý kiến cá nhân không?"]],"a":"B","s":0,"tv":"Câu hỏi nào giúp đánh giá độ tin cậy của một nguồn thông tin tốt nhất?","e":"The author’s expertise is an important factor in determining a source’s credibility.","ev":"Chuyên môn của tác giả là yếu tố quan trọng để xác định độ tin cậy của nguồn.","g":"new"},{"id":"SSA101_Q035","t":"Which practice best demonstrates responsible use of information?","o":[["A","Copying text when sources are cited without any form of paraphrasing","Sao chép văn bản khi có trích dẫn nguồn mà không diễn đạt lại"],["B","Paraphrasing without attribution","Diễn đạt lại nhưng không ghi nguồn"],["C","Integrating sources while acknowledging original authors","Kết hợp các nguồn đồng thời ghi nhận tác giả gốc"],["D","Using only one strong source","Chỉ sử dụng một nguồn mạnh"]],"a":"C","s":0,"tv":"Thực hành nào thể hiện tốt nhất việc sử dụng thông tin có trách nhiệm?","e":"Original authors must be acknowledged when using information to avoid plagiarism.","ev":"Cần ghi nhận tác giả gốc khi sử dụng thông tin để tránh đạo văn.","g":"new"},{"id":"SSA101_Q036","t":"Which statement best reflects how time management in college differs from high school?","o":[["A","College students have fewer deadlines","Sinh viên đại học có ít hạn chót hơn"],["B","College schedules are more structured and require more efforts to follow","Lịch học đại học có cấu trúc hơn và đòi hỏi nhiều nỗ lực hơn để tuân theo"],["C","College requires students to independently plan and allocate time","Đại học đòi hỏi sinh viên tự lập kế hoạch và phân bổ thời gian"],["D","Time management is less important in college","Quản lý thời gian ít quan trọng hơn ở đại học"]],"a":"C","s":0,"tv":"Which statement best reflects how quản lý thời gian in college differs from high school?","e":"In college, students are expected to manage their own time: they must plan and allocate it independently, with far less supervision than in high school. Having fewer deadlines or finding time management less important are not true of college.","ev":"Ở đại học, sinh viên phải tự quản lý thời gian: tự lập kế hoạch và phân bổ thời gian, với ít sự giám sát hơn nhiều so với cấp ba. Việc có ít hạn nộp hơn hoặc coi quản lý thời gian ít quan trọng hơn không đúng với môi trường đại học.","g":"new"},{"id":"SSA101_Q037","t":"Which statement best reflects the authors' view of the college transition?","o":[["A","It is primarily academic and rarely emotional","Chủ yếu về học tập và hiếm khi liên quan đến cảm xúc"],["B","It is uniform for all students","Giống nhau với mọi sinh viên"],["C","It involves academic, social, and personal change","Bao gồm những thay đổi về học tập, xã hội và cá nhân"],["D","It ends after the first month","Kết thúc sau tháng đầu tiên"]],"a":"C","s":0,"tv":"Phát biểu nào phản ánh đúng nhất quan điểm của các tác giả về quá trình chuyển tiếp lên đại học?","e":"The transition to college includes academic, social, and personal changes.","ev":"Việc chuyển tiếp lên đại học bao gồm thay đổi về học tập, xã hội và cá nhân.","g":"new"},{"id":"SSA101_Q038","t":"Which action best represents effective problem-solving?","o":[["A","Selecting the first solution that seems reasonable","Chọn giải pháp đầu tiên có vẻ hợp lý"],["B","Ignoring alternative approaches","Phớt lờ các cách tiếp cận thay thế"],["C","Evaluating possible solutions before implementation","Đánh giá các giải pháp khả thi trước khi thực hiện"],["D","Avoiding feedback after solving the problem","Tránh phản hồi sau khi giải quyết vấn đề"]],"a":"C","s":0,"tv":"Which action best represents effective giải quyết vấn đề?","e":"Solutions need to be evaluated before implementation to choose the most appropriate one.","ev":"Cần đánh giá các giải pháp trước khi áp dụng để chọn phương án phù hợp nhất.","g":"new"},{"id":"SSA101_Q039","t":"Which step typically comes first in effective problem-solving?","o":[["A","Choosing a solution","Chọn một giải pháp"],["B","Identifying and defining the problem clearly","Nhận diện và xác định rõ vấn đề"],["C","Evaluating results based on criteria","Đánh giá kết quả dựa trên tiêu chí"],["D","Implementing a strategy using the power of teamwork","Triển khai một chiến lược bằng sức mạnh của làm việc nhóm"]],"a":"B","s":0,"tv":"Bước nào thường đến đầu tiên trong quá trình giải quyết vấn đề hiệu quả?","e":"To solve a problem correctly, it must first be clearly identified.","ev":"Muốn giải quyết vấn đề đúng cần xác định rõ vấn đề trước tiên.","g":"new"},{"id":"SSA101_Q040","t":"Which question best reflects a critical thinking mindset?","o":[["A","\"Do I agree with this?\"","\"Tôi có đồng ý với điều này không?\""],["B","\"Is this information popular?\"","\"Thông tin này có phổ biến không?\""],["C","\"What evidence supports this claim?\"","\"Bằng chứng nào ủng hộ khẳng định này?\""],["D","\"Who benefits from this idea emotionally?\"","\"Ai được lợi từ ý tưởng này về mặt cảm xúc?\""]],"a":"C","s":0,"tv":"Which question best reflects a tư duy phản biện mindset?","e":"Critical thinking focuses on evidence to assess the accuracy of information.","ev":"Tư duy phản biện tập trung vào bằng chứng để đánh giá tính đúng đắn của thông tin.","g":"new"},{"id":"SSA101_Q041","t":"Which activity best demonstrates analytical thinking?","o":[["A","Brainstorming multiple possible essay topics quickly and productively","Động não nhanh chóng và hiệu quả nhiều chủ đề tiểu luận khả thi"],["B","Identifying relevant data while ignoring unnecessary details in a problem","Xác định dữ liệu liên quan và bỏ qua chi tiết không cần thiết trong một bài toán"],["C","Agreeing with the most popular interpretation of an issue","Đồng ý với cách diễn giải phổ biến nhất về một vấn đề"],["D","Responding emotionally to complex situations","Phản ứng theo cảm xúc trước các tình huống phức tạp"]],"a":"B","s":0,"tv":"Which activity best demonstrates tư duy phân tích?","e":"Analytical thinking focuses on selecting important information and removing unnecessary details.","ev":"Tư duy phân tích tập trung vào việc chọn lọc thông tin quan trọng và loại bỏ chi tiết không cần thiết","g":"new"},{"id":"SSA101_Q042","t":"Which strategy is recommended for managing test anxiety?","o":[["A","Avoiding preparation to reduce stress","Tránh chuẩn bị để giảm căng thẳng"],["B","Relying on last-minute cramming","Dựa vào học nhồi vào phút chót"],["C","Using preparation and familiarity to reduce fear","Dùng sự chuẩn bị và quen thuộc để giảm nỗi sợ"],["D","Studying only the night before","Chỉ học vào đêm trước"]],"a":"C","s":0,"tv":"Chiến lược nào được khuyến nghị để kiểm soát lo âu khi làm bài kiểm tra?","e":"Thorough preparation and familiarity with the content help reduce stress and anxiety.","ev":"Chuẩn bị kỹ và quen thuộc với nội dung giúp giảm căng thẳng và lo lắng.","g":"new"},{"id":"SSA101_Q043","t":"Which question reflects a metacognitive approach to learning?","o":[["A","\"How many pages do I need to read?\"","\"Mình cần đọc bao nhiêu trang?\""],["B","\"What strategy am I using, and is it effective?\"","\"Mình đang dùng chiến lược nào và nó có hiệu quả không?\""],["C","\"Will this be on the exam and how can I have support?\"","\"Cái này có thi không và làm sao để được hỗ trợ?\""],["D","\"How long is this assignment?\"","\"Bài tập này dài bao nhiêu?\""]],"a":"B","s":0,"tv":"Câu hỏi nào phản ánh cách tiếp cận siêu nhận thức trong học tập?","e":"Metacognition involves self-evaluating learning strategies and their effectiveness.","ev":"Siêu nhận thức là tự đánh giá chiến lược học tập và hiệu quả của nó.","g":"new"},{"id":"SSA101_Q044","t":"Which study habit is least effective for long-term learning?","o":[["A","Self-testing with flashcards, quiz and teaching others","Tự kiểm tra bằng thẻ ghi nhớ, câu đố và dạy người khác"],["B","Spaced practice combined with interleaving","Luyện tập giãn cách kết hợp với xen kẽ"],["C","Re-reading notes repeatedly without engagement","Đọc lại ghi chú nhiều lần mà không tham gia chủ động"],["D","Reviewing mistakes","Xem lại các lỗi sai"]],"a":"C","s":0,"tv":"Thói quen học tập nào kém hiệu quả nhất cho việc ghi nhớ lâu dài?","e":"Passive rereading without interaction or practice makes long-term retention difficult.","ev":"Chỉ đọc lại thụ động mà không tương tác hay luyện tập sẽ khó ghi nhớ lâu dài.","g":"new"},{"id":"SSA101_Q045","t":"Which condition best supports creative thinking?","o":[["A","Strict adherence to one correct answer","Bám chặt vào một đáp án đúng duy nhất"],["B","Openness to risk and experimentation","Cởi mở với rủi ro và thử nghiệm"],["C","Avoidance of uncertainty","Tránh sự không chắc chắn"],["D","Dependence on authority","Phụ thuộc vào uy quyền"]],"a":"B","s":0,"tv":"Which condition best supports tư duy sáng tạo?","e":"Creative thinking develops when people are willing to experiment and accept risks.","ev":"Tư duy sáng tạo phát triển khi sẵn sàng thử nghiệm và chấp nhận rủi ro.","g":"new"},{"id":"SSA101_Q046","t":"Which situation would most clearly violate ethical guidelines when using AI for assessment?","o":[["A","Using AI to grade multiple-choice quizzes","Dùng AI để chấm bài trắc nghiệm"],["B","Using AI to provide grammar suggestions","Dùng AI để gợi ý ngữ pháp"],["C","Using AI to evaluate student work without students' consent or awareness","Dùng AI để đánh giá bài làm của sinh viên mà không có sự đồng ý hoặc nhận biết của họ"],["D","Using AI to help manage gradebooks","Dùng AI để hỗ trợ quản lý sổ điểm"]],"a":"C","s":0,"tv":"Tình huống nào vi phạm rõ ràng nhất các nguyên tắc đạo đức khi sử dụng AI trong đánh giá?","e":"Using AI without informing learners or obtaining their consent violates ethical principles.","ev":"Sử dụng AI mà không thông báo hoặc không có sự đồng ý của người học là vi phạm đạo đức.","g":"new"},{"id":"SSA101_Q047","t":"Why does the author warn against confusing opinion with evidence?","o":[["A","Opinions are always incorrect and being more effected by emotions","Ý kiến luôn sai và chịu ảnh hưởng nhiều hơn bởi cảm xúc"],["B","Evidence-based reasoning leads to stronger conclusions","Lập luận dựa trên bằng chứng dẫn đến kết luận vững chắc hơn"],["C","Opinions slow down decision-making","Ý kiến làm chậm việc ra quyết định"],["D","Evidence is difficult to interpret","Bằng chứng khó diễn giải"]],"a":"B","s":0,"tv":"Tại sao the author warn against confusing opinion with evidence?","e":"Evidence-based reasoning helps produce more reliable conclusions.","ev":"Lập luận dựa trên bằng chứng giúp đưa ra kết luận đáng tin cậy hơn.","g":"new"},{"id":"SSA101_Q048","t":"Why does Chapter 7 emphasize defining the problem accurately?","o":[["A","It reduces the number of possible solutions","Nó làm giảm số lượng giải pháp khả thi"],["B","Incorrect problem definition leads to ineffective solutions","Xác định sai vấn đề dẫn đến giải pháp không hiệu quả"],["C","It saves time in implementation","Nó tiết kiệm thời gian triển khai"],["D","It limits creative thinking","Nó hạn chế tư duy sáng tạo"]],"a":"B","s":0,"tv":"Tại sao Chapter 7 emphasize defining the problem accurately?","e":"If the problem is identified incorrectly, the resulting solution will be ineffective.","ev":"Nếu xác định sai vấn đề thì giải pháp đưa ra sẽ không hiệu quả.","g":"new"},{"id":"SSA101_Q049","t":"Why is retrieval practice effective for learning?","o":[["A","It reduces the amount of material and knowledge to study","Nó giảm lượng tài liệu và kiến thức cần học"],["B","It strengthens memory storage and retrieval pathways","Nó củng cố việc lưu trữ ký ức và các đường truy xuất"],["C","It replaces the need for review knowledge","Nó thay thế nhu cầu ôn tập kiến thức"],["D","It prevents forgetting entirely","Nó ngăn việc quên hoàn toàn"]],"a":"B","s":0,"tv":"Tại sao retrieval practice effective for learning?","e":"Retrieval practice strengthens memory and improves the ability to remember and recall information.","ev":"Luyện tập truy xuất giúp củng cố trí nhớ và tăng khả năng ghi nhớ, truy hồi thông tin.","g":"new"},{"id":"SSA101_Q050","t":"Why is relying solely on search engine rankings problematic?","o":[["A","High-ranking results are always outdated","Các kết quả xếp hạng cao luôn đã lỗi thời"],["B","Rankings prioritize academic sources only","Xếp hạng chỉ ưu tiên các nguồn học thuật"],["C","Popularity does not equal accuracy or reliability","Sự phổ biến không đồng nghĩa với độ chính xác hay độ tin cậy"],["D","Search engines limit access to peer-reviewed material","Công cụ tìm kiếm hạn chế truy cập vào tài liệu được bình duyệt"]],"a":"C","s":0,"tv":"Tại sao relying solely on search engine rankings problematic?","e":"Popular content is not necessarily accurate or reliable.","ev":"Nội dung phổ biến chưa chắc đã chính xác hoặc đáng tin cậy.","g":"new"},{"id":"SSA101_Q051","t":"Why is using AI for personalized feedback considered ethically problematic in some cases?","o":[["A","AI feedback is always inaccurate or inclined towards complementation","Phản hồi của AI luôn không chính xác hoặc thiên về nịnh hót"],["B","It may replace meaningful instructor-student learning relationships","Nó có thể thay thế mối quan hệ học tập có ý nghĩa giữa giảng viên và sinh viên"],["C","Students prefer automated feedback","Sinh viên thích phản hồi tự động"],["D","AI cannot process written language","AI không thể xử lý ngôn ngữ viết"]],"a":"B","s":0,"tv":"Tại sao using AI for personalized feedback considered ethically problematic in some cases?","e":"AI can reduce interaction and learning relationships between instructors and students.","ev":"AI có thể làm giảm sự tương tác và mối quan hệ học tập giữa giảng viên và sinh viên.","g":"new"},{"id":"SSA101_Q052","t":"Why is understanding why you are in college considered foundational for success?","o":[["A","It helps students choose easier and low-cost courses","Nó giúp sinh viên chọn các môn dễ hơn và chi phí thấp"],["B","It clarifies long-term goals and increases motivation","Nó làm rõ mục tiêu dài hạn và tăng động lực"],["C","It allows students to reduce academic workload","Nó cho phép sinh viên giảm khối lượng học tập"],["D","It guarantees higher grades","Nó đảm bảo điểm cao hơn"]],"a":"B","s":0,"tv":"Tại sao understanding why you are in college considered foundational for success?","e":"Understanding learning goals increases motivation and provides long-term direction.","ev":"Hiểu mục tiêu học tập giúp tăng động lực và định hướng lâu dài.","g":"new"},{"id":"SSA101_Q053","t":"Why is it important to evaluate bias in sources?","o":[["A","Bias invalidates all arguments and ideas","Thiên kiến làm mọi lập luận và ý tưởng mất giá trị"],["B","Bias helps identify the strongest position to debate","Thiên kiến giúp xác định lập trường mạnh nhất để tranh luận"],["C","Understanding bias helps interpret information critically","Hiểu thiên kiến giúp diễn giải thông tin một cách có phê phán"],["D","Biased sources should never be used","Không bao giờ nên dùng các nguồn thiên kiến"]],"a":"C","s":0,"tv":"Tại sao it important to evaluate bias in sources?","e":"Recognizing bias helps analyze and evaluate information more objectively.","ev":"Nhận biết sự thiên vị giúp phân tích và đánh giá thông tin khách quan hơn.","g":"new"},{"id":"SSA101_Q054","t":"Why is intentional choice of communication method important?","o":[["A","Different methods require different levels of formality and clarity","Các phương thức khác nhau đòi hỏi mức độ trang trọng và rõ ràng khác nhau"],["B","Face-to-face communication is always superior and productive","Giao tiếp trực tiếp luôn vượt trội và hiệu quả"],["C","Digital communication reduces misunderstandings","Giao tiếp kỹ thuật số giảm hiểu lầm"],["D","Informal methods save time","Các phương thức không chính thức tiết kiệm thời gian"]],"a":"A","s":0,"tv":"Tại sao intentional choice of communication method lại quan trọng?","e":"Each communication method requires different levels of clarity and formality.","ev":"Mỗi hình thức giao tiếp cần mức độ rõ ràng và trang trọng khác nhau.","g":"new"},{"id":"SSA101_Q055","t":"Why is metacognition considered a self-regulation skill?","o":[["A","It controls classroom behavior and course expectation","Nó kiểm soát hành vi trong lớp và kỳ vọng của môn học"],["B","It allows students to manage and direct their learning","Nó cho phép sinh viên quản lý và định hướng việc học của mình"],["C","It reduces dependence on instructors","Nó giảm sự phụ thuộc vào giảng viên"],["D","It improves memorization speed","Nó cải thiện tốc độ ghi nhớ"]],"a":"B","s":0,"tv":"Tại sao metacognition considered a self-regulation skill?","e":"Metacognition helps learners manage and adjust their own learning process.","ev":"Siêu nhận thức giúp người học tự quản lý và điều chỉnh quá trình học tập.","g":"new"},{"id":"SSA101_Q056","t":"Why is multitasking a bad habit for learning?","o":[["A","It increases creativity in complex tasks","Nó tăng sự sáng tạo trong các nhiệm vụ phức tạp"],["B","It often reduces efficiency and quality of work","Nó thường làm giảm hiệu quả và chất lượng công việc"],["C","It saves time when deadlines overlap","Nó tiết kiệm thời gian khi các hạn chót chồng lên nhau"],["D","It improves long-term memory","Nó cải thiện trí nhớ dài hạn"]],"a":"B","s":0,"tv":"Tại sao multitasking a bad habit for learning?","e":"Doing several things at once often reduces efficiency and work quality.","ev":"Làm nhiều việc cùng lúc thường làm giảm hiệu quả và chất lượng công việc.","g":"new"},{"id":"SSA101_Q057","t":"Why is the process in analytical thinking important?","o":[["A","Because outcomes matter more than understanding","Vì kết quả quan trọng hơn sự hiểu biết"],["B","Because understanding how parts connect leads to better conclusions","Vì hiểu cách các phần liên kết với nhau dẫn đến kết luận tốt hơn"],["C","Because analytical thinking is slower than other thinking types","Vì tư duy phân tích chậm hơn các kiểu tư duy khác"],["D","Because it reduces creativity","Vì nó làm giảm sự sáng tạo"]],"a":"B","s":0,"tv":"Tại sao the process in tư duy phân tích lại quan trọng?","e":"Understanding connections between parts helps produce more accurate conclusions.","ev":"Hiểu mối liên hệ giữa các phần giúp đưa ra kết luận chính xác hơn.","g":"new"},{"id":"SSA101_Q058","t":"Why is transparency in AI systems important?","o":[["A","It increases software profits","Nó làm tăng lợi nhuận phần mềm"],["B","It allows users to modify algorithms directly","Nó cho phép người dùng trực tiếp sửa đổi thuật toán"],["C","It enables accountability and trust","Nó tạo nên trách nhiệm giải trình và sự tin cậy"],["D","It eliminates the need for regulation","Nó loại bỏ nhu cầu quy định"]],"a":"C","s":0,"tv":"Tại sao transparency in AI systems lại quan trọng?","e":"Transparency increases trust and accountability in AI systems.","ev":"Tính minh bạch giúp tăng sự tin cậy và trách nhiệm giải trình của hệ thống AI.","g":"new"},{"id":"SSA101_Q059","t":"Why does the author argue that using AI to do the work instead of the student is problematic?","o":[["A","It violates copyright law automatically","Nó tự động vi phạm luật bản quyền"],["B","It cheats students out of the learning experience","Nó tước đi trải nghiệm học tập của sinh viên"],["C","It reduces the accuracy of AI systems","Nó làm giảm độ chính xác của hệ thống AI"],["D","It increases institutional costs and reduces","Nó làm tăng chi phí của nhà trường và giảm"]],"a":"B","s":0,"tv":"Tại sao the author argue that using AI to do the work instead of the student is problematic?","e":"Letting AI do the work deprives students of opportunities to learn and develop skills.","ev":"Việc để AI làm thay khiến sinh viên mất cơ hội học tập và phát triển kỹ năng.","g":"new"},{"id":"SSA101_Q060","t":"Why should we review outcomes after implementing a solution?","o":[["A","To assign blame","Để quy trách nhiệm"],["B","To determine whether adjustments are needed","Để xác định liệu có cần điều chỉnh không"],["C","To prove effort was sufficient and possible","Để chứng minh nỗ lực là đủ và khả thi"],["D","To avoid repeating the process","Để tránh lặp lại quy trình"]],"a":"B","s":0,"tv":"Tại sao chúng ta nên xem xét kết quả sau khi thực hiện một giải pháp?","e":"Evaluating results helps determine whether the solution needs adjustment.","ev":"Đánh giá kết quả giúp xác định có cần điều chỉnh giải pháp hay không.","g":"new"},{"id":"SSA101_Q061","t":"Why does the book emphasize higher-order thinking in online learning?","o":[["A","Exams are more difficult online","Các kỳ thi trực tuyến khó hơn"],["B","Surface learning is ineffective for long-term learning","Học bề mặt không hiệu quả cho việc học dài hạn"],["C","Students prefer complex tasks","Sinh viên thích các nhiệm vụ phức tạp"],["D","Memorization is no longer needed","Việc ghi nhớ không còn cần thiết"]],"a":"B","s":0,"tv":"Tại sao the book emphasize higher-order thinking in online learning?","e":"Surface learning is ineffective for long-term retention and understanding.","ev":"Học hời hợt không hiệu quả cho việc ghi nhớ và hiểu biết lâu dài.","g":"new"},{"id":"SSA101_Q062","t":"Why should encourage combining creative and analytical thinking be encouraged?","o":[["A","They are interchangeable skills and it is possible to replace each other","Chúng là các kỹ năng có thể hoán đổi và thay thế cho nhau"],["B","Creativity generates ideas, while analysis refines them","Sáng tạo tạo ra ý tưởng, còn phân tích tinh chỉnh chúng"],["C","Creativity replaces logic","Sáng tạo thay thế logic"],["D","Analysis limits imagination","Phân tích hạn chế trí tưởng tượng"]],"a":"B","s":0,"tv":"Why should encourage combining creative and tư duy phân tích be encouraged?","e":"Creativity generates ideas, while analysis helps select and refine them.","ev":"Sáng tạo tạo ra ý tưởng, còn phân tích giúp chọn lọc và hoàn thiện chúng.","g":"new"},{"id":"SSA101_Q063","t":"According to the American Library Association (2011), digital literacy primarily refers to the ability to:","o":[["A","Program artificial intelligence systems to get the most productive information system","Lập trình các hệ thống trí tuệ nhân tạo để có hệ thống thông tin hiệu quả nhất"],["B","Use information and communication technologies to find, evaluate, create, and communicate information","Sử dụng công nghệ thông tin và truyền thông để tìm kiếm, đánh giá, tạo ra và truyền đạt thông tin"],["C","Detect AI-generated content","Phát hiện nội dung do AI tạo ra"],["D","Replace human judgment with algorithms","Thay thế phán đoán của con người bằng thuật toán"]],"a":"B","s":0,"tv":"Theo the American Library Association (2011), năng lực kỹ thuật số primarily refers to the ability to:","e":"Digital literacy includes using technology to find, evaluate, create, and communicate information.","ev":"Năng lực số bao gồm việc sử dụng công nghệ để tìm kiếm, đánh giá, tạo và truyền đạt thông tin.","g":"new"},{"id":"SSA101_Q064","t":"According to the chapter, creativity is:","o":[["A","A talent only some people are born with","Một tài năng chỉ một số người bẩm sinh có"],["B","Limited to artistic disciplines","Giới hạn trong các lĩnh vực nghệ thuật"],["C","A skill that can be developed and practiced","Một kỹ năng có thể được phát triển và rèn luyện"],["D","Incompatible with analytical thinking","Không tương thích với tư duy phân tích"]],"a":"C","s":0,"tv":"Theo the chapter, creativity is:","e":"Creativity is a skill that can be practiced and developed through practice.","ev":"Sáng tạo là kỹ năng có thể rèn luyện và phát triển thông qua thực hành.","g":"new"},{"id":"SSA101_Q065","t":"AI can support memory formation primarily by:","o":[["A","Replacing reading and note-taking entirely by provide main content of every document","Thay thế hoàn toàn việc đọc và ghi chép bằng cách cung cấp nội dung chính của mọi tài liệu"],["B","Providing metaphors, emotional connections, and multisensory learning ideas","Cung cấp phép ẩn dụ, liên kết cảm xúc và ý tưởng học tập đa giác quan"],["C","Automatically storing information in long-term memory","Tự động lưu thông tin vào trí nhớ dài hạn"],["D","Eliminating the need for attention and focus","Loại bỏ nhu cầu về sự chú ý và tập trung"]],"a":"B","s":0,"tv":"AI có thể hỗ trợ hình thành trí nhớ chủ yếu bằng cách nào?","e":"AI supports memory by creating emotional connections, images, and multisensory learning.","ev":"AI hỗ trợ ghi nhớ bằng cách tạo liên kết cảm xúc, hình ảnh và nhiều giác quan trong học tập.","g":"new"},{"id":"SSA101_Q066","t":"A student feels overwhelmed during their first semester and avoids contacting professors. Based on Chapter 1, what is the best recommended action?","o":[["A","Focus only on independent study","Chỉ tập trung vào tự học"],["B","Wait until grades are released","Chờ đến khi có điểm"],["C","Seek support from faculty, advisors, and campus resources","Tìm kiếm sự hỗ trợ từ giảng viên, cố vấn và các nguồn lực của trường"],["D","Reduce course load immediately","Giảm ngay khối lượng môn học"]],"a":"C","s":0,"tv":"Một sinh viên cảm thấy quá tải trong học kỳ đầu tiên và tránh liên hệ với giảng viên. Theo Chương 1, hành động được khuyến nghị tốt nhất là gì?","e":"Seeking support from instructors and campus resources helps resolve difficulties more effectively.","ev":"Tìm kiếm sự hỗ trợ từ giảng viên và các nguồn lực trong trường giúp giải quyết khó khăn hiệu quả hơn.","g":"new"},{"id":"SSA101_Q067","t":"A student sends an emotional email to a professor late at night and receives a negative response. Based on Chapter 8, what principle was most likely violated?","o":[["A","Choosing the fastest communication method","Chọn phương thức giao tiếp nhanh nhất"],["B","Considering tone, purpose, and audience before sending","Cân nhắc giọng điệu, mục đích và đối tượng trước khi gửi"],["C","Using complete sentences and formal grammar","Dùng câu hoàn chỉnh và ngữ pháp trang trọng"],["D","Providing sufficient background information","Cung cấp đủ thông tin nền"]],"a":"B","s":0,"tv":"Một sinh viên gửi email đầy cảm xúc cho giảng viên vào đêm muộn và nhận phản hồi tiêu cực. Theo Chương 8, nguyên tắc nào có khả năng bị vi phạm nhất?","e":"Communication requires considering tone, purpose, and audience before sending.","ev":"Khi giao tiếp cần cân nhắc giọng điệu, mục đích và đối tượng nhận trước khi gửi.","g":"new"},{"id":"SSA101_Q068","t":"A student struggles with word problems in math because they focus on every detail. Based on analytical thinking principles, what should they do first?","o":[["A","Practice more similar problems without reflection and revision","Luyện thêm nhiều bài tương tự mà không suy ngẫm và chỉnh sửa"],["B","Identify essential information and ignore irrelevant details","Xác định thông tin thiết yếu và bỏ qua các chi tiết không liên quan"],["C","Memorize formulas more frequently","Ghi nhớ công thức thường xuyên hơn"],["D","Seek help only after failing exams","Chỉ tìm sự giúp đỡ sau khi trượt kỳ thi"]],"a":"B","s":0,"tv":"A student struggles with word problems in math because they focus on every detail. Based on tư duy phân tích principles, what should they do first?","e":"Analytical thinking requires identifying important information and removing unnecessary details.","ev":"Tư duy phân tích yêu cầu xác định thông tin quan trọng và loại bỏ chi tiết không cần thiết.","g":"new"},{"id":"SSA101_Q069","t":"A student fails an exam and immediately blames lack of ability. From a problem-solving perspective, what should the student do instead?","o":[["A","Accept failure and move on, hope for better results","Chấp nhận thất bại và bước tiếp, hy vọng kết quả tốt hơn"],["B","Clearly identify contributing factors and possible changes","Xác định rõ các yếu tố góp phần và những thay đổi có thể thực hiện"],["C","Change majors immediately","Đổi ngành ngay lập tức"],["D","Increase study time without reflection and teamwork","Tăng thời gian học mà không suy ngẫm và làm việc nhóm"]],"a":"B","s":0,"tv":"A student fails an exam and immediately blames lack of ability. From a giải quyết vấn đề perspective, what should the student do instead?","e":"The student should analyze the causes and find ways to improve instead of blaming themselves.","ev":"Cần phân tích nguyên nhân và tìm giải pháp cải thiện thay vì tự trách bản thân.","g":"new"},{"id":"SSA101_Q070","t":"According to the text, a major concern for graduate students regarding AI grading tools is that:","o":[["A","AI grading is smarter than human grading and could overshade human's ability in grading","Chấm điểm bằng AI thông minh hơn con người và có thể lấn át khả năng chấm điểm của con người"],["B","AI systems may use their work as training data, affecting future publication","Hệ thống AI có thể dùng bài làm của họ làm dữ liệu huấn luyện, ảnh hưởng đến việc xuất bản sau này"],["C","AI cannot understand complex arguments","AI không thể hiểu các lập luận phức tạp"],["D","AI always produces biased feedback","AI luôn đưa ra phản hồi thiên kiến"]],"a":"B","s":0,"tv":"Theo the text, a major concern for graduate students regarding AI grading tools is that:","e":"Students worry that their work may be used as AI training data, affecting academic ownership.","ev":"Sinh viên lo ngại bài làm của họ bị dùng làm dữ liệu huấn luyện AI mà ảnh hưởng đến quyền sở hữu học thuật.","g":"new"},{"id":"SSA101_Q071","t":"A student avoids sharing unconventional ideas during group discussions. From a creative thinking perspective, what is the main consequence?","o":[["A","Improved efficiency and diverse forms of idea","Cải thiện hiệu quả và sự đa dạng của ý tưởng"],["B","Reduced originality and idea generation","Giảm tính độc đáo và khả năng tạo ý tưởng"],["C","Stronger analytical reasoning","Lập luận phân tích mạnh hơn"],["D","Clearer communication","Giao tiếp rõ ràng hơn"]],"a":"B","s":0,"tv":"A student avoids sharing unconventional ideas during group discussions. From a tư duy sáng tạo perspective, what is the main consequence?","e":"Reluctance to share new ideas reduces creativity and the number of ideas.","ev":"Việc ngại chia sẻ ý tưởng mới làm giảm tính sáng tạo và số lượng ý tưởng.","g":"new"},{"id":"SSA101_Q072","t":"According to the International Society of Academic Integrity (2021), academic integrity is best defined as:","o":[["A","Compliance with university assessment rules only","Chỉ tuân thủ quy định đánh giá của trường"],["B","A promise to uphold honesty, fairness, respect, responsibility, and courage","Cam kết giữ gìn sự trung thực, công bằng, tôn trọng, trách nhiệm và lòng dũng cảm"],["C","The ability to avoid plagiarism through software tools and institutional policies","Khả năng tránh đạo văn nhờ công cụ phần mềm và chính sách của nhà trường"],["D","A system of penalties designed to discourage cheating and misconduct","Một hệ thống hình phạt nhằm ngăn chặn gian lận và hành vi sai trái"]],"a":"B","s":0,"tv":"Theo the International Society of liêm chính học thuật (2021), liêm chính học thuật is best defined as:","e":"Academic integrity is based on honesty, fairness, respect, and responsibility.","ev":"Liêm chính học thuật dựa trên các giá trị trung thực, công bằng, tôn trọng và trách nhiệm.","g":"new"},{"id":"SSA101_Q073","t":"According to the chapter, the primary goal of learning is to:","o":[["A","Complete assignments as efficiently as possible using available tools","Hoàn thành bài tập hiệu quả nhất có thể bằng các công cụ sẵn có"],["B","Distill knowledge and skills so they can be applied in new situations","Chắt lọc kiến thức và kỹ năng để có thể áp dụng vào những tình huống mới"],["C","Memorize large amounts of information for examinations","Ghi nhớ lượng lớn thông tin cho kỳ thi"],["D","Reduce cognitive effort through automation and technological support","Giảm nỗ lực nhận thức thông qua tự động hóa và hỗ trợ công nghệ"]],"a":"B","s":0,"tv":"Theo the chapter, the primary goal of learning is to:","e":"Learning aims to develop knowledge and skills that can be applied in new situations.","ev":"Học tập nhằm phát triển kiến thức và kỹ năng có thể áp dụng vào tình huống mới.","g":"new"},{"id":"SSA101_Q074","t":"According to Chapter 7, analytical thinking primarily involves:","o":[["A","Generating original ideas through imagination and brainstorming techniques","Tạo ra ý tưởng độc đáo bằng trí tưởng tượng và các kỹ thuật động não"],["B","Breaking information into components to understand relationships and patterns","Chia thông tin thành các thành phần để hiểu các mối quan hệ và mô hình"],["C","Evaluating arguments based on personal beliefs and values","Đánh giá lập luận dựa trên niềm tin và giá trị cá nhân"],["D","Solving problems through trial and error without structured steps","Giải quyết vấn đề bằng thử và sai mà không có các bước có cấu trúc"]],"a":"B","s":0,"tv":"Theo Chapter 7, tư duy phân tích primarily involves:","e":"Analytical thinking breaks information into parts to understand their relationships and patterns.","ev":"Tư duy phân tích là chia nhỏ thông tin để hiểu mối liên hệ và quy luật giữa các phần.","g":"new"},{"id":"SSA101_Q075","t":"A student finds an article that supports their argument but is written by an anonymous author on a personal blog. Based on Chapter 7, what should the student do first?","o":[["A","Use the article because it supports the claim","Sử dụng bài báo vì nó ủng hộ luận điểm"],["B","Evaluate the author's credibility and evidence provided","Đánh giá độ tin cậy của tác giả và bằng chứng được đưa ra"],["C","Replace it with any academic article because journal articles are qualified","Thay bằng bất kỳ bài báo học thuật nào vì bài tạp chí đủ chuẩn"],["D","Ignore online sources entirely","Bỏ qua hoàn toàn các nguồn trực tuyến"]],"a":"B","s":0,"tv":"Một sinh viên tìm thấy một bài viết ủng hộ lập luận của mình nhưng được viết bởi một tác giả ẩn danh trên blog cá nhân. Dựa trên Chương 7, trước tiên sinh viên nên làm gì?","e":"Critical thinking requires evaluating the author's credibility and evidence before using a source.","ev":"Tư duy phản biện yêu cầu đánh giá độ tin cậy của tác giả và bằng chứng trước khi sử dụng nguồn thông tin.","g":"new"},{"id":"SSA101_Q076","t":"Creative thinking is described in as the ability to:","o":[["A","Follow established rules precisely","Tuân theo các quy tắc đã định một cách chính xác"],["B","Produce original ideas by making new connections","Tạo ra ý tưởng độc đáo bằng cách tạo kết nối mới"],["C","Evaluate information objectively and systematically","Đánh giá thông tin một cách khách quan và có hệ thống"],["D","Solve problems using fixed procedures","Giải quyết vấn đề bằng các quy trình cố định"]],"a":"B","s":0,"tv":"tư duy sáng tạo is described in as the ability to:","e":"Creative thinking focuses on generating new ideas by connecting different ideas.","ev":"Tư duy sáng tạo tập trung vào việc tạo ra ý tưởng mới thông qua liên kết các ý tưởng khác nhau.","g":"new"},{"id":"SSA101_Q077","t":"Chapter 7 emphasizes that critical thinking requires students to:","o":[["A","Avoid questioning authority and forms of powers","Tránh đặt câu hỏi về uy quyền và các hình thức quyền lực"],["B","Consider multiple perspectives before judging","Xem xét nhiều góc nhìn trước khi đánh giá"],["C","Focus on speed rather than accuracy","Tập trung vào tốc độ hơn độ chính xác"],["D","Rely on intuition","Dựa vào trực giác"]],"a":"B","s":0,"tv":"Chapter 7 emphasizes that tư duy phản biện requires students to:","e":"Critical thinking requires considering multiple perspectives before reaching a conclusion.","ev":"Tư duy phản biện đòi hỏi xem xét nhiều góc nhìn trước khi đưa ra kết luận.","g":"new"},{"id":"SSA101_Q078","t":"Communication is best described as:","o":[["A","A simple exchange of spoken words","Một sự trao đổi lời nói đơn giản"],["B","A one-way transfer of information and signals from sender to receiver","Sự truyền thông tin và tín hiệu một chiều từ người gửi đến người nhận"],["C","A complex process influenced by context, purpose, and participants","Một quá trình phức tạp chịu ảnh hưởng của bối cảnh, mục đích và những người tham gia"],["D","A skill used primarily in professional environments","Một kỹ năng chủ yếu dùng trong môi trường chuyên nghiệp"]],"a":"C","s":0,"tv":"Giao tiếp được mô tả chính xác nhất là:","e":"Communication is a complex process influenced by context, purpose, and participants.","ev":"Giao tiếp là một quá trình phức tạp chịu ảnh hưởng bởi bối cảnh, mục đích và người tham gia.","g":"new"},{"id":"SSA101_Q079","t":"Digital literacy is described as important because it:","o":[["A","Is only useful for students in technology majors","Chỉ hữu ích cho sinh viên ngành công nghệ"],["B","Helps individuals critically evaluate online content","Giúp mọi người đánh giá nội dung trực tuyến một cách có phê phán"],["C","Removes the need for critical thinking and metacognition","Loại bỏ nhu cầu tư duy phản biện và siêu nhận thức"],["D","Guarantees employment","Đảm bảo có việc làm"]],"a":"B","s":0,"tv":"năng lực kỹ thuật số is described as important because it:","e":"Digital literacy helps users selectively and critically evaluate online content.","ev":"Năng lực số giúp người dùng đánh giá nội dung trực tuyến một cách có chọn lọc và phản biện.","g":"new"},{"id":"SSA101_Q080","t":"Effective time management in college is important primarily because it:","o":[["A","Reduces the total number of assignments students receive","Giảm tổng số bài tập sinh viên nhận được"],["B","Helps prevent a chain reaction of academic problems","Giúp ngăn chặn phản ứng dây chuyền các vấn đề học tập"],["C","Allows students to finish college more quickly","Cho phép sinh viên tốt nghiệp nhanh hơn"],["D","Eliminates the need for prioritization","Loại bỏ nhu cầu ưu tiên"]],"a":"B","s":0,"tv":"Effective quản lý thời gian in college is important primarily because it:","e":"Good time management helps prevent delays from causing a series of academic problems.","ev":"Quản lý thời gian tốt giúp tránh việc chậm trễ dẫn đến hàng loạt vấn đề học tập.","g":"new"},{"id":"SSA101_Q081","t":"Guerrero-Dib, Portales, and Heredia-Escorza (2020) emphasize that academic integrity extends beyond cheating because it:","o":[["A","Focuses solely on punishment and enforcement","Chỉ tập trung vào trừng phạt và thực thi"],["B","Represents a commitment to the learning process and ethical use of resources","Thể hiện cam kết với quá trình học tập và sử dụng nguồn lực một cách có đạo đức"],["C","Is mainly concerned with citation formatting and application of formal structure","Chủ yếu quan tâm đến định dạng trích dẫn và áp dụng cấu trúc hình thức"],["D","Applies only to written assignments","Chỉ áp dụng cho bài tập viết"]],"a":"B","s":0,"tv":"Guerrero-Dib, Portales, and Heredia-Escorza (2020) emphasize that liêm chính học thuật extends beyond cheating because it:","e":"Academic integrity shows commitment to learning and the ethical use of resources.","ev":"Trung thực học thuật thể hiện cam kết với quá trình học tập và việc sử dụng tài nguyên một cách đạo đức.","g":"new"},{"id":"SSA101_Q082","t":"Information literacy is defined as the ability to:","o":[["A","Memorize academic content efficiently","Ghi nhớ nội dung học thuật hiệu quả"],["B","Locate, evaluate, and use information effectively","Xác định vị trí, đánh giá và sử dụng thông tin một cách hiệu quả"],["C","Rely on digital sources for research and study","Dựa vào các nguồn số để nghiên cứu và học tập"],["D","Avoid biased information entirely and consistently","Tránh hoàn toàn thông tin thiên kiến một cách nhất quán"]],"a":"B","s":0,"tv":"năng lực thông tin is defined as the ability to:","e":"Information literacy is the ability to find, evaluate, and use information effectively.","ev":"Năng lực thông tin là khả năng tìm kiếm, đánh giá và sử dụng thông tin hiệu quả.","g":"new"},{"id":"SSA101_Q083","t":"Metacognition is best defined as","o":[["A","Thinking critically about academic content","Suy nghĩ phản biện về nội dung học thuật"],["B","Awareness and regulation of one's own thinking and learning","Nhận thức và điều chỉnh tư duy và việc học của chính mình"],["C","Memorizing information efficiently","Ghi nhớ thông tin hiệu quả"],["D","Monitoring other students' performance","Theo dõi kết quả của các sinh viên khác"]],"a":"B","s":0,"tv":"Siêu nhận thức được định nghĩa chính xác nhất là:","e":"Metacognition is the ability to recognize and regulate one's own thinking and learning.","ev":"Siêu nhận thức là khả năng nhận thức và điều chỉnh quá trình suy nghĩ và học tập của bản thân.","g":"new"},{"id":"SSA101_Q084","t":"Metacognition helps students mainly by:","o":[["A","Increasing intelligence","Tăng trí thông minh"],["B","Making learning automatic","Làm cho việc học trở nên tự động"],["C","Allowing learners to adjust strategies intentionally","Cho phép người học chủ động điều chỉnh chiến lược"],["D","Reducing academic workload","Giảm khối lượng học tập"]],"a":"C","s":0,"tv":"Siêu nhận thức chủ yếu giúp sinh viên bằng cách:","e":"Metacognition helps learners actively adjust their learning strategies for better results.","ev":"Siêu nhận thức giúp người học chủ động điều chỉnh chiến lược học tập để đạt hiệu quả tốt hơn.","g":"new"},{"id":"SSA101_Q085","t":"One ethical concern about using AI as a grading tool is that it may:","o":[["A","Improve consistency too much","Cải thiện tính nhất quán quá mức"],["B","Breach students' intellectual property by uploading their work to AI systems","Xâm phạm quyền sở hữu trí tuệ của sinh viên bằng cách tải bài làm lên hệ thống AI"],["C","Reduce grading speed","Giảm tốc độ chấm điểm"],["D","Require excessive faculty training","Đòi hỏi đào tạo giảng viên quá mức"]],"a":"B","s":0,"tv":"Một mối lo ngại về đạo đức khi sử dụng AI như một công cụ chấm điểm là nó có thể:","e":"Uploading students' work to AI systems can create risks to intellectual property and privacy.","ev":"Việc tải bài làm của sinh viên lên hệ thống AI có thể gây rủi ro về quyền sở hữu trí tuệ và quyền riêng tư.","g":"new"},{"id":"SSA101_Q086","t":"Problem-solving is best described as:","o":[["A","Finding the quickest answer to a difficulty","Tìm câu trả lời nhanh nhất cho một khó khăn"],["B","Applying a structured process to address challenges","Áp dụng một quy trình có cấu trúc để giải quyết thách thức"],["C","Relying on intuition and experience to address normal issues","Dựa vào trực giác và kinh nghiệm để giải quyết các vấn đề thông thường"],["D","Avoiding situations that seem complex","Tránh các tình huống có vẻ phức tạp"]],"a":"B","s":0,"tv":"giải quyết vấn đề is best described as:","e":"Effective problem-solving requires a clear logical process instead of relying only on intuition.","ev":"Giải quyết vấn đề hiệu quả cần có quy trình logic và rõ ràng thay vì chỉ dựa vào trực giác.","g":"new"},{"id":"SSA101_Q087","t":"Procrastination is described as:","o":[["A","A harmless habit with minimal consequences that students usually have","Một thói quen vô hại với hậu quả tối thiểu mà sinh viên thường có"],["B","A delay that can trigger multiple academic difficulties","Sự trì hoãn có thể gây ra nhiều khó khăn trong học tập"],["C","A strategy for managing stress effectively","Một chiến lược quản lý căng thẳng hiệu quả"],["D","A result of excessive motivation","Kết quả của động lực quá mức"]],"a":"B","s":0,"tv":"Sự trì hoãn được mô tả là:","e":"Procrastination can cause academic difficulties such as deadline pressure and reduced performance.","ev":"Trì hoãn có thể dẫn đến nhiều khó khăn học tập như áp lực deadline và giảm hiệu suất.","g":"new"},{"id":"SSA101_Q088","t":"Problem-solving is described as:","o":[["A","Finding the fastest solution available based on A.I suggestion","Tìm giải pháp nhanh nhất có sẵn dựa trên gợi ý của AI"],["B","Applying a structured process to address challenges","Áp dụng một quy trình có cấu trúc để giải quyết thách thức"],["C","Using intuition to make decisions","Dùng trực giác để ra quyết định"],["D","Avoiding complex situations","Tránh các tình huống phức tạp"]],"a":"B","s":0,"tv":"giải quyết vấn đề is described as:","e":"Problem-solving requires a structured approach to find an appropriate solution.","ev":"Giải quyết vấn đề cần cách tiếp cận có cấu trúc để tìm ra giải pháp phù hợp.","g":"new"},{"id":"SSA101_Q089","t":"Studying in college often requires students to:","o":[["A","Study only before exams","Chỉ học trước kỳ thi"],["B","Modify old habits to meet new academic demands","Điều chỉnh thói quen cũ để đáp ứng yêu cầu học tập mới"],["C","Depend on memorization alone","Chỉ phụ thuộc vào việc ghi nhớ"],["D","Avoid collaborative learning","Tránh học tập hợp tác"]],"a":"B","s":0,"tv":"Việc học ở đại học thường yêu cầu sinh viên phải:","e":"The college environment requires students to change study habits to adapt to new demands.","ev":"Môi trường đại học đòi hỏi sinh viên thay đổi thói quen học tập để thích nghi với yêu cầu mới.","g":"new"},{"id":"SSA101_Q090","t":"The concept of \"hallucination\" in AI refers to:","o":[["A","Visual misinterpretation by humans","Sự hiểu sai về thị giác của con người"],["B","AI producing incorrect or fabricated information","AI tạo ra thông tin sai hoặc bịa đặt"],["C","Emotional responses to AI feedback","Phản ứng cảm xúc với phản hồi của AI"],["D","Errors caused only by user prompts","Lỗi chỉ do câu lệnh của người dùng gây ra"]],"a":"B","s":0,"tv":"Khái niệm “hallucination” trong AI đề cập đến:","e":"Hallucination occurs when AI creates false or fabricated information but presents it as factual.","ev":"“Hallucination” là khi AI tạo ra thông tin sai hoặc bịa đặt nhưng trình bày như đúng sự thật.","g":"new"},{"id":"SSA101_Q091","t":"Employers value analytical thinkers because they:","o":[["A","Work alone confidently and work with AI effectively","Làm việc một mình tự tin và làm việc với AI hiệu quả"],["B","Use logical thinking to solve issues","Dùng tư duy logic để giải quyết vấn đề"],["C","Avoid workplace conflict","Tránh xung đột nơi làm việc"],["D","Prefer routine tasks","Thích các công việc lặp đi lặp lại"]],"a":"B","s":0,"tv":"Nhà tuyển dụng đánh giá cao những người có tư duy phân tích vì họ:","g":"new","e":"Employers value analytical thinkers because they use logical reasoning to break down and solve workplace problems.","ev":"Nhà tuyển dụng đánh giá cao người có tư duy phân tích vì họ dùng lập luận logic để phân tích và giải quyết các vấn đề trong công việc."},{"id":"SSA101_Q092","t":"Analytical thinking is commonly used when:","o":[["A","Writing poetry only","Chỉ khi viết thơ"],["B","Solving complex problems","Khi giải quyết các vấn đề phức tạp"],["C","Avoiding decisions","Khi tránh việc ra quyết định"],["D","Relaxing","Khi thư giãn"]],"a":"B","s":0,"tv":"tư duy phân tích is commonly used when:","g":"new","e":"Analytical thinking is used to break complex problems into parts so they can be understood and solved.","ev":"Tư duy phân tích được dùng để chia vấn đề phức tạp thành các phần nhỏ để hiểu và giải quyết."},{"id":"SSA101_Q093","t":"Amazon is significantly successful business based in analytical thinking, which of the following is a sign of applying analytical thinking?","o":[["A","Intuition","Trực giác"],["B","Hyper organization","Tổ chức cực kỳ chặt chẽ"],["C","Random processes","Các quy trình ngẫu nhiên"],["D","Individual memory","Trí nhớ cá nhân"]],"a":"B","s":0,"tv":"Amazon is significantly successful business based in tư duy phân tích, which of the following is a sign of applying tư duy phân tích?","g":"new","e":"Amazon's success relies on highly organized, data-driven systems, a sign of analytical thinking.","ev":"Thành công của Amazon dựa trên các hệ thống được tổ chức chặt chẽ và dựa trên dữ liệu, đây là dấu hiệu của tư duy phân tích."},{"id":"SSA101_Q094","t":"What is time management?","o":[["A","Controlling others","Kiểm soát người khác"],["B","Planning time use","Lập kế hoạch sử dụng thời gian"],["C","Working randomly","Làm việc ngẫu nhiên"],["D","Avoiding tasks and responsibilities","Tránh nhiệm vụ và trách nhiệm"]],"a":"B","s":0,"tv":"What is quản lý thời gian?","g":"new","e":"Time management means planning how you use your time to get tasks done effectively.","ev":"Quản lý thời gian là lập kế hoạch cách sử dụng thời gian để hoàn thành công việc hiệu quả."},{"id":"SSA101_Q095","t":"Which of the following best represents an effective use of a planner?","o":[["A","Recording deadlines after they pass","Ghi lại hạn chót sau khi chúng đã qua"],["B","Scheduling tasks without estimating duration","Lên lịch công việc mà không ước lượng thời lượng"],["C","Planning tasks while considering priorities and time-on-task","Lập kế hoạch công việc có cân nhắc mức ưu tiên và thời gian thực hiện"],["D","Using it during exam weeks to cram knowledge in a short period of time","Dùng nó vào tuần thi để nhồi kiến thức trong thời gian ngắn"]],"a":"C","s":0,"tv":"Điều nào sau đây thể hiện việc sử dụng sổ kế hoạch (planner) hiệu quả nhất?","g":"new","e":"An effective planner is used to schedule tasks by considering priorities and how long each task will actually take.","ev":"Sổ kế hoạch được dùng hiệu quả khi lên lịch công việc có tính đến mức ưu tiên và thời gian thực tế mỗi việc cần."},{"id":"SSA101_Q096","t":"What is scheduling?","o":[["A","Ignoring time","Phớt lờ thời gian"],["B","Planning activities","Lập kế hoạch các hoạt động"],["C","Avoiding tasks","Tránh nhiệm vụ"],["D","Doing tasks randomly without any structure or order","Làm việc ngẫu nhiên không có cấu trúc hay thứ tự"]],"a":"B","s":0,"tv":"Scheduling là gì?","g":"new","e":"Scheduling is planning when activities will take place.","ev":"Lập lịch là lên kế hoạch thời điểm thực hiện các hoạt động."},{"id":"SSA101_Q097","t":"What tool helps prioritize tasks?","o":[["A","Calendar only","Chỉ dùng lịch"],["B","Priority list","Danh sách ưu tiên"],["C","Social media","Mạng xã hội"],["D","Email inbox","Hộp thư email"]],"a":"B","s":0,"tv":"Công cụ nào giúp ưu tiên các công việc?","g":"new","e":"A priority list ranks tasks by importance, which helps decide what to do first.","ev":"Danh sách ưu tiên xếp hạng công việc theo mức độ quan trọng, giúp quyết định việc nào làm trước."},{"id":"SSA101_Q098","t":"A student spends hours on low-priority tasks. What is the issue?","o":[["A","Good planning","Lập kế hoạch tốt"],["B","High productivity","Năng suất cao"],["C","Poor prioritization","Ưu tiên kém"],["D","Effective scheduling","Lập lịch hiệu quả"]],"a":"C","s":0,"tv":"Một sinh viên dành nhiều giờ cho các công việc có mức ưu tiên thấp. Vấn đề là gì?","g":"new","e":"Spending hours on low-priority tasks shows poor prioritization of what matters most.","ev":"Dành hàng giờ cho việc ít quan trọng cho thấy việc xác định thứ tự ưu tiên kém."},{"id":"SSA101_Q099","t":"What is \"keyword searching\"?","o":[["A","Writing essays","Viết tiểu luận"],["B","Reading books strategically","Đọc sách có chiến lược"],["C","Using key terms","Sử dụng các từ khóa"],["D","Copying text","Sao chép văn bản"]],"a":"C","s":0,"tv":"\"Keyword searching\" là gì?","g":"new","e":"Keyword searching means using key terms to find relevant information.","ev":"Tìm kiếm theo từ khóa là sử dụng các từ khóa chính để tìm thông tin liên quan."},{"id":"SSA101_Q100","t":"What is information literacy?","o":[["A","Reading and present articles professionally","Đọc và trình bày bài báo một cách chuyên nghiệp"],["B","Evaluating information","Đánh giá thông tin"],["C","Memorizing data","Ghi nhớ dữ liệu"],["D","Copying content","Sao chép nội dung"]],"a":"B","s":0,"tv":"What is năng lực thông tin?","g":"new","e":"Information literacy is the ability to find, evaluate and use information.","ev":"Hiểu biết thông tin là khả năng tìm kiếm, đánh giá và sử dụng thông tin."},{"id":"SSA101_Q101","t":"Why is problem-solving linked with other thinking skills?","o":[["A","Problem-solving replaces analytical thinking and creative thinking","Giải quyết vấn đề thay thế tư duy phân tích và tư duy sáng tạo"],["B","Effective problem-solving integrates multiple types of thinking","Giải quyết vấn đề hiệu quả kết hợp nhiều loại tư duy"],["C","Creative thinking interferes with problem-solving","Tư duy sáng tạo cản trở việc giải quyết vấn đề"],["D","Critical thinking is unnecessary","Tư duy phản biện là không cần thiết"]],"a":"B","s":0,"tv":"Tại sao giải quyết vấn đề linked with other thinking skills?","g":"new","e":"Effective problem-solving combines analytical, creative and critical thinking rather than relying on one.","ev":"Giải quyết vấn đề hiệu quả kết hợp tư duy phân tích, sáng tạo và phản biện chứ không dựa vào riêng một loại."},{"id":"SSA101_Q102","t":"Reviewing results after solving a problem helps students:","o":[["A","Assign blame to less responsible person","Đổ lỗi cho người ít trách nhiệm hơn"],["B","Improve future problem-solving efforts","Cải thiện nỗ lực giải quyết vấn đề trong tương lai"],["C","Prove effort was sufficient to solve any problem","Chứng minh nỗ lực đủ để giải quyết mọi vấn đề"],["D","Avoid repeating tasks","Tránh lặp lại các nhiệm vụ"]],"a":"B","s":0,"tv":"Việc xem xét lại kết quả sau khi giải quyết một vấn đề giúp sinh viên:","g":"new","e":"Reviewing results shows what worked and what did not, so future problem-solving improves.","ev":"Xem lại kết quả cho thấy điều gì hiệu quả và điều gì không, nhờ đó việc giải quyết vấn đề sau này tốt hơn."},{"id":"SSA101_Q103","t":"Why is flexibility important in problem-solving?","o":[["A","Problems rarely change once identified","Các vấn đề hiếm khi thay đổi sau khi được xác định"],["B","Initial solutions may not fully address the problem","Các giải pháp ban đầu có thể chưa giải quyết hết vấn đề"],["C","Flexibility reduces accountability","Sự linh hoạt làm giảm trách nhiệm giải trình"],["D","It saves time in decision-making","Nó tiết kiệm thời gian ra quyết định"]],"a":"B","s":0,"tv":"Tại sao flexibility important in giải quyết vấn đề?","g":"new","e":"Flexibility matters because the first solution may not fully solve the problem and may need adjusting.","ev":"Sự linh hoạt quan trọng vì giải pháp đầu tiên có thể chưa giải quyết trọn vẹn vấn đề và cần điều chỉnh."},{"id":"SSA101_Q104","t":"What is clarity in communication?","o":[["A","Long and complex sentences","Những câu dài và phức tạp"],["B","Beautiful and eloquent language","Ngôn ngữ đẹp và hùng biện"],["C","Easy understanding","Dễ hiểu"],["D","Repetition and emphasizing","Lặp lại và nhấn mạnh"]],"a":"C","s":0,"tv":"Sự rõ ràng trong giao tiếp là gì?","g":"new","e":"Clarity in communication means the message is easy to understand.","ev":"Sự rõ ràng trong giao tiếp nghĩa là thông điệp dễ hiểu."},{"id":"SSA101_Q105","t":"Which of the following best reflects the relationship between digital literacy and human agency?","o":[["A","Digital literacy reduces personal responsibility","Kỹ năng số làm giảm trách nhiệm cá nhân"],["B","Algorithms fully determine human choices and thinking process","Thuật toán hoàn toàn quyết định lựa chọn và quá trình suy nghĩ của con người"],["C","Digital literacy helps individuals navigate algorithmic influence","Kỹ năng số giúp mọi người ứng phó với ảnh hưởng của thuật toán"],["D","Human agency is irrelevant in digital environments","Quyền chủ động của con người không liên quan trong môi trường số"]],"a":"C","s":0,"tv":"Which of the following best reflects the relationship between năng lực kỹ thuật số and human agency?","g":"new","e":"Digital literacy helps people understand and navigate the influence of algorithms, keeping human agency.","ev":"Kỹ năng số giúp con người hiểu và ứng phó với ảnh hưởng của thuật toán, giữ được quyền chủ động."},{"id":"SSA101_Q106","t":"Which term describes AI systems producing incorrect or fabricated information?","o":[["A","Automation","Tự động hóa"],["B","Optimization","Tối ưu hóa"],["C","Hallucination","Ảo giác"],["D","Simulation","Mô phỏng"]],"a":"C","s":0,"tv":"Thuật ngữ nào mô tả việc hệ thống AI tạo ra thông tin sai hoặc bịa đặt?","g":"new","e":"A hallucination is when an AI system produces incorrect or fabricated information.","ev":"Ảo giác (hallucination) là khi hệ thống AI tạo ra thông tin sai hoặc bịa đặt."},{"id":"SSA101_Q107","t":"Which AI-supported strategy best aligns with improving memory storage?","o":[["A","Asking AI to summarize a chapter and skipping the reading","Nhờ AI tóm tắt một chương và bỏ qua việc đọc"],["B","Using AI to plan spaced practice after understanding the material","Dùng AI để lập kế hoạch luyện tập giãn cách sau khi đã hiểu tài liệu"],["C","Letting AI answer practice questions and remember the answer list","Để AI trả lời câu hỏi luyện tập rồi ghi nhớ danh sách đáp án"],["D","Relying on AI-generated notes only","Chỉ dựa vào ghi chú do AI tạo"]],"a":"B","s":0,"tv":"Chiến lược hỗ trợ bởi AI nào phù hợp nhất để cải thiện khả năng ghi nhớ?","g":"new","e":"Spaced practice helps store information in memory, and AI is best used to plan it after you understand the material.","ev":"Luyện tập giãn cách giúp lưu thông tin vào trí nhớ, và AI nên dùng để lập kế hoạch này sau khi bạn đã hiểu tài liệu."},{"id":"SSA101_Q108","t":"Which of the following principle could best guides ethical student use of AI?","o":[["A","Use AI whenever it saves time and when you are too busy","Dùng AI bất cứ khi nào tiết kiệm thời gian và khi bạn quá bận"],["B","Use AI to support learning goals, not replace them","Dùng AI để hỗ trợ mục tiêu học tập, không thay thế chúng"],["C","Avoid AI entirely in higher education because it causes more harm than benefit","Tránh hoàn toàn AI trong giáo dục đại học vì nó gây hại nhiều hơn lợi"],["D","Use AI only for graded tasks","Chỉ dùng AI cho các bài có chấm điểm"]],"a":"B","s":0,"tv":"Nguyên tắc nào hướng dẫn tốt nhất việc sử dụng AI một cách có đạo đức của sinh viên?","g":"new","e":"Ethical use of AI means supporting your learning goals, not replacing your own learning.","ev":"Dùng AI có đạo đức là để hỗ trợ mục tiêu học tập của bạn, không thay thế việc tự học."},{"id":"SSA101_Q109","t":"Why is using AI to complete assignments unethical?","o":[["A","It takes too much time","Nó tốn quá nhiều thời gian"],["B","It replaces the intended learning process","Nó thay thế quá trình học tập vốn có"],["C","It requires technical skills","Nó đòi hỏi kỹ năng kỹ thuật"],["D","It reduces collaboration and social learning","Nó làm giảm hợp tác và học tập xã hội"]],"a":"B","s":0,"tv":"Tại sao using AI to complete assignments unethical?","g":"new","e":"Using AI to complete assignments replaces the learning process the assignment is meant to build.","ev":"Dùng AI để làm bài tập thay thế quá trình học tập mà bài tập đó nhằm xây dựng."},{"id":"SSA101_Q110","t":"A student skips classes but studies alone. What is the likely issue?","o":[["A","Too much collaboration","Hợp tác quá nhiều"],["B","Low behavioral engagement","Mức độ tham gia về hành vi thấp"],["C","Overconfidence","Quá tự tin"],["D","Excessive motivation","Động lực quá mức"]],"a":"B","s":0,"tv":"Một sinh viên bỏ học trên lớp nhưng tự học một mình. Vấn đề có khả năng xảy ra là gì?","g":"new","e":"Skipping classes shows low behavioral engagement, even if the student studies alone.","ev":"Bỏ học cho thấy mức độ tham gia về hành vi thấp, dù sinh viên tự học một mình."},{"id":"SSA101_Q111","t":"A student reads the syllabus carefully and plans ahead. This shows:","o":[["A","Passive learning","Học thụ động"],["B","Avoidance behavior","Hành vi né tránh"],["C","Self-management","Tự quản lý bản thân"],["D","Dependence on teachers","Phụ thuộc vào giáo viên"]],"a":"C","s":0,"tv":"Một sinh viên đọc kỹ đề cương môn học và lập kế hoạch trước. Điều này thể hiện:","g":"new","e":"Reading the syllabus and planning ahead is self-management.","ev":"Đọc kỹ đề cương và lập kế hoạch trước là biểu hiện của tự quản lý bản thân."},{"id":"SSA101_Q112","t":"Which term describes taking responsibility for your own learning?","o":[["A","Passive learning","Học thụ động"],["B","Academic ownership","Quyền làm chủ việc học"],["C","External motivation","Động lực bên ngoài"],["D","Teacher-led learning systems","Hệ thống học tập do giáo viên dẫn dắt"]],"a":"B","s":0,"tv":"Thuật ngữ nào mô tả việc chịu trách nhiệm đối với việc học của chính mình?","g":"new","e":"Academic ownership means taking responsibility for your own learning.","ev":"Quyền làm chủ việc học (academic ownership) nghĩa là tự chịu trách nhiệm cho việc học của mình."},{"id":"SSA101_Q113","t":"A student studies extensively but keeps failing quizzes. From a metacognitive perspective, what is the most likely issue?","o":[["A","Lack of motivation","Thiếu động lực"],["B","Poor time management","Quản lý thời gian kém"],["C","Ineffective study strategies not being evaluated","Các chiến lược học không hiệu quả mà không được đánh giá"],["D","Insufficient intelligence","Không đủ thông minh"]],"a":"C","s":0,"tv":"Một sinh viên học rất nhiều nhưng vẫn liên tục làm bài kiểm tra không tốt. Theo góc nhìn siêu nhận thức (metacognition), nguyên nhân có khả năng nhất là gì?","g":"new","e":"The student studies a lot but never evaluates whether the study strategies work, a metacognitive gap.","ev":"Sinh viên học nhiều nhưng không đánh giá xem chiến lược học có hiệu quả không, đó là thiếu sót về siêu nhận thức."},{"id":"SSA101_Q114","t":"Mark Twain compared idea generation to:","o":[["A","A journey","Một hành trình"],["B","A kaleidoscope","Một chiếc kính vạn hoa"],["C","A puzzle","Một trò xếp hình"],["D","A dream-making machine","Một cỗ máy tạo giấc mơ"]],"a":"B","s":0,"tv":"Mark Twain đã so sánh quá trình tạo ý tưởng với điều gì?","g":"new","e":"Mark Twain compared idea generation to a kaleidoscope, which recombines old pieces into new patterns.","ev":"Mark Twain ví việc tạo ý tưởng như một chiếc kính vạn hoa, kết hợp lại các mảnh cũ thành hình mẫu mới."},{"id":"SSA101_Q115","t":"Tracking ideas enhances creativity because it:","o":[["A","Eliminates imagination","Loại bỏ trí tưởng tượng"],["B","Preserves inspiration","Lưu giữ cảm hứng"],["C","Avoids reflection and conclusion","Tránh suy ngẫm và kết luận"],["D","Reduces novelty","Giảm tính mới mẻ"]],"a":"B","s":0,"tv":"Việc ghi lại các ý tưởng giúp tăng khả năng sáng tạo vì:","g":"new","e":"Tracking ideas preserves inspiration so you can return to and build on them later.","ev":"Ghi lại ý tưởng giúp giữ cảm hứng để sau này quay lại và phát triển thêm."},{"id":"SSA101_Q116","t":"What is the key advantage of short, regular study sessions?","o":[["A","Less effort is required","Cần ít nỗ lực hơn"],["B","Information is memorized faster","Thông tin được ghi nhớ nhanh hơn"],["C","Focus and retention are improved","Cải thiện sự tập trung và khả năng ghi nhớ"],["D","Assignments become easier and more motivational","Bài tập trở nên dễ hơn và có động lực hơn"]],"a":"C","s":0,"tv":"Lợi ích chính của những buổi học ngắn nhưng đều đặn là gì?","g":"new","e":"Short, regular sessions improve focus and retention compared with long cramming sessions.","ev":"Các buổi học ngắn và đều đặn cải thiện sự tập trung và khả năng ghi nhớ so với học nhồi dài."},{"id":"SSA101_Q118","t":"What is encoding in memory?","o":[["A","Forgetting information","Quên thông tin"],["B","Converting information for storage in memory","Chuyển đổi thông tin để lưu trữ vào trí nhớ"],["C","Repeating words and image","Lặp lại từ ngữ và hình ảnh"],["D","Skipping details","Bỏ qua chi tiết"]],"a":"B","s":0,"tv":"Mã hóa (encoding) trong trí nhớ là gì?","g":"new","e":"Encoding converts information into a form that can be stored in memory.","ev":"Mã hóa là chuyển thông tin sang dạng có thể lưu vào trí nhớ."},{"id":"SSA101_Q119","t":"What is the primary benefit of reviewing graded tests?","o":[["A","Improving GPA immediately","Cải thiện điểm trung bình ngay lập tức"],["B","Identifying grading errors","Xác định lỗi chấm điểm"],["C","Strengthening understanding and memory","Củng cố sự hiểu biết và trí nhớ"],["D","Reducing study time and have more fun if practicing with friends","Giảm thời gian học và vui hơn nếu luyện tập với bạn bè"]],"a":"C","s":0,"tv":"Lợi ích chính của việc xem lại các bài kiểm tra đã được chấm điểm là gì?","g":"new","e":"Reviewing graded tests strengthens understanding and memory by showing which mistakes to fix.","ev":"Xem lại bài kiểm tra đã chấm củng cố sự hiểu biết và trí nhớ vì cho thấy cần sửa những lỗi nào."},{"id":"SSA101_Q120","t":"Why are AI detection tools controversial in academic settings?","o":[["A","They could replace teachers in learning any knowledge","Chúng có thể thay thế giáo viên trong việc dạy mọi kiến thức"],["B","They are difficult to install","Chúng khó cài đặt"],["C","They are rarely used productively","Chúng hiếm khi được sử dụng hiệu quả"],["D","They may produce inaccurate results and false accusations","Chúng có thể cho kết quả không chính xác và buộc tội sai"]],"a":"D","s":0,"tv":"Tại sao các công cụ phát hiện AI lại gây tranh cãi trong môi trường học thuật?","g":"new","e":"AI detection tools are controversial because they can give inaccurate results and cause false accusations.","ev":"Công cụ phát hiện AI gây tranh cãi vì có thể cho kết quả không chính xác và dẫn đến buộc tội sai."},{"id":"SSA101_Q121","t":"Which institutional response best aligns with the ethical approach advocated in the text?","o":[["A","Developing clear AI usage policies and promoting transparency","Xây dựng chính sách sử dụng AI rõ ràng và thúc đẩy sự minh bạch"],["B","Banning all AI tools immediately because AI will destroy students' independent thinking","Cấm ngay lập tức mọi công cụ AI vì AI sẽ phá hủy tư duy độc lập của sinh viên"],["C","Ignoring AI-related misconduct","Phớt lờ các vi phạm liên quan đến AI"],["D","Replacing instructors with AI graders","Thay thế giảng viên bằng AI chấm điểm"]],"a":"A","s":0,"tv":"Phản ứng nào của nhà trường phù hợp nhất với cách tiếp cận đạo đức được đề cập trong tài liệu?","g":"new","e":"The ethical approach is to set clear AI-use policies and promote transparency.","ev":"Cách tiếp cận có đạo đức là xây dựng chính sách dùng AI rõ ràng và thúc đẩy sự minh bạch."},{"id":"SSA101_Q122","t":"Why are universities described as being \"in the process\" of developing AI policies?","o":[["A","AI adoption is declining","Việc áp dụng AI đang giảm"],["B","AI is developing faster than ethical guidelines can be established","AI phát triển nhanh hơn tốc độ xây dựng các hướng dẫn đạo đức"],["C","Faculty resistance has ended and AI become a popular tool accepted everywhere","Sự phản đối của giảng viên đã chấm dứt và AI trở thành công cụ phổ biến được chấp nhận ở mọi nơi"],["D","Students no longer use AI","Sinh viên không còn dùng AI"]],"a":"B","s":0,"tv":"Tại sao các trường đại học được mô tả là đang \"trong quá trình\" xây dựng chính sách về AI?","g":"new","e":"Universities are still developing AI policies because AI advances faster than ethical guidelines can be set.","ev":"Các trường vẫn đang xây dựng chính sách AI vì AI phát triển nhanh hơn việc đặt ra hướng dẫn đạo đức."},{"id":"SSA101_Q123","t":"Recognizing personal bias is part of:","o":[["A","Problem-solving","Giải quyết vấn đề"],["B","Critical thinking","Tư duy phản biện"],["C","Information literacy","Hiểu biết thông tin"],["D","Intuition","Trực giác"]],"a":"B","s":0,"tv":"Việc nhận ra thiên kiến cá nhân là một phần của kỹ năng nào?","g":"new","e":"Recognizing your own bias is part of critical thinking.","ev":"Nhận ra thiên kiến của bản thân là một phần của tư duy phản biện."},{"id":"SSA101_Q124","t":"Revisiting a resolved issue when conditions change is:","o":[["A","Weakness","Sự yếu kém"],["B","Critical awareness","Nhận thức phản biện"],["C","Confusion","Sự bối rối"],["D","Creativity","Sự sáng tạo"]],"a":"B","s":0,"tv":"Xem xét lại một vấn đề đã được giải quyết khi điều kiện thay đổi là biểu hiện của điều gì?","g":"new","e":"Revisiting a resolved issue when conditions change shows critical awareness.","ev":"Xem xét lại một vấn đề đã giải quyết khi điều kiện thay đổi thể hiện nhận thức phản biện."},{"id":"SSA101_Q125","t":"What is active listening?","o":[["A","Hearing only","Chỉ nghe"],["B","Engaging fully","Tham gia trọn vẹn"],["C","Interrupting to clarify if needed","Ngắt lời để làm rõ khi cần"],["D","Ignoring speaker","Phớt lờ người nói"]],"a":"B","s":0,"tv":"Lắng nghe chủ động (active listening) là gì?","g":"new","e":"Active listening means engaging fully with the speaker, not just hearing.","ev":"Lắng nghe chủ động là tham gia trọn vẹn với người nói, chứ không chỉ nghe."},{"id":"SSA101_Q126","t":"What is nonverbal communication?","o":[["A","Spoken words","Lời nói"],["B","Body language","Ngôn ngữ cơ thể"],["C","Written text","Văn bản viết"],["D","Grammar rules","Quy tắc ngữ pháp"]],"a":"B","s":0,"tv":"Giao tiếp phi ngôn ngữ (nonverbal communication) là gì?","g":"new","e":"Nonverbal communication is communicating through body language rather than words.","ev":"Giao tiếp phi ngôn ngữ là giao tiếp bằng ngôn ngữ cơ thể thay vì lời nói."},{"id":"SSA101_Q127","t":"Analytical thinking can help prevent:","o":[["A","Emotional thinking","Tư duy cảm xúc"],["B","Workplace inefficiency","Sự kém hiệu quả ở nơi làm việc"],["C","Creativity and overthinking","Sáng tạo và suy nghĩ quá mức"],["D","Collaboration and communication","Hợp tác và giao tiếp"]],"a":"B","s":0,"tv":"tư duy phân tích can help prevent:","g":"new","e":"Analytical thinking helps prevent workplace inefficiency by finding and fixing problems logically.","ev":"Tư duy phân tích giúp ngăn sự kém hiệu quả ở nơi làm việc bằng cách tìm và sửa vấn đề một cách logic."},{"id":"SSA101_Q128","t":"Component parts refer to:","o":[["A","Final conclusions","Kết luận cuối cùng"],["B","Emotional reactions","Phản ứng cảm xúc"],["C","Separate elements of a problem","Các yếu tố riêng biệt của một vấn đề"],["D","Examine assumptions and bias that influence thinking","Xem xét các giả định và thiên kiến ảnh hưởng đến tư duy"]],"a":"C","s":0,"tv":"“Component parts” đề cập đến điều gì?","g":"new","e":"Component parts are the separate elements that make up a problem.","ev":"Các thành phần (component parts) là những yếu tố riêng biệt cấu thành một vấn đề."},{"id":"SSA101_Q129","t":"Which skill supports analytical thinking?","o":[["A","Information literacy","Hiểu biết thông tin"],["B","Ignoring data","Bỏ qua dữ liệu"],["C","Emotional reaction and intuition","Phản ứng cảm xúc và trực giác"],["D","Guesswork","Đoán mò"]],"a":"A","s":0,"tv":"Which skill supports tư duy phân tích?","g":"new","e":"Information literacy supports analytical thinking by helping you find and judge reliable data.","ev":"Hiểu biết thông tin hỗ trợ tư duy phân tích vì giúp bạn tìm và đánh giá dữ liệu đáng tin cậy."},{"id":"SSA101_Q130","t":"Assembly lines (in mass production) reduced inefficiency by:","o":[["A","Eliminating thinking","Loại bỏ tư duy"],["B","Dividing labor","Phân chia lao động"],["C","Increasing chaos","Tăng sự hỗn loạn"],["D","Slowing production","Làm chậm sản xuất"]],"a":"B","s":0,"tv":"Dây chuyền lắp ráp (assembly lines) trong sản xuất hàng loạt đã giảm sự kém hiệu quả bằng cách nào?","g":"new","e":"Assembly lines reduced inefficiency by dividing labor into specialized steps.","ev":"Dây chuyền lắp ráp giảm sự kém hiệu quả bằng cách phân chia lao động thành các bước chuyên môn hóa."},{"id":"SSA101_Q131","t":"Which factor most strongly contributes to poor time management?","o":[["A","Lack of access to technology","Thiếu quyền truy cập công nghệ"],["B","Underestimating how long tasks will take","Đánh giá thấp thời gian các nhiệm vụ cần"],["C","Too many group projects","Quá nhiều dự án nhóm"],["D","Excessive instructor support","Giảng viên hỗ trợ quá mức"]],"a":"B","s":0,"tv":"Which factor most strongly contributes to poor quản lý thời gian?","g":"new","e":"Underestimating how long tasks will take is a main cause of poor time management.","ev":"Đánh giá thấp thời gian cần cho các nhiệm vụ là nguyên nhân chính gây quản lý thời gian kém."},{"id":"SSA101_Q132","t":"What is one benefit of regularly evaluating your time management habits?","o":[["A","It guarantees higher grades","Nó đảm bảo điểm cao hơn"],["B","It allows continuous adjustment and improvement","Nó cho phép điều chỉnh và cải thiện liên tục"],["C","It eliminates stress permanently","Nó loại bỏ căng thẳng vĩnh viễn"],["D","It reduces course workload","Nó giảm khối lượng môn học"]],"a":"B","s":0,"tv":"What is one benefit of regularly evaluating your quản lý thời gian habits?","g":"new","e":"Evaluating your habits regularly lets you keep adjusting and improving how you manage time.","ev":"Đánh giá thói quen thường xuyên cho phép bạn liên tục điều chỉnh và cải thiện cách quản lý thời gian."},{"id":"SSA101_Q133","t":"A student believes being constantly busy means they are managing time well. Based on Chapter 3, why is this assumption flawed?","o":[["A","Being busy always reduces learning quality and knowledge retention","Bận rộn luôn làm giảm chất lượng học và khả năng ghi nhớ kiến thức"],["B","Productivity depends on purposeful prioritization, not just activity","Năng suất phụ thuộc vào việc ưu tiên có mục đích, không chỉ là hoạt động"],["C","Time management only applies to academic tasks","Quản lý thời gian chỉ áp dụng cho các nhiệm vụ học tập"],["D","Busy students are more likely to procrastinate and aske for external support","Sinh viên bận rộn dễ trì hoãn hơn và nhờ hỗ trợ bên ngoài"]],"a":"B","s":0,"tv":"Một sinh viên cho rằng lúc nào cũng bận rộn nghĩa là họ đang quản lý thời gian tốt. Tại sao giả định này không chính xác?","g":"new","e":"Being busy is not the same as being productive; productivity comes from purposeful prioritization.","ev":"Bận rộn không đồng nghĩa với hiệu quả; năng suất đến từ việc ưu tiên có mục đích."},{"id":"SSA101_Q134","t":"What is a planner used for?","o":[["A","Organizing time","Sắp xếp thời gian"],["B","Entertainment","Giải trí"],["C","Social media","Mạng xã hội"],["D","Ignoring deadlines","Phớt lờ hạn chót"]],"a":"A","s":0,"tv":"Planner được sử dụng để làm gì?","g":"new","e":"A planner is a tool for organizing your time.","ev":"Sổ kế hoạch là công cụ để sắp xếp thời gian."},{"id":"SSA101_Q135","t":"What is procrastination?","o":[["A","Planning tasks","Lập kế hoạch nhiệm vụ"],["B","Delaying tasks","Trì hoãn nhiệm vụ"],["C","Completing tasks","Hoàn thành nhiệm vụ"],["D","Prioritizing tasks","Ưu tiên nhiệm vụ"]],"a":"B","s":0,"tv":"Procrastination là gì?","g":"new","e":"Procrastination means delaying tasks.","ev":"Trì hoãn nghĩa là hoãn lại các nhiệm vụ."},{"id":"SSA101_Q137","t":"A student copies text without citation. This is:","o":[["A","Research","Nghiên cứu"],["B","Plagiarism","Đạo văn"],["C","Summary","Tóm tắt"],["D","Analysis","Phân tích"]],"a":"B","s":0,"tv":"Một sinh viên sao chép văn bản mà không trích dẫn nguồn. Đây là hành vi gì?","g":"new","e":"Copying text without citing the source is plagiarism.","ev":"Sao chép văn bản mà không trích dẫn nguồn là đạo văn."},{"id":"SSA101_Q139","t":"What is paraphrasing?","o":[["A","Copying text","Sao chép văn bản"],["B","Rewriting ideas","Viết lại ý tưởng"],["C","Quoting directly","Trích dẫn trực tiếp"],["D","Ignoring source","Bỏ qua nguồn"]],"a":"B","s":0,"tv":"Paraphrasing là gì?","g":"new","e":"Paraphrasing is rewriting an idea in your own words.","ev":"Diễn đạt lại (paraphrase) là viết lại một ý tưởng bằng lời của chính mình."},{"id":"SSA101_Q142","t":"Why is it important to define the problem accurately?","o":[["A","It limits the number of possible solutions and reduces cost accordingly","Nó hạn chế số lượng giải pháp khả thi và giảm chi phí tương ứng"],["B","Misidentified problems often lead to ineffective solutions","Các vấn đề bị xác định sai thường dẫn đến giải pháp không hiệu quả"],["C","It saves time and energy during implementation","Nó tiết kiệm thời gian và công sức khi thực hiện"],["D","It reduces the need for evaluation","Nó giảm nhu cầu đánh giá"]],"a":"B","s":0,"tv":"Tại sao it important to define the problem accurately?","g":"new","e":"A misidentified problem usually leads to solutions that do not work.","ev":"Vấn đề bị xác định sai thường dẫn đến các giải pháp không hiệu quả."},{"id":"SSA101_Q143","t":"Which statement best reflects the chapter's view of problem-solving outcomes?","o":[["A","A solution must work perfectly the first time","Một giải pháp phải hoạt động hoàn hảo ngay lần đầu"],["B","Solutions should be evaluated and adjusted if needed","Các giải pháp nên được đánh giá và điều chỉnh nếu cần"],["C","Once a solution is chosen, it should not change because of the financial riks","Khi đã chọn giải pháp thì không nên thay đổi vì rủi ro tài chính"],["D","Outcomes matter more than process","Kết quả quan trọng hơn quy trình"]],"a":"B","s":0,"tv":"Which statement best reflects the chapter's view of giải quyết vấn đề outcomes?","g":"new","e":"Solutions should be evaluated and adjusted if needed.","ev":"Các giải pháp cần được đánh giá và điều chỉnh khi cần."},{"id":"SSA101_Q144","t":"What is effective communication?","o":[["A","Speaking loudly and emotionally","Nói to và đầy cảm xúc"],["B","Clear message exchange","Trao đổi thông điệp rõ ràng"],["C","Talking more to express yourself","Nói nhiều hơn để thể hiện bản thân"],["D","Ignoring feedback","Phớt lờ phản hồi"]],"a":"B","s":0,"tv":"Giao tiếp hiệu quả (effective communication) là gì?","g":"new","e":"Effective communication is a clear exchange of messages between people.","ev":"Giao tiếp hiệu quả là sự trao đổi thông điệp rõ ràng giữa mọi người."},{"id":"SSA101_Q146","t":"Digital literacy enhances employability mainly because it:","o":[["A","Guarantees higher salaries","Đảm bảo lương cao hơn"],["B","Enables adaptation to technological change","Giúp thích nghi với sự thay đổi công nghệ"],["C","Eliminates workplace stress and enhance mental health","Loại bỏ căng thẳng nơi làm việc và cải thiện sức khỏe tinh thần"],["D","Replaces teamwork skills","Thay thế kỹ năng làm việc nhóm"]],"a":"B","s":0,"tv":"năng lực kỹ thuật số enhances employability mainly because it:","g":"new","e":"Digital literacy improves employability because it lets people adapt to technological change.","ev":"Kỹ năng số nâng cao khả năng có việc làm vì giúp con người thích nghi với thay đổi công nghệ."},{"id":"SSA101_Q148","t":"The book suggests digital literacy programs should include training on:","o":[["A","AI coding only","Chỉ lập trình AI"],["B","Protecting personal data and digital footprints","Bảo vệ dữ liệu cá nhân và dấu vết số"],["C","Eliminating AI tools","Loại bỏ các công cụ AI"],["D","Memorizing algorithms and how to train data","Học thuộc thuật toán và cách huấn luyện dữ liệu"]],"a":"B","s":0,"tv":"The book suggests năng lực kỹ thuật số programs should include training on:","g":"new","e":"Digital literacy programs should teach how to protect personal data and digital footprints.","ev":"Các chương trình kỹ năng số nên dạy cách bảo vệ dữ liệu cá nhân và dấu vết số."},{"id":"SSA101_Q149","t":"AI can support memory formation by:","o":[["A","Replacing reading and note-taking entirely by provide main content of every document","Thay thế hoàn toàn việc đọc và ghi chép bằng cách cung cấp nội dung chính của mọi tài liệu"],["B","Providing metaphors, emotional connections, and multisensory learning ideas","Cung cấp phép ẩn dụ, liên kết cảm xúc và ý tưởng học tập đa giác quan"],["C","Automatically storing information in long-term memory","Tự động lưu thông tin vào trí nhớ dài hạn"],["D","Eliminating the need for attention and focus","Loại bỏ nhu cầu về sự chú ý và tập trung"]],"a":"B","s":0,"tv":"AI có thể hỗ trợ quá trình hình thành trí nhớ bằng cách nào?","g":"new","e":"AI supports memory by offering metaphors, emotional links and multisensory ideas, not by replacing your effort.","ev":"AI hỗ trợ trí nhớ bằng ẩn dụ, liên kết cảm xúc và ý tưởng đa giác quan, chứ không thay thế nỗ lực của bạn."},{"id":"SSA101_Q152","t":"Which factor contributes most to student success?","o":[["A","Intelligence only","Chỉ trí thông minh"],["B","Active engagement","Tham gia tích cực"],["C","Memorizing everything","Ghi nhớ mọi thứ"],["D","Avoiding challenges","Tránh thử thách"]],"a":"B","s":0,"tv":"Yếu tố nào đóng góp nhiều nhất vào sự thành công của sinh viên?","g":"new","e":"Active engagement contributes most to student success.","ev":"Sự tham gia tích cực đóng góp nhiều nhất vào thành công của sinh viên."},{"id":"SSA101_Q154","t":"Which of the following best illustrates monitoring in metacognition?","o":[["A","Creating a study schedule","Lập thời gian biểu học tập"],["B","Checking comprehension while reading","Kiểm tra mức độ hiểu khi đang đọc"],["C","Reviewing grades at the end of the semester","Xem lại điểm số vào cuối học kỳ"],["D","Choosing a major","Chọn ngành học"]],"a":"B","s":0,"tv":"Điều nào sau đây minh họa rõ nhất cho monitoring (tự giám sát) trong siêu nhận thức (metacognition)?","g":"new","e":"Monitoring means checking your understanding while you are learning, such as while reading.","ev":"Theo dõi (monitoring) là kiểm tra mức độ hiểu ngay trong lúc học, chẳng hạn khi đang đọc."},{"id":"SSA101_Q156","t":"Why is metacognition linked to academic success?","o":[["A","Successful students study longer and collaboratively","Sinh viên giỏi học lâu hơn và cùng nhau"],["B","Effective learners actively reflect and adapt","Người học hiệu quả chủ động suy ngẫm và thích nghi"],["C","Intelligence predicts performance","Trí thông minh dự đoán kết quả"],["D","Grades depend on effort alone","Điểm số chỉ phụ thuộc vào nỗ lực"]],"a":"B","s":0,"tv":"Tại sao metacognition linked to academic success?","g":"new","e":"Effective learners reflect on their learning and adapt, which links metacognition to success.","ev":"Người học hiệu quả chủ động suy ngẫm và điều chỉnh, đó là lý do siêu nhận thức gắn với thành công học tập."},{"id":"SSA101_Q157","t":"Creativity often combines:","o":[["A","Only new ideas","Chỉ những ý tưởng mới"],["B","Old ideas in new ways","Những ý tưởng cũ theo cách mới"],["C","Unrelated facts and information","Các sự kiện và thông tin không liên quan"],["D","Strict repetition","Sự lặp lại nghiêm ngặt"]],"a":"B","s":0,"tv":"Sự sáng tạo (creativity) thường kết hợp điều gì?","g":"new","e":"Creativity often combines old ideas in new ways.","ev":"Sự sáng tạo thường kết hợp những ý tưởng cũ theo cách mới."},{"id":"SSA101_Q158","t":"If a student combines two theories to form a new model, this reflects:","o":[["A","Simple recall","Nhớ lại đơn giản"],["B","Creative synthesis","Tổng hợp sáng tạo"],["C","Memorization","Học thuộc lòng"],["D","Avoidance","Né tránh"]],"a":"B","s":0,"tv":"Nếu một sinh viên kết hợp hai lý thuyết để tạo thành một mô hình mới, điều này phản ánh điều gì?","g":"new","e":"Combining two theories into a new model is creative synthesis.","ev":"Kết hợp hai lý thuyết thành một mô hình mới là tổng hợp sáng tạo."},{"id":"SSA101_Q160","t":"Creativity improves thinking skills by:","o":[["A","Limiting scope","Giới hạn phạm vi"],["B","Narrowing vision","Thu hẹp tầm nhìn"],["C","Expanding possibilities","Mở rộng khả năng"],["D","Avoiding challenge","Tránh thử thách"]],"a":"C","s":0,"tv":"Sự sáng tạo cải thiện kỹ năng tư duy bằng cách nào?","g":"new","e":"Creativity improves thinking by expanding the range of possibilities.","ev":"Sáng tạo cải thiện tư duy bằng cách mở rộng phạm vi các khả năng."},{"id":"SSA101_Q161","t":"Which learner behavior best reflects metacognitive awareness?","o":[["A","Completing tasks quickly","Hoàn thành nhiệm vụ nhanh"],["B","Following instructions exactly","Làm theo hướng dẫn chính xác"],["C","Reflecting on what strategies worked or failed","Suy ngẫm về chiến lược nào hiệu quả hay thất bại"],["D","Memorizing lecture slides","Học thuộc slide bài giảng"]],"a":"C","s":0,"tv":"Hành vi nào của người học phản ánh rõ nhất metacognitive awareness (nhận thức siêu nhận thức)?","g":"new","e":"Reflecting on which strategies worked or failed shows metacognitive awareness.","ev":"Suy ngẫm về chiến lược nào hiệu quả hay thất bại thể hiện nhận thức siêu nhận thức."},{"id":"SSA101_Q162","t":"Which situation BEST illustrates weak social presence in an online course?","o":[["A","Students debate ideas respectfully","Sinh viên tranh luận ý tưởng một cách tôn trọng"],["B","Learners avoid responding to peers","Người học tránh phản hồi bạn học"],["C","Instructors provide timely feedback","Giảng viên phản hồi kịp thời"],["D","Groups set clear communication rules","Các nhóm đặt quy tắc giao tiếp rõ ràng"]],"a":"B","s":0,"tv":"Tình huống nào minh họa rõ nhất social presence yếu trong một khóa học trực tuyến?","g":"new","e":"Avoiding responses to peers shows weak social presence in an online course.","ev":"Tránh phản hồi bạn học cho thấy sự hiện diện xã hội yếu trong lớp học trực tuyến."},{"id":"SSA101_Q164","t":"What is working memory?","o":[["A","Long-term storage","Lưu trữ dài hạn"],["B","Temporary processing space","Không gian xử lý tạm thời"],["C","Permanent recall of knowledge","Nhớ lại kiến thức vĩnh viễn"],["D","Emotional memory system","Hệ thống trí nhớ cảm xúc"]],"a":"B","s":0,"tv":"What is trí nhớ làm việc (working memory)?","g":"new","e":"Working memory is a temporary space for holding and processing information.","ev":"Trí nhớ làm việc là không gian tạm thời để giữ và xử lý thông tin."},{"id":"SSA101_Q166","t":"A student studies 10 minutes daily instead of cramming. This uses:","o":[["A","Massed practice","Luyện tập dồn"],["B","Spaced learning","Học giãn cách"],["C","Passive recall","Nhớ lại thụ động"],["D","Surface processing","Xử lý bề mặt"]],"a":"B","s":0,"tv":"Một sinh viên học 10 phút mỗi ngày thay vì học dồn trước kỳ thi. Phương pháp này sử dụng kỹ thuật nào?","g":"new","e":"Studying a little each day instead of cramming is spaced learning.","ev":"Học một ít mỗi ngày thay vì học nhồi là học giãn cách."},{"id":"SSA101_Q167","t":"According to the text, a major concern for graduate students regarding AI grading tools is that:","o":[["A","AI grading is smarter than human grading and could overshadow human's ability in grading","Chấm điểm bằng AI thông minh hơn con người và có thể lấn át khả năng chấm điểm của con người"],["B","AI systems may use their work as training data, affecting future publication","Hệ thống AI có thể dùng bài làm của họ làm dữ liệu huấn luyện, ảnh hưởng đến việc xuất bản sau này"],["C","AI cannot understand complex arguments","AI không thể hiểu các lập luận phức tạp"],["D","AI always produces biased feedback","AI luôn đưa ra phản hồi thiên kiến"]],"a":"B","s":0,"tv":"Theo the text, a major concern for graduate students regarding AI grading tools is that:","g":"new","e":"Graduate students worry that AI systems may use their work as training data, affecting future publication.","ev":"Nghiên cứu sinh lo rằng hệ thống AI có thể dùng bài làm của họ làm dữ liệu huấn luyện, ảnh hưởng đến việc xuất bản sau này."},{"id":"SSA101_Q168","t":"Which method helps reduce test anxiety?","o":[["A","Avoid studying","Tránh học"],["B","Ignoring exams","Phớt lờ kỳ thi"],["C","Preparation","Sự chuẩn bị"],["D","Skipping practice","Bỏ qua luyện tập"]],"a":"C","s":0,"tv":"Phương pháp nào giúp giảm lo lắng khi thi (test anxiety)?","g":"new","e":"Preparation reduces test anxiety because it builds confidence and familiarity.","ev":"Sự chuẩn bị giảm lo lắng khi thi vì tạo sự tự tin và quen thuộc."},{"id":"SSA101_Q169","t":"Which action would most directly improve a student's metacognitive skills?","o":[["A","Increasing total study hours","Tăng tổng số giờ học"],["B","Reflecting on why an exam strategy failed","Suy ngẫm vì sao chiến lược làm bài thi đã thất bại"],["C","Highlighting more information","Đánh dấu nhiều thông tin hơn"],["D","Studying with friends","Học cùng bạn bè"]],"a":"B","s":0,"tv":"Hành động nào trực tiếp nhất giúp cải thiện kỹ năng siêu nhận thức (metacognitive skills) của sinh viên?","g":"new","e":"Reflecting on why a strategy failed directly builds metacognitive skills.","ev":"Suy ngẫm vì sao một chiến lược thất bại trực tiếp rèn luyện kỹ năng siêu nhận thức."},{"id":"SSA101_Q170","t":"When planning travel during uncertainty, you should:","o":[["A","Ignore risk","Phớt lờ rủi ro"],["B","Assume success","Giả định sẽ thành công"],["C","Prepare backup plans","Chuẩn bị các phương án dự phòng"],["D","Avoid thinking","Tránh suy nghĩ"]],"a":"C","s":0,"tv":"Khi lập kế hoạch đi lại trong điều kiện không chắc chắn, bạn nên:","g":"new","e":"When facing uncertainty, you should prepare backup plans.","ev":"Khi đối mặt với sự không chắc chắn, bạn nên chuẩn bị các phương án dự phòng."},{"id":"SSA101_Q171","t":"Critical thinking forces you to determine:","o":[["A","Actual situation","Tình huống thực tế"],["B","By emotion","Bằng cảm xúc"],["C","Preference and research","Sở thích và nghiên cứu"],["D","Habit","Thói quen"]],"a":"A","s":0,"tv":"tư duy phản biện forces you to determine:","g":"new","e":"Critical thinking forces you to determine the actual situation rather than rely on feelings.","ev":"Tư duy phản biện buộc bạn xác định tình huống thực tế thay vì dựa vào cảm xúc."},{"id":"SSA101_Q172","t":"Looking at something \"with a different lens\" means:","o":[["A","Reframing perspective","Định khung lại góc nhìn"],["B","Criticizing it","Chỉ trích nó"],["C","Ignoring details","Bỏ qua chi tiết"],["D","Avoiding structure","Tránh cấu trúc"]],"a":"A","s":0,"tv":"Nhìn một vấn đề \"with a different lens\" (qua một lăng kính khác) có nghĩa là:","g":"new","e":"Looking with a different lens means reframing your perspective.","ev":"Nhìn bằng một lăng kính khác nghĩa là định khung lại góc nhìn."},{"id":"SSA101_Q173","t":"What is one major purpose of college beyond career preparation?","o":[["A","To avoid responsibilities","Để tránh trách nhiệm"],["B","Personal growth","Phát triển bản thân"],["C","To earn money quickly","Để kiếm tiền nhanh"],["D","To reduce social interaction","Để giảm tương tác xã hội"]],"a":"B","s":0,"tv":"Một mục đích quan trọng của việc học đại học ngoài chuẩn bị cho nghề nghiệp là gì?","e":"Personal growth.","ev":"Phát triển bản thân.","g":"new"},{"id":"SSA101_Q174","t":"A student sets specific study hours daily. This improves:","o":[["A","Confusion","Sự bối rối"],["B","Procrastination","Sự trì hoãn"],["C","Consistency","Tính nhất quán"],["D","Random work habits","Thói quen làm việc ngẫu nhiên"]],"a":"C","s":0,"tv":"Một sinh viên đặt ra giờ học cụ thể mỗi ngày. Điều này cải thiện:","g":"new","e":"Setting specific study hours each day builds consistency.","ev":"Đặt giờ học cụ thể mỗi ngày giúp xây dựng tính nhất quán."},{"id":"SSA101_Q175","t":"Developing a board game from literature shows:","o":[["A","Recall from the best childhood experiences","Nhớ lại từ những trải nghiệm tuổi thơ đẹp nhất"],["B","Memorization","Học thuộc lòng"],["C","Creative transformation","Sự biến đổi sáng tạo"],["D","Imitation from best practices","Bắt chước từ các thực hành tốt nhất"]],"a":"C","s":0,"tv":"Việc phát triển một board game (trò chơi bàn cờ) dựa trên tác phẩm văn học thể hiện:","g":"new","e":"Turning literature into a board game is creative transformation.","ev":"Biến văn học thành một trò chơi cờ bàn là sự biến đổi sáng tạo."},{"id":"SSA101_Q176","t":"What is the primary role of a rubric in assignments?","o":[["A","To limit creativity","Để hạn chế sự sáng tạo"],["B","To replace instructor's guideline and comments","Để thay thế hướng dẫn và nhận xét của giảng viên"],["C","To explain grading criteria clearly","Để giải thích rõ tiêu chí chấm điểm"],["D","To rank students","Để xếp hạng sinh viên"]],"a":"C","s":0,"tv":"Vai trò chính của rubric trong các bài tập là gì?","g":"new","e":"A rubric explains the grading criteria clearly.","ev":"Thang chấm (rubric) giải thích rõ các tiêu chí chấm điểm."},{"id":"SSA101_Q177","t":"What risk is associated with uploading dense readings to AI for summaries without reading them?","o":[["A","Reduced chances to practicing English","Giảm cơ hội luyện tiếng Anh"],["B","Missing critical thinking required for memory formation","Bỏ lỡ tư duy phản biện cần thiết cho việc hình thành trí nhớ"],["C","Violating institutional AI policies automatically","Tự động vi phạm chính sách AI của nhà trường"],["D","Overloading working memory and risk to pay more for AI premium versions","Quá tải trí nhớ làm việc và phải trả thêm cho phiên bản AI cao cấp"]],"a":"B","s":0,"tv":"Rủi ro nào liên quan đến việc đưa các bài đọc khó/dày đặc cho AI tóm tắt mà không tự đọc chúng?","g":"new","e":"Skipping the reading loses the critical thinking needed to form memories.","ev":"Bỏ qua việc đọc làm mất tư duy phản biện cần thiết để hình thành trí nhớ."},{"id":"SSA101_Q178","t":"Which factor makes academic integrity a shared responsibility?","o":[["A","Only students submit assignments","Chỉ sinh viên nộp bài"],["B","Institutions must establish clear guidelines and pedagogical practices","Các tổ chức phải thiết lập hướng dẫn rõ ràng và thực hành sư phạm"],["C","Faculty are solely responsible for enforcement","Chỉ giảng viên chịu trách nhiệm thực thi"],["D","Internal communication campaign to criticize and condemn case studies of plagiarism","Chiến dịch truyền thông nội bộ để chỉ trích và lên án các trường hợp đạo văn"]],"a":"B","s":0,"tv":"Which factor makes liêm chính học thuật a shared responsibility?","g":"new","e":"Academic integrity is shared because institutions must set clear guidelines and teaching practices.","ev":"Liêm chính học thuật là trách nhiệm chung vì các tổ chức phải đặt ra hướng dẫn rõ ràng và thực hành giảng dạy phù hợp."},{"id":"SSA101_Q179","t":"What is a 'Liability' example provided for college students?","o":[["A","A savings account.","Một tài khoản tiết kiệm."],["B","A student loan or credit card debt.","Khoản vay sinh viên hoặc nợ thẻ tín dụng."],["C","Income from a part-time job.","Thu nhập từ công việc bán thời gian."],["D","A scholarship.","Một học bổng."]],"a":"B","s":0,"e":"In strict financial terms, a liability represents any legally binding financial obligation or borrowed capital that must eventually be repaid, usually with accrued interest. For the vast majority of college students, the most significant and burdensome liabilities they carry are outstanding federal or private student loans and high-interest consumer credit card balances.","ev":"Xét về mặt tài chính, nợ phải trả là bất kỳ nghĩa vụ tài chính ràng buộc về mặt pháp lý hoặc vốn vay nào mà cuối cùng phải được hoàn trả, thường kèm theo lãi suất. Đối với phần lớn sinh viên [?]","g":"new","tv":"Ví dụ nào về 'Nợ phải trả' (Liability) được nêu cho sinh viên đại học?"},{"id":"SSA101_Q180","t":"What is the mathematical formula for Net Worth?","o":[["A","Income + Expenses = Net Worth","Thu nhập + Chi phí = Giá trị ròng"],["B","Assets + Liabilities = Net Worth","Tài sản + Nợ phải trả = Giá trị ròng"],["C","Assets (Owned) – Liabilities (Owed) = Net Worth","Tài sản (sở hữu) – Nợ phải trả (còn nợ) = Giá trị ròng"],["D","Savings – Debt = Net Worth","Tiết kiệm – Nợ = Giá trị ròng"]],"a":"C","s":0,"e":"The mathematical formula to calculate Net Worth is extremely straightforward but conceptually critical: you take your total Assets (everything you legally own that holds economic value) and subtract your total Liabilities (every single cent of borrowed money or outstanding debt that you owe) to find your true Net Worth.","ev":"Công thức toán học để tính Giá trị tài sản ròng (Net Worth) rất đơn giản nhưng quan trọng về mặt khái niệm: bạn lấy tổng Tài sản (mọi thứ bạn sở hữu hợp pháp có giá trị kinh tế) trừ đi tổng Nợ phải trả (mọi khoản tiền vay hoặc nợ chưa thanh toán) để tìm ra Giá trị tài sản ròng thực sự của mình.","g":"new","tv":"Công thức toán học tính Giá trị ròng (Net Worth) là gì?"},{"id":"SSA101_Q181","t":"What is the first step in the five-step financial planning process?","o":[["A","Monitor and Adjust the Plan","Theo dõi và điều chỉnh kế hoạch"],["B","Implement the Plan","Thực hiện kế hoạch"],["C","Develop Personal Goals","Xây dựng mục tiêu cá nhân"],["D","Write My Financial Plan","Viết kế hoạch tài chính của tôi"]],"a":"C","s":0,"e":"The rigorous five-step financial planning process must logically start with developing specific personal goals. Without clearly articulating what you actually want to achieve—such as eliminating debt or saving for a house—your financial plan will lack direction, making it impossible to create actionable budgets or measure meaningful progress.","ev":"Quy trình lập kế hoạch tài chính nghiêm ngặt gồm năm bước phải bắt đầu bằng việc xác định các mục tiêu cá nhân cụ thể. Nếu không xác định rõ ràng những gì bạn thực sự muốn đạt được—chẳng hạn như xóa nợ hoặc tiết kiệm để mua nhà—kế hoạch tài chính của bạn sẽ thiếu định hướng, khiến việc lập ngân sách khả thi hoặc đo lường tiến độ có ý nghĩa trở nên bất khả thi.","g":"new","tv":"Bước đầu tiên trong quy trình lập kế hoạch tài chính năm bước là gì?"},{"id":"SSA101_Q182","t":"Which time management app uses boards to organize obligations and share them with collaborators?","o":[["A","Toggl","Toggl"],["B","Trello","Trello"],["C","Sticky Notes","Sticky Notes"],["D","Google Calendar","Google Calendar"]],"a":"B","s":0,"tv":"Which quản lý thời gian app uses boards to organize obligations and share them with collaborators?","e":"Trello is a visual time and project management application that utilizes a highly intuitive system of digital boards, lists, and movable cards. It allows you to organize multiple academic obligations, track their progress in real-time, and easily share or assign these tasks with collaborators during group projects to ensure everyone stays on schedule.","ev":"Trello là một ứng dụng quản lý thời gian và dự án trực quan, sử dụng hệ thống bảng kỹ thuật số, danh sách và thẻ di động vô cùng dễ sử dụng. Nó cho phép bạn tổ chức nhiều nghĩa vụ học tập, theo dõi tiến độ trong thời gian thực và dễ dàng chia sẻ hoặc giao nhiệm vụ cho cộng tác viên trong các dự án nhóm để đảm bảo mọi người luôn đúng tiến độ.","g":"new"},{"id":"SSA101_Q183","t":"Which motivation strategy involves adopting the mindset that you alone are responsible for your goals?","o":[["A","Reward Yourself","Tự thưởng cho bản thân"],["B","Tap into Other People's Energy","Tận dụng năng lượng của người khác"],["C","Increase Personal Responsibility","Tăng trách nhiệm cá nhân"],["D","Visualize the Results","Hình dung kết quả"]],"a":"C","s":0,"e":"The motivation strategy of \"Increasing Personal Responsibility\" requires an internal mindset shift where you fully accept that you are the sole driver of your academic and professional success. By holding yourself entirely accountable for your goals, you eliminate the habit of blaming external factors and empower yourself to take direct control over your learning journey.","ev":"Chiến lược tạo động lực \"Tăng cường trách nhiệm cá nhân\" đòi hỏi sự thay đổi tư duy nội tại, nơi bạn hoàn toàn chấp nhận rằng bạn là người duy nhất chịu trách nhiệm cho thành công học tập và nghề nghiệp của mình. Bằng cách tự chịu trách nhiệm hoàn toàn cho mục tiêu của bản thân, bạn loại bỏ thói quen đổ lỗi cho các yếu tố bên ngoài và tự trao quyền kiểm soát trực tiếp hành trình học tập của mình.","g":"new","tv":"Chiến lược tạo động lực nào liên quan đến việc tin rằng chỉ riêng bạn chịu trách nhiệm cho mục tiêu của mình?"},{"id":"SSA101_Q184","t":"Which motivation strategy suggests that moods and emotions can be influenced by those around you?","o":[["A","Visualize the Results.","Hình dung kết quả."],["B","Tap into Other People's Energy.","Tận dụng năng lượng của người khác."],["C","Break the Goal Down.","Chia nhỏ mục tiêu."],["D","Increase Personal Responsibility.","Tăng trách nhiệm cá nhân."]],"a":"B","s":0,"e":"Human emotions and motivation levels are highly contagious via a psychological concept known as \"emotional contagion.\" By intentionally surrounding yourself with driven, positive, and naturally focused peers or mentors, you unconsciously absorb their productive energy and high standards, which actively helps pull you out of academic slumps and reinforces your own commitment to success.","ev":"Cảm xúc và động lực của con người có tính lây lan cao thông qua một khái niệm tâm lý gọi là \"sự lây lan cảm xúc\". Bằng cách chủ động bao quanh mình bởi những người bạn hoặc người hướng dẫn tích cực, có động lực và tập trung, bạn sẽ hấp thụ năng lượng tích cực và tiêu chuẩn cao của họ, giúp bạn thoát khỏi sự sa sút trong học tập và củng cố cam kết thành công của chính mình.","g":"new","tv":"Chiến lược tạo động lực nào cho rằng tâm trạng và cảm xúc có thể bị ảnh hưởng bởi những người xung quanh?"},{"id":"SSA101_Q185","t":"Which career assessment tool identifies motivations by ranking different aspects of work?","o":[["A","MAPP Test","Bài kiểm tra MAPP"],["B","MyPlan","MyPlan"],["C","Career Cluster Interest Survey","Khảo sát sở thích theo cụm nghề nghiệp"],["D","Myers-Briggs Type Indicator","Chỉ số loại hình Myers-Briggs"]],"a":"A","s":0,"e":"The MAPP (Motivational Appraisal Personal Potential) test is a comprehensive career assessment instrument that moves beyond simple skills testing. It uncovers your true intrinsic motivations and natural inclinations by requiring you to rank various distinct aspects of work, daily tasks, and environments, helping align your career path with long-term job satisfaction.","ev":"Bài kiểm tra MAPP (Đánh giá động lực và tiềm năng cá nhân) là một công cụ đánh giá nghề nghiệp toàn diện vượt ra ngoài việc kiểm tra kỹ năng đơn thuần. Nó khám phá động lực nội tại và khuynh hướng tự nhiên của bạn bằng cách yêu cầu bạn xếp hạng các khía cạnh khác nhau của công việc, nhiệm vụ hàng ngày và môi trường làm việc, giúp định hướng nghề nghiệp phù hợp với sự hài lòng lâu dài.","g":"new","tv":"Công cụ đánh giá nghề nghiệp nào xác định động lực bằng cách xếp hạng các khía cạnh khác nhau của công việc?"},{"id":"SSA101_Q186","t":"Which level of the revised Bloom's cognitive taxonomy is considered the apex (highest level)?","o":[["A","Remembering","Ghi nhớ"],["B","Analyzing","Phân tích"],["C","Evaluating","Đánh giá"],["D","Creating","Sáng tạo"]],"a":"D","s":0,"e":"In the revised framework of Bloom's Taxonomy, the cognitive process of \"Creating\" represents the absolute maximum apex of human learning. It requires mastering all previous levels in order to seamlessly synthesize independently gathered elements into a completely new, coherent, and highly functional product or original idea.","ev":"Trong khuôn khổ sửa đổi của Phân loại Bloom, quá trình nhận thức \"Sáng tạo\" đại diện cho đỉnh cao tuyệt đối của khả năng học tập của con người. Nó đòi hỏi phải nắm vững tất cả các cấp độ trước đó để tổng hợp một cách liền mạch các yếu tố độc lập thành một sản phẩm hoặc ý tưởng gốc hoàn toàn mới, mạch lạc và có tính ứng dụng cao.","g":"new","tv":"Cấp độ nào của thang phân loại nhận thức Bloom sửa đổi được xem là đỉnh cao (cấp cao nhất)?"},{"id":"SSA101_Q187","t":"Which type of thinking involves generating original and unconventional ideas?","o":[["A","Analytical Thinking","Tư duy phân tích"],["B","Creative Thinking","Tư duy sáng tạo"],["C","Critical Thinking","Tư duy phản biện"],["D","Metacognition","Siêu nhận thức"]],"a":"B","s":0,"e":"Creative thinking is a cognitive process focused strictly on innovation, originality, and unconventional perspective-taking. Unlike analytical thinking—which breaks down existing data—creative thinking encourages \"out-of-the-box\" brainstorming to synthesize entirely new ideas and design unique solutions to complex problems.","ev":"Tư duy sáng tạo là một quá trình nhận thức tập trung vào sự đổi mới, tính độc đáo và khả năng nhìn nhận vấn đề từ những góc độ khác biệt. Không giống như tư duy phân tích—vốn chia nhỏ dữ liệu hiện có—tư duy sáng tạo khuyến khích việc động não \"vượt ra ngoài khuôn khổ\" để tổng hợp những ý tưởng hoàn toàn mới và thiết kế các giải pháp độc đáo cho những vấn đề phức tạp.","g":"new","tv":"Kiểu tư duy nào liên quan đến việc tạo ra những ý tưởng độc đáo và khác thường?"},{"id":"SSA101_Q188","t":"Approximately how many hours of reading per week might a full college course load require?","o":[["A","1–2 hours","1–2 giờ"],["B","5–7 hours","5–7 giờ"],["C","10–15 hours","10–15 giờ"],["D","20+ hours","20+ giờ"]],"a":"C","s":0,"e":"Maintaining a full college course load is a significant commitment that demands extensive independent preparation outside the classroom. Because courses rely heavily on diverse academic materials, a student should realistically expect and schedule anywhere from 10 to 15 hours of rigorous assigned reading every single week just to keep pace with the curriculum.","ev":"Việc duy trì chương trình học đại học đầy đủ là một cam kết đáng kể đòi hỏi sự chuẩn bị độc lập sâu rộng ngoài giờ học. Vì các môn học phụ thuộc nhiều vào các tài liệu học thuật đa dạng, sinh viên nên dự kiến và sắp xếp khoảng 10 đến 15 giờ đọc tài liệu được giao mỗi tuần để theo kịp chương trình học.","g":"new","tv":"Một khối lượng học đại học đầy đủ có thể đòi hỏi khoảng bao nhiêu giờ đọc mỗi tuần?"},{"id":"SSA101_Q189","t":"In personal finance, what are 'Liabilities'?","o":[["A","Your monthly income sources","Các nguồn thu nhập hằng tháng của bạn"],["B","The interest earned on savings accounts","Tiền lãi kiếm được từ tài khoản tiết kiệm"],["C","Borrowed money, or debt, that you owe","Tiền vay mượn, tức khoản nợ bạn phải trả"],["D","Your fixed monthly expenses like rent","Các khoản chi cố định hằng tháng như tiền thuê nhà"]],"a":"C","s":0,"e":"\"Liabilities\" are the direct opposite of assets; they represent binding financial debts, borrowed capital, or formal financial obligations that you legally owe to external entities or creditors. In a standard personal finance context, these typically manifest as high-interest credit card balances, longstanding student loans, auto financing, and home mortgages.","ev":"\"Nợ phải trả\" là hoàn toàn trái ngược với tài sản; chúng đại diện cho các khoản nợ tài chính ràng buộc, vốn vay hoặc các nghĩa vụ tài chính chính thức mà bạn phải trả theo pháp luật cho các tổ chức hoặc chủ nợ bên ngoài. Trong bối cảnh tài chính cá nhân, những khoản này thường thể hiện dưới dạng dư nợ thẻ tín dụng lãi suất cao, các khoản vay sinh viên, vay mua ô tô và vay thế chấp mua nhà.","g":"new","tv":"Trong tài chính cá nhân, 'Nợ phải trả' (Liabilities) là gì?"},{"id":"SSA101_Q190","t":"In the SIFT method used to evaluate the accuracy of information on the internet, what does the letter \"I\" stand for?","o":[["A","Identify the initial author.","Xác định tác giả ban đầu."],["B","Investigate the source.","Điều tra nguồn."],["C","Imitate the main claim.","Bắt chước luận điểm chính."],["D","Inform the general public","Thông báo cho công chúng."]],"a":"B","s":0,"e":"In the SIFT framework for evaluating digital information (Stop, Investigate the source, Find better coverage, Trace claims to original context), the \"I\" stands for \"Investigate the source.\" This crucial step demands that students pause reading the actual claim and instead rigorously research the author, publisher, and funding behind the website to determine their underlying credibility and potential biases.","ev":"Trong khuôn khổ SIFT để đánh giá thông tin kỹ thuật số (Dừng lại, Điều tra nguồn, Tìm kiếm thông tin đầy đủ hơn, Truy tìm nguồn gốc thông tin), chữ \"I\" viết tắt cho \"Điều tra nguồn\" (Investigate the source). Bước quan trọng này yêu cầu sinh viên tạm dừng việc đọc tuyên bố thực tế mà thay vào đó nghiên cứu kỹ tác giả, nhà xuất bản và nguồn tài trợ đứng sau trang web để xác định độ tin cậy và các thiên kiến tiềm ẩn.","g":"new","tv":"Trong phương pháp SIFT dùng để đánh giá độ chính xác của thông tin trên internet, chữ \"I\" là viết tắt của gì?"},{"id":"SSA101_Q191","t":"In the SMART acronym, what does 'T' usually stand for?","o":[["A","Technical.","Kỹ thuật (Technical)."],["B","Tested.","Đã kiểm thử (Tested)."],["C","Time-bound.","Có thời hạn (Time-bound)."],["D","Theoretical.","Lý thuyết (Theoretical)."]],"a":"C","s":0,"e":"The \"T\" in the SMART goal-setting framework stands for \"Time-bound.\" This criterion emphasizes that an effective goal must have a clear, strictly defined deadline or timeframe, which creates a vital sense of urgency, prevents tasks from lingering indefinitely, and forces the individual to prioritize their daily schedule to achieve the goal on time.","ev":"Chữ \"T\" trong khung thiết lập mục tiêu SMART viết tắt cho \"Có thời hạn\" (Time-bound). Tiêu chí này nhấn mạnh rằng một mục tiêu hiệu quả phải có thời hạn hoặc khung thời gian rõ ràng, được xác định nghiêm ngặt, tạo ra cảm giác khẩn cấp cần thiết, ngăn chặn các nhiệm vụ bị trì hoãn vô thời hạn và buộc cá nhân phải ưu tiên lịch trình hàng ngày của mình để đạt được mục tiêu đúng hạn.","g":"new","tv":"Trong từ viết tắt SMART, chữ 'T' thường là viết tắt của gì?"},{"id":"SSA101_Q192","t":"What is the 'most important' financial rule when buying an education?","o":[["A","Attend the most expensive college you can get into","Học trường đắt nhất mà bạn có thể vào"],["B","Use credit cards to pay for tuition","Dùng thẻ tín dụng để trả học phí"],["C","If you fail to plan, you are planning to fail","Nếu bạn không lập kế hoạch, bạn đang lên kế hoạch để thất bại"]],"a":"C","s":0,"e":"Financing a college education is one of the largest investments a person will ever make. The principle \"if you fail to plan, you are planning to fail\" emphasizes that entering college without a rigid, highly proactive financial strategy to safely cover tuition and living expenses drastically increases the risk of crippling debt or being forced to abandon the degree.","ev":"Chi trả cho việc học đại học là một trong những khoản đầu tư lớn nhất mà một người sẽ thực hiện trong đời. Nguyên tắc \"nếu bạn không lập kế hoạch, bạn đang lên kế hoạch cho sự thất bại\" nhấn mạnh rằng việc vào đại học mà không có một chiến lược tài chính chủ động và chặt chẽ để trang trải học phí và chi phí sinh hoạt sẽ làm tăng đáng kể nguy cơ mắc nợ chồng chất hoặc phải bỏ dở việc học.","g":"new","tv":"Quy tắc tài chính 'quan trọng nhất' khi đầu tư cho giáo dục là gì?"},{"id":"SSA101_Q193","t":"What is the primary purpose of recapturing 'lost moments' in a schedule?","o":[["A","To increase the amount of time spent on social media","Để tăng thời gian dùng mạng xã hội"],["B","To find time for napping during the day","Để tìm thời gian ngủ trưa trong ngày"],["C","To repurpose that time for studying or completing productive tasks","Để dùng lại khoảng thời gian đó cho việc học hoặc hoàn thành các nhiệm vụ hiệu quả"],["D","To allow for more travel time between classes","Để có thêm thời gian di chuyển giữa các tiết học"]],"a":"C","s":0,"e":"In any daily schedule, there are inevitably \"lost moments\"—short 10-to-15-minute pockets of downtime, such as waiting for public transit or transitioning between classes. The primary purpose of identifying these moments is to proactively repurpose them for quick, productive study tasks (like reviewing flashcards), which ultimately maximizes your total daily productivity.","ev":"Trong bất kỳ lịch trình hàng ngày nào, chắc chắn sẽ có những \"khoảnh khắc bị lãng phí\"—những khoảng thời gian ngắn từ 10 đến 15 phút rảnh rỗi, chẳng hạn như chờ phương tiện công cộng hoặc di chuyển giữa các lớp học. Mục đích chính của việc nhận diện những khoảnh khắc này là chủ động tận dụng chúng cho các nhiệm vụ học tập nhanh chóng và hiệu quả (như ôn tập thẻ ghi nhớ), giúp tối đa hóa năng suất hàng ngày.","g":"new","tv":"Mục đích chính của việc tận dụng lại 'những khoảnh khắc bị lãng phí' trong lịch trình là gì?"},{"id":"SSA101_Q194","t":"According to the text, what is a 'bad practice' that leads to a 'debt hole'?","o":[["A","Tracking all spending and saving","Theo dõi mọi khoản chi tiêu và tiết kiệm"],["B","Spending money on wants instead of saving","Chi tiền cho những thứ muốn có thay vì tiết kiệm"],["C","Knowing the difference between needs and wants","Biết sự khác biệt giữa nhu cầu và mong muốn"],["D","Paying yourself first","Trả cho bản thân trước"]],"a":"B","s":0,"tv":"Theo the text, what is a 'bad practice' that leads to a 'debt hole'","e":"A consistently poor financial practice is systematically prioritizing discretionary spending on non-essential \"wants\" before adequately funding essential savings. This behavior inevitably depletes cash reserves, leaving you highly vulnerable during unexpected emergencies and almost guaranteeing a reliance on high-interest credit that creates a deep, inescapable \"debt hole.\"","ev":"Một thói quen quản lý tài chính tồi thường xuyên là ưu tiên chi tiêu tùy ý vào những thứ \"mong muốn\" không thiết yếu trước khi dành đủ tiền tiết kiệm cho những nhu cầu thiết yếu. Hành vi này chắc chắn sẽ làm cạn kiệt quỹ dự phòng, khiến bạn dễ bị tổn thương trong các tình huống khẩn cấp và gần như dẫn đến việc phụ thuộc vào tín dụng lãi suất cao, tạo ra một \"hố nợ\" sâu khó thoát.","g":"new"},{"id":"SSA101_Q195","t":"During a class, what type of questions should a student ask to engage in critical thinking?","o":[["A","Questions about the format of the final exam","Câu hỏi về hình thức của kỳ thi cuối kỳ"],["B","Questions that distract the professor to use up class time","Câu hỏi làm giảng viên phân tâm để câu giờ"],["C","Questions for clarification on areas that are confusing","Câu hỏi làm rõ những phần còn khó hiểu"],["D","All of the above","Tất cả các ý trên"]],"a":"C","s":0,"tv":"During a class, what type of questions should a student ask to engage in tư duy phản biện?","e":"Critical thinking requires students to actively analyze, evaluate, and clarify what they do not yet understand instead of passively receiving information. Asking questions to clarify confusing parts helps students grasp the true essence of the knowledge.","ev":"Critical thinking (tư duy phản biện) đòi hỏi sinh viên phải chủ động phân tích, đánh giá và làm rõ những điều mình chưa hiểu, thay vì chỉ tiếp nhận thông tin một cách thụ động. Việc đặt câu hỏi để làm rõ các phần còn gây nhầm lẫn giúp hiểu đúng bản chất của kiến thức.","g":"new"},{"id":"SSA101_Q196","t":"What is the potential downside of creating overly complex mnemonics?","o":[["A","They are too easy to remember and thus boring.","Chúng quá dễ nhớ nên nhàm chán."],["B","The reminder itself can become more difficult to remember than the information you are trying to relate it to","Chính lời nhắc có thể trở nên khó nhớ hơn thông tin bạn đang cố liên hệ"],["C","They only work for math problems.","Chúng chỉ hiệu quả với các bài toán."],["D","Instructors generally forbid their use during exams.","Giảng viên thường cấm dùng chúng trong kỳ thi."]],"a":"B","s":0,"e":"The entire functional purpose of a mnemonic device is to act as a simple cognitive shortcut to retrieve complex information. However, if the mnemonic itself is overly complicated or too long, your brain must exert more cognitive effort merely trying to remember the reminder than the actual underlying information, completely defeating its purpose as an effective study aid.","ev":"Mục đích chính của một phương pháp ghi nhớ là hoạt động như một lối tắt nhận thức đơn giản để truy xuất thông tin phức tạp. Tuy nhiên, nếu bản thân phương pháp ghi nhớ quá phức tạp hoặc quá dài, não bộ của bạn phải nỗ lực nhận thức nhiều hơn chỉ để cố gắng nhớ lại lời nhắc hơn là thông tin thực sự cần nhớ, điều này hoàn toàn làm mất đi tác dụng của nó như một công cụ hỗ trợ học tập hiệu quả.","g":"new","tv":"Nhược điểm tiềm ẩn của việc tạo ra các mẹo ghi nhớ (mnemonics) quá phức tạp là gì?"},{"id":"SSA101_Q197","t":"What is 'Information Literacy' for college students?","o":[["A","The ability to read very quickly","Khả năng đọc rất nhanh"],["B","Knowing how to use social media effectively","Biết cách dùng mạng xã hội hiệu quả"],["C","The ability to weigh information, examine it for validity, and determine which information is appropriate to use","Khả năng cân nhắc thông tin, kiểm tra tính hợp lệ và xác định thông tin nào phù hợp để dùng"],["D","Knowing how to build a website","Biết cách xây dựng một trang web"]],"a":"C","s":0,"tv":"What is 'năng lực thông tin' for college students?","e":"In the modern digital age, students are overwhelmed with easily accessible data from countless sources, many of which are unreliable or biased. Information literacy empowers students to critically evaluate these sources for credibility, expertly filter out misinformation, and ethically apply the most accurate and relevant evidence to support their academic arguments or solve complex problems.","ev":"Trong thời đại kỹ thuật số hiện đại, sinh viên bị choáng ngợp bởi lượng dữ liệu dễ dàng tiếp cận từ vô số nguồn, nhiều trong số đó không đáng tin cậy hoặc mang tính thiên vị. Năng lực thông tin trao quyền cho sinh viên đánh giá phản biện độ tin cậy của các nguồn này, lọc bỏ thông tin sai lệch và áp dụng một cách có đạo đức những bằng chứng chính xác, phù hợp nhất để hỗ trợ lập luận học thuật hoặc giải quyết các vấn đề phức tạp.","g":"new"},{"id":"SSA101_Q198","t":"What is a significant technological challenge related to the use of AI detection tools like Turnitin in higher education environments?","o":[["A","These tools have proven to be entirely flawless in distinguishing between human and machine writing, rendering traditional academic grading obsolete","Các công cụ này đã được chứng minh hoàn toàn hoàn hảo trong việc phân biệt văn bản của con người và máy, khiến việc chấm điểm truyền thống trở nên lỗi thời"],["B","These tools are completely incapable of scanning any student essays that have been submitted through standard, school-sponsored learning management systems","Các công cụ này hoàn toàn không thể quét bất kỳ bài luận nào được nộp qua hệ thống quản lý học tập tiêu chuẩn của trường"],["C","These tools face reliability issues as new software continually emerges to intentionally bypass detection by artificially mimicking human writing styles","Các công cụ này gặp vấn đề về độ tin cậy vì phần mềm mới liên tục xuất hiện để cố ý qua mặt việc phát hiện bằng cách mô phỏng phong cách viết của con người"],["D","These tools deliberately alter the original text of student submissions to artificially inflate similarity scores and arbitrarily justify academic penalties","Các công cụ này cố ý thay đổi văn bản gốc của bài nộp để thổi phồng điểm tương đồng và biện minh tùy tiện cho các hình phạt học thuật"]],"a":"C","s":0,"e":"The technological \"arms race\" between generative AI and AI detection tools creates severe reliability issues inside academic grading. As students deliberately adopt sophisticated \"humanizer\" software specifically engineered to artificially insert grammatical variability and bypass detection algorithms, the current scanning tools rapidly become outdated, regularly producing dangerous false positives and false negatives.","ev":"Cuộc \"chạy đua vũ trang\" công nghệ giữa trí tuệ nhân tạo tạo sinh (generative AI) và các công cụ phát hiện AI tạo ra những vấn đề nghiêm trọng về độ tin cậy trong việc chấm điểm học thuật. Khi sinh viên cố tình sử dụng các phần mềm \"nhân hóa\" tinh vi được thiết kế để chèn các biến thể ngữ pháp nhân tạo nhằm vượt qua thuật toán phát hiện, các công cụ quét hiện tại nhanh chóng trở nên lỗi thời và thường xuyên cho ra kết quả dương tính giả hoặc âm tính giả nguy hiểm.","g":"new","tv":"Thách thức công nghệ đáng kể liên quan đến việc dùng các công cụ phát hiện AI như Turnitin trong môi trường giáo dục đại học là gì?"},{"id":"SSA101_Q199","t":"What is a major negative environmental impact of developing and training Large Language Models (like ChatGPT-4)?","o":[["A","The continuous execution of complex algorithms actively depletes the overall quality of biodiversity data stored in international environmental databases","Việc liên tục chạy các thuật toán phức tạp làm suy giảm chất lượng dữ liệu đa dạng sinh học lưu trong các cơ sở dữ liệu môi trường quốc tế"],["B","The physical process of collecting billions of data points causes severe noise pollution and habitat disruption at global server storage centers","Quá trình thu thập hàng tỷ điểm dữ liệu gây ô nhiễm tiếng ồn nghiêm trọng và phá vỡ môi trường sống tại các trung tâm lưu trữ máy chủ toàn cầu"],["C","The training process requires continuous operation on specialized hardware for weeks, consuming massive electricity and creating a large carbon footprint","Quá trình huấn luyện đòi hỏi vận hành liên tục trên phần cứng chuyên dụng trong nhiều tuần, tiêu thụ lượng điện khổng lồ và tạo ra lượng khí thải carbon lớn"],["D","The rapid advancement of models increases electronic waste exponentially due to constant, yearly server and hardware replacements","Sự tiến bộ nhanh của các mô hình làm rác thải điện tử tăng theo cấp số nhân do phải thay máy chủ và phần cứng liên tục hằng năm"]],"a":"C","s":0,"e":"Developing sophisticated AI models fundamentally requires immense computational power, achieved by running thousands of specialized high-performance GPUs continuously for weeks or months. This relentless processing consumes staggering, industrial-level amounts of electricity and generates massive heat, resulting in a tremendously large global carbon footprint and heavily straining local water resources for server cooling.","ev":"Việc phát triển các mô hình AI phức tạp về cơ bản đòi hỏi sức mạnh tính toán khổng lồ, đạt được bằng cách vận hành liên tục hàng nghìn GPU hiệu năng cao chuyên dụng trong nhiều tuần hoặc nhiều tháng. Quá trình xử lý không ngừng này tiêu thụ lượng điện năng khổng lồ ở quy mô công nghiệp và sinh ra lượng nhiệt lớn, dẫn đến dấu chân carbon toàn cầu cực lớn và gây áp lực nặng nề lên nguồn nước địa phương để làm mát máy chủ.","g":"new","tv":"Tác động tiêu cực lớn đến môi trường của việc phát triển và huấn luyện các Mô hình ngôn ngữ lớn (như ChatGPT-4) là gì?"},{"id":"SSA101_Q200","t":"What is the greatest risk to students' freedom of expression when universities implement \"AI surveillance\" on school-issued devices?","o":[["A","The students' devices may experience severe performance degradation and battery drain due to the constant running of background monitoring algorithms","Thiết bị của sinh viên có thể bị giảm hiệu năng nghiêm trọng và hao pin do các thuật toán giám sát chạy nền liên tục"],["B","Students' search histories on sensitive topics (e.g., politics, mental health) could be tracked, creating a persistent fear of being criminalized or exposed","Lịch sử tìm kiếm của sinh viên về các chủ đề nhạy cảm (ví dụ chính trị, sức khỏe tâm thần) có thể bị theo dõi, tạo ra nỗi sợ thường trực bị quy tội hoặc bị lộ"],["C","A significant loss of diverse academic thinking because students are artificially restricted to only utilizing safe, school-recommended research databases","Mất đi đáng kể sự đa dạng trong tư duy học thuật vì sinh viên bị hạn chế một cách giả tạo chỉ được dùng các cơ sở dữ liệu nghiên cứu an toàn do trường đề xuất"],["D","The advanced surveillance algorithms cost too much to maintain, leading directly to increased tuition fees and financial burdens for marginalized students","Các thuật toán giám sát tiên tiến tốn quá nhiều chi phí bảo trì, dẫn trực tiếp đến tăng học phí và gánh nặng tài chính cho sinh viên yếu thế"]],"a":"B","s":0,"e":"When universities implement pervasive algorithmic surveillance to monitor student activity, it completely strips away digital privacy. The greatest chilling effect is that students become terrified to research highly sensitive, personal, or controversial topics—such as mental health struggles, political activism, or reproductive rights—out of a legitimate fear of institutional backlash or criminalization.","ev":"Khi các trường đại học triển khai hệ thống giám sát thuật toán rộng khắp để theo dõi hoạt động của sinh viên, điều đó hoàn toàn tước đoạt quyền riêng tư kỹ thuật số. Tác động đáng sợ nhất là sinh viên trở nên sợ hãi khi tìm hiểu các chủ đề nhạy cảm, cá nhân hoặc gây tranh cãi—như sức khỏe tâm thần, hoạt động chính trị hay quyền sinh sản—vì lo sợ bị nhà trường trừng phạt hoặc hình sự hóa.","g":"new","tv":"Rủi ro lớn nhất đối với quyền tự do ngôn luận của sinh viên khi các trường đại học triển khai \"giám sát bằng AI\" trên thiết bị do trường cấp là gì?"},{"id":"SSA101_Q201","t":"What is the 'first year experience' described in the Chapter 1 outline?","o":[["A","A big party held at the end of the school year.","Một bữa tiệc lớn tổ chức vào cuối năm học."],["B","A mandatory physical education course.","Một môn thể dục bắt buộc."],["C","A transitional experience that requires academic, cultural, emotional, financial, intellectual, and social adjustments.","Một trải nghiệm chuyển tiếp đòi hỏi sự điều chỉnh về học tập, văn hóa, cảm xúc, tài chính, trí tuệ và xã hội."],["D","A period where grades do not count toward your transcript.","Một giai đoạn mà điểm số không được tính vào bảng điểm của bạn."]],"a":"C","s":0,"e":"The transition into higher education is not merely an academic shift; it represents a massive, total disruption of a student's previous life structure. The \"first year experience\" acknowledges that first-year students must simultaneously navigate enormous adjustments in academic rigor, cultural independence, emotional maturity, financial responsibility, and new complex social dynamics.","ev":"Việc chuyển tiếp lên bậc giáo dục đại học không chỉ đơn thuần là một sự thay đổi về mặt học thuật; nó còn là một sự xáo trộn lớn, hoàn toàn đối với cấu trúc cuộc sống trước đây của sinh viên. \"Trải nghiệm năm nhất\" thừa nhận rằng sinh viên năm nhất phải đồng thời thích nghi với những điều chỉnh to lớn về độ khó học thuật, sự độc lập văn hóa, sự trưởng thành cảm xúc, trách nhiệm tài chính và các mối quan hệ xã hội mới phức tạp.","g":"new","tv":"'Trải nghiệm năm nhất' được mô tả trong đề cương Chương 1 là gì?"},{"id":"SSA101_Q202","t":"What is the benefit of practicing for interviews with career counselors?","o":[["A","They will tell you the exact questions employers will ask.","Họ sẽ cho bạn biết chính xác các câu hỏi nhà tuyển dụng sẽ hỏi."],["B","They will hire you immediately.","Họ sẽ tuyển bạn ngay lập tức."],["C","It helps you prepare mentally, gain experience, and learn how to communicate your skills effectively.","Nó giúp bạn chuẩn bị tinh thần, tích lũy kinh nghiệm và học cách truyền đạt kỹ năng hiệu quả."],["D","It completely replaces submitting a resume.","Nó hoàn toàn thay thế việc nộp sơ yếu lý lịch."]],"a":"C","s":0,"e":"The professional interview process is fundamentally a high-pressure performance that requires specific communication techniques. Practicing with experienced career counselors provides a safe, constructive environment to emotionally prepare, refine body language, and learn how to articulate academic skills and past experiences into highly compelling, employable assets.","ev":"Quá trình phỏng vấn xin việc chuyên nghiệp về cơ bản là một cuộc thi dưới áp lực cao, đòi hỏi các kỹ thuật giao tiếp cụ thể. Việc luyện tập với các chuyên gia tư vấn nghề nghiệp giàu kinh nghiệm mang lại một môi trường an toàn, mang tính xây dựng để chuẩn bị tâm lý, hoàn thiện ngôn ngữ cơ thể và học cách diễn đạt các kỹ năng học thuật cùng kinh nghiệm đã qua thành những điểm mạnh thuyết phục nhà tuyển dụng.","g":"new","tv":"Lợi ích của việc luyện phỏng vấn với các chuyên viên tư vấn nghề nghiệp là gì?"},{"id":"SSA101_Q203","t":"What is the average cost of tuition for local community colleges mentioned in the text?","o":[["A","About $50,000 per year.","Khoảng 50.000 đô la mỗi năm."],["B","About $100,000 per year.","Khoảng 100.000 đô la mỗi năm."],["C","The text does not give an exact figure, but emphasizes that attending a community college for the first two years can save a lot of money.","Văn bản không đưa ra con số cụ thể, nhưng nhấn mạnh rằng học hai năm đầu ở cao đẳng cộng đồng có thể tiết kiệm rất nhiều tiền."],["D","Community colleges are completely free.","Các trường cao đẳng cộng đồng hoàn toàn miễn phí."]],"a":"C","s":0,"e":"While precise tuition figures fluctuate by region and institution, local community colleges consistently offer significantly lower credit costs compared to traditional four-year universities. By completing foundational general education requirements at a community college during the first two years of study, students can dramatically reduce their overall student debt burden.","ev":"Mặc dù con số học phí chính xác dao động theo khu vực và cơ sở đào tạo, các trường cao đẳng cộng đồng địa phương luôn có chi phí tín chỉ thấp hơn đáng kể so với các trường đại học bốn năm truyền thống. Bằng cách hoàn thành các môn giáo dục đại cương nền tảng tại trường cao đẳng cộng đồng trong hai năm đầu tiên, sinh viên có thể giảm đáng kể tổng gánh nặng nợ sinh viên của mình.","g":"new","tv":"Chi phí học phí trung bình của các trường cao đẳng cộng đồng địa phương được nêu trong văn bản là bao nhiêu?"},{"id":"SSA101_Q204","t":"What is the career planning step of 'Self-Awareness'?","o":[["A","Applying for as many jobs as possible.","Nộp đơn vào càng nhiều công việc càng tốt."],["B","The process of exploring your personal interests, skills, values, and personality traits to find a suitable career path.","Quá trình khám phá sở thích, kỹ năng, giá trị và đặc điểm tính cách cá nhân để tìm con đường nghề nghiệp phù hợp."],["C","Negotiating a starting salary.","Thương lượng mức lương khởi điểm."],["D","Writing a cover letter.","Viết thư xin việc."]],"a":"B","s":0,"e":"Self-awareness serves as the absolute foundational bedrock of intelligent career planning. Before a student can effectively research job markets or safely select a major, they must deeply introspect to discover exactly what tasks they naturally excel at, what core values define their morality, and what specific environments they thrive in, ensuring their ultimate career choice is truly fulfilling.","ev":"Nhận thức về bản thân là nền tảng tuyệt đối của việc lập kế hoạch nghề nghiệp thông minh. Trước khi sinh viên có thể nghiên cứu thị trường việc làm một cách hiệu quả hoặc lựa chọn chuyên ngành phù hợp, họ phải tự nhìn nhận sâu sắc để khám phá những công việc mình làm tốt tự nhiên, những giá trị cốt lõi định hình đạo đức và môi trường cụ thể mà họ phát triển mạnh, đảm bảo lựa chọn nghề nghiệp cuối cùng thực sự viên mãn.","g":"new","tv":"Bước 'Tự nhận thức' trong lập kế hoạch nghề nghiệp là gì?"},{"id":"SSA101_Q205","t":"What is one way a nurse might use 'Creative Thinking' on the job?","o":[["A","By ignoring hospital safety protocols.","Bằng cách phớt lờ các quy trình an toàn của bệnh viện."],["B","By prescribing untested medication.","Bằng cách kê đơn thuốc chưa được kiểm chứng."],["C","By finding an original and effective way to convey patient care information to other medical team members.","Bằng cách tìm ra cách độc đáo và hiệu quả để truyền đạt thông tin chăm sóc bệnh nhân cho các thành viên khác trong nhóm y tế."],["D","By singing to the patient instead of giving an injection.","Bằng cách hát cho bệnh nhân nghe thay vì tiêm."]],"a":"C","s":0,"tv":"What is one way a nurse might use 'tư duy sáng tạo' on the job?","e":"While nursing critically relies on analytical adherence to strict safety protocols, creative thinking is essential for addressing unique human challenges. If a standard communication protocol is repeatedly failing to accurately convey nuances about a patient's condition, a creative nurse will purposefully design an entirely novel, highly efficient communication method to ensure the medical team operates flawlessly.","ev":"Mặc dù nghề điều dưỡng phụ thuộc rất nhiều vào việc tuân thủ nghiêm ngặt các quy trình an toàn, tư duy sáng tạo vẫn rất cần thiết để giải quyết những thách thức đặc thù của con người. Nếu một quy trình giao tiếp tiêu chuẩn liên tục không truyền đạt chính xác các sắc thái về tình trạng bệnh nhân, một điều dưỡng viên sáng tạo sẽ chủ động thiết kế một phương pháp giao tiếp hoàn toàn mới và hiệu quả cao để đảm bảo đội ngũ y tế phối hợp hoàn hảo.","g":"new"},{"id":"SSA101_Q206","t":"What is 'Monitoring' in the financial planning process?","o":[["A","Continually tracking your income, spending, and progress toward your financial goals.","Liên tục theo dõi thu nhập, chi tiêu và tiến độ hướng tới các mục tiêu tài chính của bạn."],["B","Watching the stock market daily.","Theo dõi thị trường chứng khoán hằng ngày."],["C","Letting the bank manage all your money.","Để ngân hàng quản lý toàn bộ tiền của bạn."],["D","Setting a goal and never looking back.","Đặt mục tiêu rồi không bao giờ nhìn lại."]],"a":"A","s":0,"e":"A financial plan is not a static document; it is a dynamic strategy that must adapt directly to reality. Monitoring requires the consistent, ongoing tracking of your daily financial behaviors to ensure your actual spending perfectly matches your projected budget, allowing you to instantly catch deviations and correct your course before missing major financial milestones.","ev":"Kế hoạch tài chính không phải là một văn bản tĩnh; đó là một chiến lược năng động phải thích ứng trực tiếp với thực tế. Việc theo dõi đòi hỏi sự giám sát liên tục, thường xuyên các hành vi tài chính hàng ngày của bạn để đảm bảo chi tiêu thực tế hoàn toàn phù hợp với ngân sách dự kiến, cho phép bạn ngay lập tức phát hiện những sai lệch và điều chỉnh hướng đi trước khi bỏ lỡ các cột mốc tài chính quan trọng.","g":"new","tv":"'Theo dõi' (Monitoring) trong quy trình lập kế hoạch tài chính là gì?"},{"id":"SSA101_Q207","t":"What is the 'Hidden Curriculum' as mentioned in the chapter outlines?","o":[["A","Courses not listed in the course catalog.","Các môn học không được liệt kê trong danh mục môn học."],["B","Test answers hidden in the textbook.","Đáp án bài kiểm tra được giấu trong sách giáo khoa."],["C","The unwritten, unspoken rules and expectations that students must follow to succeed in the college environment","Những quy tắc và kỳ vọng bất thành văn, không nói ra mà sinh viên phải tuân theo để thành công trong môi trường đại học"],["D","A secret club on campus.","Một câu lạc bộ bí mật trong khuôn viên trường."]],"a":"C","s":0,"e":"The \"Hidden Curriculum\" refers to the complex social and academic norms that are rarely explicitly taught but are absolutely crucial for survival in higher education. This includes understanding appropriate email etiquette with professors, knowing exactly when to utilize office hours, seamlessly navigating university bureaucracy, and mastering the unspoken expectations of independent study.","ev":"\"Chương trình học ẩn\" (Hidden Curriculum) đề cập đến các chuẩn mực xã hội và học thuật phức tạp hiếm khi được giảng dạy rõ ràng nhưng lại vô cùng quan trọng để tồn tại ở bậc đại học. Điều này bao gồm việc hiểu quy tắc viết email phù hợp với giảng viên, biết chính xác khi nào nên tận dụng giờ tiếp sinh viên (office hours), xử lý thủ tục hành chính đại học và nắm vững những kỳ vọng bất thành văn của việc tự học.","g":"new","tv":"'Chương trình ngầm' (Hidden Curriculum) được đề cập trong đề cương các chương là gì?"},{"id":"SSA101_Q208","t":"What is the purpose of the 'Rethinking' exercises at the end of textbook chapters?","o":[["A","To provide extra homework assignments.","Cung cấp thêm bài tập về nhà."],["B","To test your short-term memory.","Kiểm tra trí nhớ ngắn hạn của bạn."],["C","To revisit initial survey questions and reflect on how your understanding has changed after learning.","Xem lại các câu hỏi khảo sát ban đầu và suy ngẫm xem sự hiểu biết của bạn đã thay đổi thế nào sau khi học."],["D","To summarize the chapter instead of reading it.","Tóm tắt chương thay vì đọc nó."]],"a":"C","s":0,"e":"\"Rethinking\" exercises forcefully trigger a metacognitive review process, requiring the student to objectively compare their prior assumptions with their newly acquired knowledge. By directly assessing how deeply the chapter altered or enhanced their perspective, the student actively cements the information into long-term memory and verifies that the core learning objectives were successfully achieved.","ev":"Các bài tập \"Suy nghĩ lại\" (Rethinking) kích hoạt mạnh mẽ quá trình đánh giá siêu nhận thức, yêu cầu sinh viên so sánh một cách khách quan những giả định trước đây của họ với kiến thức mới thu được. Bằng cách đánh giá trực tiếp mức độ chương học đã thay đổi hoặc nâng cao góc nhìn của mình, sinh viên chủ động củng cố thông tin vào trí nhớ dài hạn và xác minh rằng các mục tiêu học tập cốt lõi đã đạt được thành công.","g":"new","tv":"Mục đích của các bài tập 'Suy nghĩ lại' (Rethinking) ở cuối các chương sách giáo khoa là gì?"},{"id":"SSA101_Q209","t":"What is the 'Occupational Outlook Handbook' used for?","o":[["A","To find the easiest classes in college.","Tìm các lớp học dễ nhất ở đại học."],["B","To research requirements for careers and identify fields with good job growth prospects.","Nghiên cứu yêu cầu của các nghề nghiệp và xác định các lĩnh vực có triển vọng tăng trưởng việc làm tốt."],["C","To apply for financial aid.","Nộp đơn xin hỗ trợ tài chính."],["D","To track your daily schedule.","Theo dõi lịch trình hằng ngày của bạn."]],"a":"B","s":0,"e":"Produced by the government, the Occupational Outlook Handbook is an indispensable, data-driven tool for pragmatic career planning. It provides students with highly accurate statistical profiles on thousands of professions, detailing extreme specifics like median salaries, required educational degrees, daily responsibilities, and projected industry job growth rates over the next decade.","ev":"Được chính phủ biên soạn, Cẩm nang Triển vọng Nghề nghiệp là một công cụ không thể thiếu dựa trên dữ liệu giúp lập kế hoạch nghề nghiệp thực tiễn. Nó cung cấp cho sinh viên những hồ sơ thống kê có độ chính xác cao về hàng nghìn ngành nghề, nêu chi tiết các thông số cụ thể như mức lương trung vị, bằng cấp yêu cầu, trách nhiệm hàng ngày và tỷ lệ tăng trưởng việc làm dự kiến trong thập kỷ tới.","g":"new","tv":"'Sổ tay Triển vọng Nghề nghiệp' (Occupational Outlook Handbook) được dùng để làm gì?"},{"id":"SSA101_Q210","t":"What is the risk of setting goals that are not truly your own?","o":[["A","You will complete them too quickly.","Bạn sẽ hoàn thành chúng quá nhanh."],["B","You will be accused of plagiarism.","Bạn sẽ bị cáo buộc đạo văn."],["C","You will have very little motivation to achieve them because you don't actually care.","Bạn sẽ có rất ít động lực để đạt được chúng vì bạn thực sự không quan tâm."],["D","Your academic advisor will not approve them.","Cố vấn học tập của bạn sẽ không phê duyệt chúng."]],"a":"C","s":0,"e":"True, sustainable motivation must come from within; it requires a deep, personal connection to the ultimate outcome. If you adopt goals dictated entirely by societal pressure, family expectations, or peer influence, you will lack the crucial intrinsic drive required to push through inevitable academic hardships, making you highly susceptible to severe burnout and failure.","ev":"Động lực bền vững thực sự phải đến từ bên trong; nó đòi hỏi một sự kết nối sâu sắc, cá nhân với kết quả cuối cùng. Nếu bạn đặt ra những mục tiêu hoàn toàn do áp lực xã hội, kỳ vọng gia đình hoặc ảnh hưởng của bạn bè chi phối, bạn sẽ thiếu động lực nội tại cần thiết để vượt qua những khó khăn học tập không thể tránh khỏi, khiến bạn rất dễ bị kiệt sức và thất bại nghiêm trọng.","g":"new","tv":"Rủi ro của việc đặt ra những mục tiêu không thực sự là của bạn là gì?"},{"id":"SSA101_Q211","t":"What is one common reason people waste time during the day?","o":[["A","They have too many entertainment apps on their phones.","Họ có quá nhiều ứng dụng giải trí trên điện thoại."],["B","Being constrained by schedules and lacking the awareness to effectively repurpose short \"waiting times\" (15-20 minutes).","Bị ràng buộc bởi lịch trình và thiếu nhận thức để tận dụng hiệu quả những \"khoảng chờ\" ngắn (15–20 phút)."],["C","They sleep more than 8 hours a night.","Họ ngủ hơn 8 tiếng mỗi đêm."],["D","They spend too much time planning.","Họ dành quá nhiều thời gian lập kế hoạch."]],"a":"B","s":0,"tv":"Một lý do phổ biến mà people waste time during the day là gì?","e":"Many students mistakenly believe that productive studying requires uninterrupted blocks of several hours, leading them to completely ignore shorter, 15-to-20-minute gaps between scheduled classes or appointments. This lack of awareness causes them to passively waste these highly valuable \"waiting times,\" significantly reducing their total daily productivity and forcing them to sacrifice their evening rest to catch up.","ev":"Nhiều sinh viên lầm tưởng rằng việc học tập hiệu quả đòi hỏi những khoảng thời gian liên tục kéo dài vài giờ, dẫn đến việc họ hoàn toàn bỏ qua những khoảng thời gian ngắn hơn từ 15 đến 20 phút giữa các tiết học hoặc cuộc hẹn. Sự thiếu nhận thức này khiến họ lãng phí một cách thụ động những \"thời gian chờ\" quý giá, làm giảm đáng kể năng suất hàng ngày và buộc phải hy sinh thời gian nghỉ ngơi buổi tối để học bù.","g":"new"},{"id":"SSA101_Q212","t":"What is the intended outcome of the 'After Class' task of testing yourself?","o":[["A","To start the studying process and assess whether you understand the material.","Bắt đầu quá trình học và đánh giá xem bạn có hiểu tài liệu không."],["B","To memorize the textbook word-for-word.","Học thuộc lòng sách giáo khoa từng chữ."],["C","To replace taking notes in class.","Thay thế việc ghi chép trên lớp."],["D","To prepare for an immediate pop quiz.","Chuẩn bị cho một bài kiểm tra bất ngờ ngay lập tức."]],"a":"A","s":0,"e":"Self-testing immediately after a lecture acts as a highly effective diagnostic tool to measure your actual comprehension versus your assumed comprehension. By proactively challenging your memory without looking at your notes, you instantly identify which specific concepts you have mastered and which areas require immediate review, thereby launching a highly efficient study cycle.","ev":"Việc tự kiểm tra ngay sau bài giảng là một công cụ chẩn đoán cực kỳ hiệu quả để đo lường mức độ hiểu bài thực tế so với mức độ hiểu bài mà bạn cho là đúng. Bằng cách chủ động kiểm tra trí nhớ mà không nhìn vào ghi chú, bạn ngay lập tức xác định được những khái niệm nào mình đã nắm vững và những phần nào cần ôn tập ngay, qua đó khởi động một chu trình học tập hiệu quả cao.","g":"new","tv":"Kết quả mong muốn của nhiệm vụ 'Sau giờ học' là tự kiểm tra bản thân là gì?"},{"id":"SSA101_Q213","t":"What is the primary benefit of being 'financially literate'?","o":[["A","It allows you to become a stockbroker","Nó cho phép bạn trở thành nhà môi giới chứng khoán"],["B","It allows you to do more of what you want with your life by working hard, separating needs from wants, and avoiding debt pitfalls.","Nó cho phép bạn làm nhiều hơn những gì mình muốn trong cuộc sống bằng cách làm việc chăm chỉ, phân biệt nhu cầu với mong muốn và tránh các cạm bẫy nợ nần."],["C","It guarantees you will be rich immediately after college","Nó đảm bảo bạn sẽ giàu ngay sau khi tốt nghiệp"],["D","It eliminates the need to pay taxes","Nó loại bỏ nhu cầu đóng thuế"]],"a":"B","s":0,"e":"The ultimate primary benefit of achieving strong financial literacy is the acquisition of total personal freedom. By deeply understanding how to budget effectively, separate fleeting desires from genuine needs, and aggressively avoid toxic debt pitfalls, you secure the financial stability necessary to confidently pursue your true life goals on your own terms.","ev":"Lợi ích quan trọng nhất của việc đạt được kiến thức tài chính vững chắc là sự tự do cá nhân tuyệt đối. Bằng cách hiểu sâu sắc cách lập ngân sách hiệu quả, phân biệt giữa những mong muốn nhất thời và nhu cầu thực sự, và chủ động tránh những cạm bẫy nợ nần, bạn sẽ đảm bảo được sự ổn định tài chính cần thiết để tự tin theo đuổi mục tiêu cuộc sống thực sự của mình.","g":"new","tv":"Lợi ích chính của việc 'am hiểu tài chính' là gì?"},{"id":"SSA101_Q214","t":"What is the 'Career Planning Cycle' used for?","o":[["A","To find a job immediately after high school","Để tìm việc ngay sau khi tốt nghiệp trung học"],["B","To determine which professors are the easiest graders","Để xác định giảng viên nào chấm điểm dễ nhất"],["C","To apply concrete steps to figure out where you might fit into the work world and to reconsider your approach and progress","Để áp dụng các bước cụ thể nhằm tìm ra vị trí phù hợp của bạn trong thế giới việc làm và xem xét lại cách tiếp cận và tiến độ của bạn"],["D","To guarantee a high salary upon graduation","Để đảm bảo mức lương cao khi tốt nghiệp"]],"a":"C","s":0,"e":"The Career Planning Cycle is a dynamic, ongoing structured framework designed to guide professional development. It forces individuals to apply concrete, actionable steps to continuously assess their evolving skills, explore where they naturally fit into the modern work world, and regularly reconsider their trajectory to ensure long-term career satisfaction.","ev":"Chu trình lập kế hoạch nghề nghiệp là một khuôn khổ có cấu trúc, năng động và liên tục được thiết kế để hướng dẫn sự phát triển chuyên nghiệp. Nó buộc các cá nhân phải áp dụng các bước cụ thể, khả thi để liên tục đánh giá các kỹ năng đang phát triển của mình, khám phá vị trí phù hợp tự nhiên của họ trong thế giới công việc hiện đại và thường xuyên xem xét lại lộ trình để đảm bảo sự hài lòng nghề nghiệp lâu dài.","g":"new","tv":"'Chu trình lập kế hoạch nghề nghiệp' được dùng để làm gì?"},{"id":"SSA101_Q215","t":"What is the first step in identifying wasted time in a daily schedule?","o":[["A","Asking a friend to track your movements","Nhờ một người bạn theo dõi các hoạt động của bạn"],["B","Immediately cutting out all leisure activities","Cắt bỏ ngay mọi hoạt động giải trí"],["C","Analyzing your schedule to identify areas where you can recapture and repurpose time","Phân tích lịch trình để xác định những chỗ bạn có thể tận dụng lại và dùng lại thời gian"],["D","Downloading a complex time-management app","Tải về một ứng dụng quản lý thời gian phức tạp"]],"a":"C","s":0,"e":"You cannot fix a time management problem if you do not know where your time is actually going. Therefore, the crucial first step is to objectively record and analyze your current daily routine to pinpoint exactly where time is being inefficiently wasted on low-value activities so that you can consciously recapture and repurpose those hours.","ev":"Bạn không thể khắc phục vấn đề quản lý thời gian nếu bạn không biết thời gian của mình thực sự đang đi đâu. Do đó, bước đầu tiên quan trọng là ghi chép và phân tích một cách khách quan thói quen hàng ngày hiện tại để xác định chính xác nơi thời gian đang bị lãng phí vào các hoạt động ít giá trị, từ đó chủ động thu hồi và tái sử dụng những giờ đó.","g":"new","tv":"Bước đầu tiên để xác định thời gian bị lãng phí trong lịch trình hằng ngày là gì?"},{"id":"SSA101_Q216","t":"What is the 'simplest way' to manage time according to the text?","o":[["A","Use a digital calendar with automated reminders","Dùng lịch số có nhắc nhở tự động"],["B","Multitask by doing several assignments at once","Làm nhiều việc cùng lúc bằng cách làm nhiều bài tập một lúc"],["C","Accurately plan how much time a task will take and set aside that amount of time","Lên kế hoạch chính xác một nhiệm vụ cần bao nhiêu thời gian và dành ra đúng lượng thời gian đó"],["D","Prioritize tasks based on which are the most enjoyable","Ưu tiên các nhiệm vụ dựa trên việc nhiệm vụ nào thú vị nhất"]],"a":"C","s":0,"e":"The simplest and most highly recommended way to manage time is realistic time blocking. By accurately estimating exactly how much time a specific task will take and formally dedicating that block of time to it in your schedule, you prevent tasks from overlapping, reduce the temptation to procrastinate, and ensure steady progress.","ev":"Cách đơn giản và được khuyên dùng nhất để quản lý thời gian là lập kế hoạch thời gian thực tế (time blocking). Bằng cách ước tính chính xác thời gian cần thiết cho một nhiệm vụ cụ thể và dành riêng khoảng thời gian đó cho nó trong lịch trình của bạn, bạn sẽ tránh được tình trạng chồng chéo công việc, giảm bớt cám dỗ trì hoãn và đảm bảo tiến độ ổn định.","g":"new","tv":"Theo văn bản, 'cách đơn giản nhất' để quản lý thời gian là gì?"},{"id":"SSA101_Q217","t":"What is the recommended task regarding reading before a class session begins?","o":[["A","Read the summary of the chapter only to save time","Chỉ đọc phần tóm tắt chương để tiết kiệm thời gian"],["B","Wait until after the lecture to read so you understand the context better","Chờ đến sau bài giảng mới đọc để hiểu bối cảnh tốt hơn"],["C","Read the assigned material to make the lecture and complex concepts easier to follow","Đọc tài liệu được giao để bài giảng và các khái niệm phức tạp dễ theo dõi hơn"],["D","Skim the bolded terms and look at the graphics","Lướt qua các thuật ngữ in đậm và xem hình ảnh"]],"a":"C","s":0,"e":"Reading the assigned material before a class session is fundamentally necessary to build a baseline understanding of the topic. This proactive approach ensures that when the instructor presents complex concepts, you already have a foundation. Consequently, the lecture becomes significantly easier to follow, allowing you to transition from simply trying to comprehend the basics to actively engaging with the material.","ev":"Đọc tài liệu được giao trước buổi học là điều cần thiết về mặt cơ bản để xây dựng nền tảng hiểu biết về chủ đề. Cách tiếp cận chủ động này đảm bảo rằng khi giảng viên trình bày các khái niệm phức tạp, bạn đã có sẵn nền tảng, nhờ đó bài giảng trở nên dễ theo dõi hơn nhiều và giúp bạn chuyển từ việc chỉ cố gắng hiểu kiến thức cơ bản sang tích cực tương tác với tài liệu.","g":"new","tv":"Nhiệm vụ được khuyến nghị liên quan đến việc đọc trước khi buổi học bắt đầu là gì?"},{"id":"SSA101_Q218","t":"What was the primary ethical issue discovered in the AI-based recruiting tool that was implemented and subsequently scrapped by Amazon in 2018?","o":[["A","The system required candidates to pay exorbitant processing fees to access the portal, which severely exacerbated existing socioeconomic inequalities","Hệ thống yêu cầu ứng viên trả phí xử lý cắt cổ để truy cập cổng thông tin, làm trầm trọng thêm bất bình đẳng kinh tế xã hội hiện có"],["B","The system consistently downgraded the resumes of female candidates because it was trained on ten years of historically male-dominated data","Hệ thống liên tục hạ điểm hồ sơ của ứng viên nữ vì được huấn luyện trên dữ liệu mười năm do nam giới chiếm ưu thế"],["C","The system utilized unauthorized facial recognition algorithms to monitor candidates' expressions and reactions during the virtual interview process","Hệ thống dùng thuật toán nhận diện khuôn mặt trái phép để theo dõi biểu cảm và phản ứng của ứng viên trong buổi phỏng vấn trực tuyến"],["D","The system generated fabricated educational backgrounds for numerous applicants, leading to widespread hallucinations and false credential verifications","Hệ thống tạo ra lý lịch học vấn giả cho nhiều ứng viên, dẫn đến ảo giác lan rộng và xác minh bằng cấp sai"]],"a":"B","s":0,"e":"Machine learning algorithms inevitably inherit the internal biases of their strictly historical training data. Because Amazon's AI recruiting tool was trained on ten years of historically male-dominated tech industry resumes, the software \"learned\" that male candidates were statistically preferable, resulting in the algorithm systematically downgrading and actively penalizing resumes submitted by highly qualified women.","ev":"Các thuật toán học máy chắc chắn thừa hưởng những thiên kiến nội tại từ dữ liệu huấn luyện mang tính lịch sử của chúng. Bởi vì công cụ tuyển dụng AI của Amazon được huấn luyện trên dữ liệu hồ sơ ngành công nghệ trong mười năm vốn do nam giới thống trị, phần mềm đã \"học\" rằng ứng viên nam được ưu tiên hơn về mặt thống kê, dẫn đến việc thuật toán hạ thấp và đánh giá bất lợi đối với hồ sơ của những phụ nữ có trình độ cao.","g":"new","tv":"Vấn đề đạo đức chính được phát hiện ở công cụ tuyển dụng dùng AI mà Amazon triển khai rồi loại bỏ vào năm 2018 là gì?"},{"id":"SSA101_Q219","t":"What does the term \"Hallucinations\" in Large Language Models (LLMs) refer to?","o":[["A","The AI generating highly abstract, surreal, and unrealistic visual images when prompted to create realistic photographs","AI tạo ra hình ảnh rất trừu tượng, siêu thực và phi thực tế khi được yêu cầu tạo ảnh chân thực"],["B","Users becoming overly dependent on the software and holding unrealistic illusions about the true technological capabilities of AI","Người dùng phụ thuộc quá mức vào phần mềm và có ảo tưởng không thực tế về khả năng công nghệ thật sự của AI"],["C","The AI producing text responses that sound highly plausible but are actually factually incorrect or entirely fabricated by the system.","AI tạo ra các câu trả lời văn bản nghe rất hợp lý nhưng thực tế sai sự thật hoặc hoàn toàn do hệ thống bịa ra."],["D","The AI consistently misidentifying specific human faces or expressions when utilized in advanced facial recognition security tools","AI liên tục nhận diện sai khuôn mặt hoặc biểu cảm của con người khi dùng trong các công cụ bảo mật nhận diện khuôn mặt tiên tiến"]],"a":"C","s":0,"e":"Large Language Models function by probabilistically predicting the next word in a sequence based on vast training data, not by actually understanding factual reality. A \"hallucination\" occurs when the algorithm strings together highly confident, perfectly grammatical sentences that effectively fabricate historical events, fake academic citations, or entirely false information that sounds flawlessly plausible.","ev":"Các mô hình ngôn ngữ lớn hoạt động bằng cách dự đoán xác suất từ tiếp theo trong một chuỗi dựa trên dữ liệu huấn luyện khổng lồ, chứ không phải bằng cách thực sự hiểu thực tế khách quan. Hiện tượng \"ảo giác\" (hallucination) xảy ra khi thuật toán ghép nối những câu văn đúng ngữ pháp và đầy tự tin nhưng thực chất lại bịa đặt các sự kiện lịch sử, trích dẫn học thuật giả mạo hoặc thông tin hoàn toàn sai lệch nghe có vẻ rất hợp lý.","g":"new","tv":"Thuật ngữ \"Ảo giác\" (Hallucinations) trong các Mô hình ngôn ngữ lớn (LLM) có nghĩa là gì?"},{"id":"SSA101_Q220","t":"What does 'true learning' mean beyond just earning high grades?","o":[["A","Getting a piece of paper that guarantees a job.","Có một tờ giấy đảm bảo việc làm."],["B","Never making a mistake.","Không bao giờ mắc lỗi."],["C","It is a transformative process that expands your mind, challenges your identity, and helps you handle real-world situations.","Đó là một quá trình biến đổi giúp mở mang trí óc, thử thách bản sắc của bạn và giúp bạn xử lý các tình huống thực tế."],["D","Memorizing every small detail in the textbook.","Học thuộc từng chi tiết nhỏ trong sách giáo khoa."]],"a":"C","s":0,"e":"While grades temporarily measure academic compliance, \"true learning\" permanently alters how a person interacts with the world. It involves developing highly adaptable critical thinking skills, confronting and adjusting personal biases, and synthesizing diverse knowledge to successfully navigate complex, unpredictable challenges in both your professional career and personal life.","ev":"Trong khi điểm số chỉ tạm thời đo lường sự tuân thủ chương trình học, \"việc học thực sự\" sẽ thay đổi vĩnh viễn cách một người tương tác với thế giới. Nó bao gồm việc phát triển các kỹ năng tư duy phản biện linh hoạt, đối mặt và điều chỉnh thiên kiến cá nhân, đồng thời tổng hợp kiến thức đa dạng để xử lý thành công những thách thức phức tạp, khó lường trong cả sự nghiệp lẫn đời sống cá nhân.","g":"new","tv":"'Học tập thực sự' có nghĩa gì ngoài việc đạt điểm cao?"},{"id":"SSA101_Q221","t":"What should a student do with their notes immediately after a class session?","o":[["A","Put them in a folder and do not look at them until the midterm","Bỏ vào một thư mục và không xem lại cho đến kỳ thi giữa kỳ"],["B","Review and rewrite them, adding in any missing details or clarifications","Xem lại và viết lại, bổ sung các chi tiết hoặc phần làm rõ còn thiếu"],["C","Type them out word-for-word to ensure they are neat","Gõ lại từng chữ để đảm bảo gọn gàng"],["D","Share them immediately with a classmate who missed the lecture","Chia sẻ ngay với bạn học đã vắng buổi giảng"]],"a":"B","s":0,"e":"Immediately after a class, while the lecture content is still fresh in your short-term memory, reviewing and rewriting your notes is critical. This practice allows you to spot gaps, fix unclear phrasing, and add valuable context that you mentally remember but didn't have time to write down, creating a highly reliable study resource for future exams.","ev":"Ngay sau giờ học, khi nội dung bài giảng vẫn còn mới mẻ trong trí nhớ ngắn hạn, việc xem lại và viết lại ghi chú là vô cùng quan trọng. Thói quen này giúp bạn phát hiện ra những lỗ hổng, sửa chữa cách diễn đạt chưa rõ ràng và bổ sung ngữ cảnh giá trị mà bạn nhớ trong đầu nhưng chưa kịp ghi lại, tạo thành tài liệu ôn tập đáng tin cậy cho các kỳ thi sau này.","g":"new","tv":"Sinh viên nên làm gì với ghi chú của mình ngay sau buổi học?"},{"id":"SSA101_Q222","t":"What should a student do with their resume throughout college?","o":[["A","Write it once in freshman year and never look at it again.","Viết một lần vào năm nhất và không bao giờ xem lại."],["B","Continuously update it as they acquire new Knowledge, Skills, Abilities (KSAs), and experiences.","Liên tục cập nhật khi có thêm Kiến thức, Kỹ năng, Năng lực (KSA) và kinh nghiệm mới."],["C","Copy a friend's resume.","Sao chép sơ yếu lý lịch của bạn bè."],["D","Wait until the day before graduation to start writing it.","Chờ đến ngày trước khi tốt nghiệp mới bắt đầu viết."]],"a":"B","s":0,"e":"A resume is not a static historical document; it is a continuously evolving professional marketing tool. As students progress through college, they constantly acquire new Knowledge, Skills, Abilities (KSAs), leadership roles, and internship experiences, meaning their resume must be regularly updated to accurately reflect their growing value and readiness for the post-graduation job market.","ev":"Sơ yếu lý lịch không phải là một tài liệu lịch sử tĩnh; nó là một công cụ tiếp thị chuyên nghiệp liên tục phát triển. Khi sinh viên học tập trong suốt quá trình bậc đại học, họ liên tục tiếp thu Kiến thức, Kỹ năng, Khả năng (KSAs) mới, đảm nhận vai trò lãnh đạo và tích lũy kinh nghiệm thực tập, do đó hồ sơ phải được cập nhật thường xuyên để phản ánh chính xác giá trị và mức độ sẵn sàng cho thị trường lao động sau tốt nghiệp.","g":"new","tv":"Sinh viên nên làm gì với sơ yếu lý lịch của mình trong suốt thời gian học đại học?"},{"id":"SSA101_Q223","t":"Which of the following is a recommended visual technique for individuals attempting to identify hyper-realistic \"deep fake\" media?","o":[["A","Trusting the emotional resonance of the media content and relying exclusively on mainstream social media platforms for rapid, community-based fact-checking","Tin vào sức hút cảm xúc của nội dung và chỉ dựa vào các nền tảng mạng xã hội phổ biến để kiểm chứng nhanh bằng cộng đồng"],["B","Searching for subtle inconsistencies in lighting, shadows, unnatural facial movements, mismatched lip-syncing, and irregular or absent blinking patterns","Tìm các điểm bất nhất tinh vi về ánh sáng, bóng đổ, chuyển động khuôn mặt không tự nhiên, môi không khớp tiếng và kiểu chớp mắt bất thường hoặc không có"],["C","Assuming that all digital videos featuring high-profile politicians or celebrities are inherently fabricated by advanced generative artificial intelligence algorithms","Cho rằng mọi video kỹ thuật số có chính trị gia hoặc người nổi tiếng đều bị thuật toán AI tạo sinh tiên tiến làm giả"],["D","Using strictly text-based large language models to analyze the video files and automatically generate a highly conclusive report on the media's authenticity","Chỉ dùng các mô hình ngôn ngữ lớn dựa trên văn bản để phân tích tệp video và tự động tạo báo cáo kết luận về tính xác thực"]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là a recommended visual technique for individuals attempting to identify hyper-realistic \"deep fake\" media?","e":"While generative AI excels at replicating the broad strokes of a human face, it frequently struggles with precise physiological minutiae. To critically identify a \"deep fake,\" digital analysts are trained to systematically search for extremely subtle visual glitches: unnatural lighting artifacts, mismatched lip-syncing, anatomical irregularities, or the complete absence of normal human micro-expressions like blinking.","ev":"Mặc dù trí tuệ nhân tạo tạo sinh (generative AI) rất giỏi trong việc tái tạo những đường nét tổng thể của khuôn mặt người, nhưng nó thường gặp khó khăn với những chi tiết sinh lý chính xác. Để nhận diện một \"deep fake\", các nhà phân tích kỹ thuật số tìm kiếm những lỗi hình ảnh tinh vi như ánh sáng bất thường, khẩu hình không khớp, sự bất thường về giải phẫu hoặc việc thiếu hoàn toàn các biểu cảm tự nhiên như chớp mắt.","g":"new"},{"id":"SSA101_Q224","t":"Which of the following best describes the \"Monitoring\" phase in the Plan-Monitor-Evaluate model of metacognition?","o":[["A","You are continuously assessing what you have already learned, identifying what you do not yet know, and determining if your current study strategies are working effectively","Bạn liên tục đánh giá những gì đã học, xác định những gì chưa biết và xác định xem các chiến lược học hiện tại có hiệu quả không"],["B","You are reflecting on how well you met your overall learning objectives after completely finishing a unit of study or receiving feedback from a recent course assignment","Bạn suy ngẫm xem mình đạt các mục tiêu học tập tổng thể tốt đến đâu sau khi hoàn toàn kết thúc một đơn vị học hoặc nhận phản hồi từ một bài tập gần đây"],["C","You are deciding exactly what material you need to learn for an upcoming exam and selecting the specific active learning strategies you will use to master that material","Bạn quyết định chính xác cần học tài liệu nào cho kỳ thi sắp tới và chọn các chiến lược học tích cực cụ thể để nắm vững tài liệu đó"],["D","You are reviewing your final exam answers to compare them with the instructor's suggested answers to see which key components were entirely missed during the test","Bạn xem lại câu trả lời bài thi cuối kỳ để so sánh với đáp án gợi ý của giảng viên nhằm xem những ý chính nào đã bị bỏ sót hoàn toàn"]],"a":"A","s":0,"e":"Metacognitive monitoring is an active, ongoing, and highly critical self-assessment process that occurs simultaneously with studying. It requires the student to continuously test their own comprehension in real-time—identifying exactly what concepts they have successfully mastered and forcefully questioning whether their current study strategies are actually proving effective or if they need immediate adjustment.","ev":"Giám sát siêu nhận thức là một quá trình tự đánh giá chủ động, liên tục và vô cùng quan trọng diễn ra đồng thời với việc học tập. Nó đòi hỏi sinh viên phải liên tục kiểm tra khả năng hiểu bài của chính mình theo thời gian thực—xác định chính xác những khái niệm đã nắm vững và đánh giá xem các chiến lược học tập hiện tại có thực sự hiệu quả hay cần điều chỉnh ngay lập tức.","g":"new","tv":"Mô tả nào đúng nhất về giai đoạn \"Theo dõi\" trong mô hình Lập kế hoạch – Theo dõi – Đánh giá của siêu nhận thức?"},{"id":"SSA101_Q225","t":"How does 'Critical Thinking' assist a student in identifying exam material?","o":[["A","By asking the professor to reveal the test questions","Bằng cách nhờ giảng viên tiết lộ câu hỏi thi"],["B","By using data (like careful class notes) and reasoning to deduce what core content the professor might include on the exam.","Bằng cách dùng dữ liệu (như ghi chú lớp học cẩn thận) và lập luận để suy ra nội dung cốt lõi mà giảng viên có thể đưa vào kỳ thi."],["C","By blindly guessing the questions.","Bằng cách đoán mò câu hỏi."],["D","By only studying the hardest questions.","Bằng cách chỉ học các câu khó nhất."]],"a":"B","s":0,"tv":"How does 'tư duy phản biện' assist a student in identifying exam material?","e":"Instead of passively trying to memorize the entire textbook, a critical thinker actively analyzes the instructor's behavior, lecture emphasis, repeated themes, and syllabus structure. By logically synthesizing these contextual clues, the student can highly accurately deduce the core concepts most likely to be tested, thereby optimizing their limited study time for maximum efficiency.","ev":"Thay vì thụ động cố gắng ghi nhớ toàn bộ sách giáo khoa, người tư duy phản biện chủ động phân tích hành vi của giảng viên, trọng tâm bài giảng, các chủ đề lặp đi lặp lại và cấu trúc chương trình học. Bằng cách tổng hợp hợp lý những manh mối ngữ cảnh này, sinh viên có thể suy luận khá chính xác các khái niệm cốt lõi có khả năng cao sẽ được kiểm tra, qua đó tối ưu hóa thời gian ôn tập để đạt hiệu quả cao nhất.","g":"new"},{"id":"SSA101_Q226","t":"How do academic advisors help with career exploration?","o":[["A","They guarantee you a job right after graduation.","Họ đảm bảo bạn có việc ngay sau khi tốt nghiệp."],["B","They help you set educational/career goals, choose a major, and connect you with career services.","Họ giúp bạn đặt mục tiêu học tập/nghề nghiệp, chọn ngành và kết nối bạn với trung tâm hướng nghiệp."],["C","They write your resume and cover letter for you.","Họ viết sơ yếu lý lịch và thư xin việc cho bạn."],["D","They provide loans to pay for your tuition.","Họ cho vay tiền để trả học phí của bạn."]],"a":"B","s":0,"e":"Academic advisors act as vital strategic partners who deeply understand both the university's complex curriculum and the broader professional landscape. They can successfully translate your vague personal interests into concrete educational pathways, ensure you are taking the correct prerequisites for your desired field, and directly connect you with practical campus career resources.","ev":"Cố vấn học thuật đóng vai trò là đối tác chiến lược quan trọng, am hiểu sâu sắc cả chương trình giảng dạy phức tạp của trường đại học và bối cảnh nghề nghiệp rộng lớn hơn. Họ có thể chuyển hóa sở thích cá nhân mơ hồ của bạn thành lộ trình học tập cụ thể, đảm bảo bạn học đúng các môn tiên quyết cho lĩnh vực mong muốn và kết nối trực tiếp bạn với các nguồn lực hỗ trợ nghề nghiệp thiết thực tại trường.","g":"new","tv":"Cố vấn học tập giúp ích như thế nào trong việc khám phá nghề nghiệp?"},{"id":"SSA101_Q227","t":"How does breaking a goal down into manageable tasks aid in completion?","o":[["A","Accomplishing the whole is easier when each part is tackled individually","Hoàn thành tổng thể dễ hơn khi từng phần được xử lý riêng"],["B","It makes the goal look larger and more impressive","Nó làm mục tiêu trông lớn hơn và ấn tượng hơn"],["C","It allows you to procrastinate on the smaller parts","Nó cho phép bạn trì hoãn các phần nhỏ hơn"],["D","It removes the need for a timeline","Nó loại bỏ nhu cầu có mốc thời gian"]],"a":"A","s":0,"e":"Confronting a massive goal all at once can quickly lead to feelings of overwhelm and paralysis. By breaking the larger goal down into several smaller, highly manageable, and actionable tasks, you create a clear roadmap. Completing each individual step provides immediate psychological rewards and builds positive momentum, making the overarching goal feel significantly more achievable.","ev":"Đối mặt với một mục tiêu khổng lồ cùng một lúc có thể nhanh chóng dẫn đến cảm giác choáng ngợp và tê liệt. Bằng cách chia nhỏ mục tiêu lớn thành nhiều nhiệm vụ nhỏ hơn, dễ quản lý và có tính khả thi cao, bạn tạo ra một lộ trình rõ ràng. Việc hoàn thành từng bước riêng lẻ mang lại phần thưởng tâm lý tức thì và tạo động lực tích cực, khiến mục tiêu tổng thể trở nên khả thi hơn nhiều.","g":"new","tv":"Việc chia nhỏ một mục tiêu thành các nhiệm vụ dễ quản lý giúp hoàn thành mục tiêu như thế nào?"},{"id":"SSA101_Q228","t":"How does annotating graphics differ from annotating text?","o":[["A","Graphics do not need any annotations.","Đồ họa không cần bất kỳ chú thích nào."],["B","Deciphering graphics takes time, so you might want to create a copy before annotating to avoid making the information messy.","Giải mã đồ họa mất thời gian, nên bạn có thể muốn tạo một bản sao trước khi chú thích để tránh làm thông tin lộn xộn."],["C","Graphics should only be highlighted in yellow.","Đồ họa chỉ nên được đánh dấu bằng màu vàng."],["D","Graphics should be memorized instead of annotated.","Đồ họa nên được học thuộc thay vì chú thích."]],"a":"B","s":0,"e":"Unlike standard text, academic graphics (such as complex charts, graphs, or anatomical diagrams) pack an immense amount of dense, interconnected data into a very small visual space. Because initial attempts to understand and label these visuals can easily become cluttered and illegible, making a separate copy to freely annotate ensures you reliably preserve the pristine original graphic for clear, long-term reference.","ev":"Khác với văn bản thông thường, các hình ảnh học thuật (như biểu đồ phức tạp, đồ thị hoặc sơ đồ giải phẫu) chứa một lượng dữ liệu khổng lồ, dày đặc và liên kết chặt chẽ trong một không gian thị giác rất nhỏ. Vì những nỗ lực ban đầu để hiểu và ghi chú lên các hình ảnh này dễ trở nên lộn xộn và khó đọc, việc tạo một bản sao riêng để thoải mái chú thích sẽ đảm bảo bạn giữ nguyên được bản gốc sạch sẽ để tham khảo lâu dài.","g":"new","tv":"Việc chú thích đồ họa khác với chú thích văn bản như thế nào?"},{"id":"SSA101_Q229","t":"How does 'Metacognition' improve problem-solving?","o":[["A","By increasing your reading speed.","Bằng cách tăng tốc độ đọc của bạn."],["B","By practicing self-awareness, helping you recognize knowledge gaps and adjust problem-solving strategies promptly.","Bằng cách rèn luyện sự tự nhận thức, giúp bạn nhận ra các lỗ hổng kiến thức và điều chỉnh chiến lược giải quyết vấn đề kịp thời."],["C","By relying strictly on emotions to make decisions.","Bằng cách chỉ dựa vào cảm xúc để ra quyết định."],["D","By helping you rote-memorize faster.","Bằng cách giúp bạn học vẹt nhanh hơn."]],"a":"B","s":0,"tv":"How does 'Metacognition' improve giải quyết vấn đề?","e":"Because metacognition involves \"thinking about your thinking,\" it allows a student to objectively monitor their own thought processes while tackling a difficult problem. This acute self-awareness ensures that if a specific approach is clearly failing, the student instantly recognizes the impasse, abandons the ineffective method, and strategically pivots to a better solution rather than blindly wasting time.","ev":"Vì siêu nhận thức liên quan đến việc \"suy nghĩ về suy nghĩ của chính mình\", nó cho phép sinh viên theo dõi một cách khách quan quá trình tư duy của bản thân khi giải quyết một vấn đề khó. Sự tự nhận thức sắc bén này đảm bảo rằng nếu một cách tiếp cận rõ ràng đang thất bại, sinh viên ngay lập tức nhận ra bế tắc, từ bỏ phương pháp kém hiệu quả và chuyển sang giải pháp tốt hơn thay vì lãng phí thời gian.","g":"new"},{"id":"SSA101_Q230","t":"How can a balance sheet help a student in the future?","o":[["A","It helps balance their class schedule.","Nó giúp cân bằng thời khóa biểu của họ."],["B","It provides a comprehensive picture (\"snapshot\") of assets and liabilities, allowing them to track financial progress at a point in time.","Nó cung cấp bức tranh toàn diện (\"ảnh chụp nhanh\") về tài sản và nợ phải trả, cho phép họ theo dõi tiến độ tài chính tại một thời điểm."],["C","It automatically pays bills.","Nó tự động thanh toán các hóa đơn."],["D","It prevents students from getting into debt.","Nó ngăn sinh viên mắc nợ."]],"a":"B","s":0,"e":"A personal balance sheet is a vital financial diagnostic tool that explicitly lists everything a student owns (assets) versus everything they owe (liabilities) on a specific date. By regularly generating this objective \"snapshot,\" students can accurately measure exactly how much their net worth has grown, ensuring their long-term financial strategies are actually working.","ev":"Bảng cân đối tài chính cá nhân là một công cụ chẩn đoán tài chính quan trọng, liệt kê rõ ràng tất cả những gì sinh viên sở hữu (tài sản) so với tất cả những gì họ nợ (nợ phải trả) tại một ngày cụ thể. Bằng cách thường xuyên lập ra \"bức tranh tổng quan\" khách quan này, sinh viên có thể đo lường chính xác mức độ tăng trưởng giá trị tài sản ròng của mình, đảm bảo các chiến lược tài chính dài hạn thực sự hiệu quả.","g":"new","tv":"Bảng cân đối kế toán có thể giúp sinh viên như thế nào trong tương lai?"},{"id":"SSA101_Q231","t":"How can 15 to 20 minutes of 'waiting time' be repurposed effectively?","o":[["A","By being organized enough to complete short tasks or review notes during that brief period.","Bằng cách đủ ngăn nắp để hoàn thành các nhiệm vụ ngắn hoặc xem lại ghi chú trong khoảng thời gian ngắn đó."],["B","By taking a quick nap to catch up on sleep.","Bằng cách chợp mắt nhanh để bù giấc ngủ."],["C","By scrolling social media to relax the brain.","Bằng cách lướt mạng xã hội để thư giãn đầu óc."],["D","By finishing an entire research paper.","Bằng cách hoàn thành cả một bài nghiên cứu."]],"a":"A","s":0,"e":"If a student actively anticipates these inevitable short delays and keeps portable study materials (like flashcards, a reading assignment, or a digital checklist) easily accessible, they can immediately pivot to productivity. Repurposing these brief, unused pockets of time to complete small, discrete tasks prevents the accumulation of overwhelming workloads at the end of the day.","ev":"Nếu sinh viên chủ động lường trước những khoảng thời gian trì hoãn ngắn không thể tránh khỏi này và luôn chuẩn bị sẵn các tài liệu học tập mang theo bên mình (như thẻ ghi nhớ, bài đọc hoặc danh sách kiểm tra kỹ thuật số), họ có thể ngay lập tức chuyển sang làm việc hiệu quả. Tận dụng những khoảng thời gian rảnh ngắn ngủi này để hoàn thành các nhiệm vụ nhỏ giúp tránh tích tụ khối lượng công việc quá tải vào cuối ngày.","g":"new","tv":"15 đến 20 phút 'thời gian chờ' có thể được tận dụng hiệu quả như thế nào?"},{"id":"SSA101_Q232","t":"How much can on-campus housing and meals add to the annual cost of college?","o":[["A","The exact cost is not stated, but the text recommends living at home (if possible) to save a significant amount of money.","Văn bản không nêu chi phí chính xác, nhưng khuyến nghị sống ở nhà (nếu có thể) để tiết kiệm một khoản đáng kể."],["B","It is always cheaper than living at home.","Nó luôn rẻ hơn sống ở nhà."],["C","An extra $50,000 per year.","Thêm 50.000 đô la mỗi năm."],["D","Universities do not charge for room and board.","Các trường đại học không thu phí chỗ ở và ăn uống."]],"a":"A","s":0,"e":"On-campus room and board represent one of the largest hidden expenses in higher education, often doubling the base cost of tuition alone. The text pragmatically recommends that students live at home if logistically possible, as this entirely eliminates exorbitant dormitory and meal plan fees, saving them tens of thousands of dollars over the course of their degree.","ev":"Chi phí ăn ở trong ký túc xá là một trong những khoản chi phí ẩn lớn nhất trong giáo dục đại học, thường gấp đôi chi phí học phí cơ bản. Văn bản này đưa ra lời khuyên thực tế rằng sinh viên nên sống ở nhà nếu điều kiện cho phép, vì điều này sẽ loại bỏ hoàn toàn các khoản phí ký túc xá và ăn uống đắt đỏ, giúp họ tiết kiệm hàng chục nghìn đô la trong suốt quá trình học.","g":"new","tv":"Chỗ ở và bữa ăn trong khuôn viên trường có thể làm tăng chi phí học đại học hằng năm bao nhiêu?"},{"id":"SSA101_Q233","t":"How do supporters of generative AI justify the use of copyrighted works in training data under the \"fair use doctrine\"?","o":[["A","They argue that AI algorithms completely destroy the original market value of the copyrighted works, forcing the creation of entirely new markets","Họ cho rằng thuật toán AI hoàn toàn phá hủy giá trị thị trường gốc của các tác phẩm có bản quyền, buộc phải tạo ra các thị trường hoàn toàn mới"],["B","They claim the use is \"non-consumptive\" because the tool learns syntax and context without reproducing the central elements of the original work","Họ cho rằng việc sử dụng là \"không tiêu thụ\" vì công cụ học cú pháp và ngữ cảnh mà không tái tạo các yếu tố trung tâm của tác phẩm gốc"],["C","They state that the original creators automatically forfeit their intellectual property rights once their works are uploaded to public internet servers","Họ nói rằng người sáng tạo gốc tự động mất quyền sở hữu trí tuệ khi tác phẩm của họ được tải lên máy chủ internet công khai"],["D","They emphasize that the developers are utilizing the copyrighted materials exclusively for non-profit, government-sponsored educational programs","Họ nhấn mạnh rằng các nhà phát triển chỉ dùng tài liệu có bản quyền cho các chương trình giáo dục phi lợi nhuận do chính phủ tài trợ"]],"a":"B","s":0,"e":"Technology companies heavily argue that scraping copyrighted works to train AI fundamentally qualifies as a \"fair use\" exception. They legally claim the process is strictly \"non-consumptive\"; the AI is not inherently copying the original data to directly pirate it, but rather mathematically analyzing thousands of texts to learn the abstract concepts of syntax, grammar, and contextual relationships.","ev":"Các công ty công nghệ lập luận mạnh mẽ rằng việc thu thập dữ liệu từ các tác phẩm có bản quyền để huấn luyện AI về cơ bản thuộc phạm vi ngoại lệ \"sử dụng hợp lý\" (fair use). Họ khẳng định quá trình này hoàn toàn mang tính \"không tiêu thụ\" (non-consumptive); AI không sao chép dữ liệu gốc để vi phạm bản quyền mà phân tích toán học hàng nghìn văn bản để học các khái niệm trừu tượng về cú pháp, ngữ pháp và quan hệ ngữ cảnh.","g":"new","tv":"Những người ủng hộ AI tạo sinh biện minh cho việc dùng các tác phẩm có bản quyền trong dữ liệu huấn luyện theo \"học thuyết sử dụng hợp lý\" (fair use) như thế nào?"},{"id":"SSA101_Q234","t":"How can a student most effectively utilize a grading rubric to improve their assignment before submitting the final version to their online instructor?","o":[["A","The student should completely ignore the rubric until after receiving the final grade, using it only to argue for additional points if the instructor made a mistake","Sinh viên nên hoàn toàn phớt lờ thang chấm cho đến sau khi nhận điểm cuối, chỉ dùng nó để tranh luận xin thêm điểm nếu giảng viên sai sót"],["B","The student should put themselves in the place of the instructor and grade their own drafted assignment according to the rubric criteria to identify missing elements","Sinh viên nên đặt mình vào vị trí giảng viên và tự chấm bài nháp theo tiêu chí của thang chấm để xác định các phần còn thiếu"],["C","The student should copy the exact phrasing found within the highest scoring column of the rubric and paste it directly into their assignment to guarantee top marks","Sinh viên nên sao chép nguyên văn cách diễn đạt trong cột điểm cao nhất của thang chấm và dán trực tiếp vào bài để đảm bảo điểm tối đa"],["D","The student should only read the rubric after finishing the entire writing process to avoid feeling overwhelmed or restricted by the instructor's specific guidelines","Sinh viên chỉ nên đọc thang chấm sau khi hoàn thành toàn bộ quá trình viết để tránh cảm thấy quá tải hoặc bị gò bó bởi hướng dẫn cụ thể của giảng viên"]],"a":"B","s":0,"e":"A grading rubric is essentially a detailed, highly transparent blueprint of exactly what the instructor expects to see in a flawless, top-tier assignment. By proactively adopting the precise perspective of the grader and rigorously evaluating your own rough draft against each specific rubric criterion before submission, you can systematically identify critical missing elements. This objective self-assessment allows you to confidently revise your work and maximize your final score before the teacher ever sees it.","ev":"Bảng tiêu chí chấm điểm (rubric) về cơ bản là một bản thiết kế chi tiết và minh bạch về những gì giảng viên kỳ vọng ở một bài tập xuất sắc. Bằng cách chủ động đặt mình vào vị trí người chấm và tự đánh giá bản nháp của mình theo từng tiêu chí cụ thể trước khi nộp, bạn có thể phát hiện có hệ thống những yếu tố còn thiếu, tự tin chỉnh sửa và tối đa hóa điểm số cuối cùng.","g":"new","tv":"Sinh viên có thể tận dụng hiệu quả nhất thang chấm (rubric) như thế nào để cải thiện bài tập trước khi nộp bản cuối cho giảng viên trực tuyến?"},{"id":"SSA101_Q235","t":"Why is 'Evaluating' a necessary step in the financial planning process?","o":[["A","To judge other people's spending habits.","Để đánh giá thói quen chi tiêu của người khác."],["B","To assess your current financial situation (e.g., income, expenses) before making a plan.","Để đánh giá tình hình tài chính hiện tại của bạn (ví dụ thu nhập, chi tiêu) trước khi lập kế hoạch."],["C","To calculate bank interest rates.","Để tính lãi suất ngân hàng."],["D","To decide which bank to choose.","Để quyết định chọn ngân hàng nào."]],"a":"B","s":0,"tv":"Tại sao 'Evaluating' a necessary step in the financial planning process?","e":"You absolutely cannot chart a reliable course to a future financial goal if you do not know your precise starting point. The evaluation step requires a brutally honest audit of your current cash flow, existing debts, and monthly expenses, establishing the necessary factual baseline required to safely build a realistic, mathematically sound financial plan.","ev":"Bạn hoàn toàn không thể vạch ra một lộ trình đáng tin cậy để đạt được mục tiêu tài chính trong tương lai nếu không biết chính xác điểm xuất phát của mình. Bước đánh giá đòi hỏi một cuộc kiểm toán trung thực tuyệt đối về dòng tiền hiện tại, các khoản nợ hiện có và chi phí hàng tháng của bạn, thiết lập cơ sở thực tế cần thiết để xây dựng một kế hoạch tài chính thực tế và vững chắc.","g":"new"},{"id":"SSA101_Q236","t":"Why is it important to research 'job market trends' for a chosen major?","o":[["A","To find the easiest jobs to do.","Để tìm những công việc dễ làm nhất."],["B","To ensure you are preparing for a growing and promising field, rather than a declining one.","Để đảm bảo bạn đang chuẩn bị cho một lĩnh vực đang phát triển và đầy triển vọng, thay vì một lĩnh vực đang suy giảm."],["C","To know what clothes to wear to work.","Để biết mặc quần áo gì đi làm."],["D","To guarantee a six-figure starting salary.","Để đảm bảo mức lương khởi điểm sáu con số."]],"a":"B","s":0,"tv":"Tại sao it important to research 'job market trends' for a chosen major?","e":"An academic major is a massive investment of time and capital, so it must yield a viable return. Researching long-term job market trends ensures that the specific field you are intensely training for is actually experiencing sustained demand and economic growth, protecting you from graduating into a declining industry with zero realistic employment prospects.","ev":"Việc theo học một chuyên ngành học thuật đòi hỏi đầu tư rất lớn về thời gian và vốn, vì vậy nó phải mang lại lợi ích thiết thực. Nghiên cứu xu hướng thị trường việc làm dài hạn đảm bảo rằng lĩnh vực cụ thể mà bạn đang theo đuổi thực sự có nhu cầu ổn định và tăng trưởng kinh tế, giúp bạn tránh khỏi việc tốt nghiệp vào một ngành đang suy thoái với triển vọng việc làm bằng không.","g":"new"},{"id":"SSA101_Q237","t":"Why is it easy to forget why you set a long-term goal?","o":[["A","Because short-term memory erases long-term goals.","Vì trí nhớ ngắn hạn xóa mục tiêu dài hạn."],["B","Because it is easy to become mired in the drudgery of current difficult tasks and forget the initial reason.","Vì dễ bị sa lầy trong sự nhàm chán của các nhiệm vụ khó hiện tại và quên lý do ban đầu."],["C","Because long-term goals are usually not SMART goals.","Vì mục tiêu dài hạn thường không phải là mục tiêu SMART."],["D","Because friends and family often distract you.","Vì bạn bè và gia đình thường làm bạn xao nhãng."]],"a":"B","s":0,"tv":"Tại sao it easy to forget why you set a long-term goal?","e":"Long-term goals, by definition, require months or years of sustained effort, often involving highly repetitive or frustrating daily tasks. As a student becomes exhausted by immediate deadlines, stressful exams, and heavy reading loads, this relentless daily friction can easily obscure the overarching, inspirational \"big picture\" that initially motivated them to start their journey.","ev":"Theo định nghĩa, mục tiêu dài hạn đòi hỏi nhiều tháng hoặc nhiều năm nỗ lực bền bỉ, thường bao gồm các công việc hàng ngày lặp đi lặp lại hoặc gây nản lòng. Khi sinh viên kiệt sức vì những hạn chót sát nút, các kỳ thi căng thẳng và khối lượng bài đọc nặng nề, sự ma sát hàng ngày không ngừng nghỉ này có thể dễ dàng che khuất \"bức tranh lớn\" đầy cảm hứng ban đầu.","g":"new"},{"id":"SSA101_Q238","t":"Why is 'pulling an all-nighter' considered a poor planning method?","o":[["A","It ensures you have too much energy the next day","Nó đảm bảo bạn có quá nhiều năng lượng vào ngày hôm sau"],["B","It is the best way to utilize long-term memory","Đó là cách tốt nhất để tận dụng trí nhớ dài hạn"],["C","It rarely produces the best work and is often a last-minute attempt to make up for poor planning","Nó hiếm khi tạo ra sản phẩm tốt nhất và thường là nỗ lực phút chót để bù đắp cho việc lập kế hoạch kém"],["D","It allows you to finish assignments early so you can socialize","Nó cho phép bạn hoàn thành bài tập sớm để có thể giao lưu"]],"a":"C","s":0,"tv":"Tại sao 'pulling an all-nighter' considered a poor planning method?","e":"An \"all-nighter\" is a universally recognized poor planning method because severe sleep deprivation drastically impairs critical cognitive functions, including memory retention, focus, and logical problem-solving. As a result, any academic work produced under these exhausting conditions is typically rushed, highly error-prone, and acts as an ineffective last-minute fix for poor time management.","ev":"Việc thức trắng đêm được công nhận rộng rãi là một phương pháp lập kế hoạch kém hiệu quả vì thiếu ngủ trầm trọng làm suy giảm đáng kể các chức năng nhận thức quan trọng, bao gồm ghi nhớ, tập trung và giải quyết vấn đề logic. Do đó, bất kỳ bài tập học thuật nào được tạo ra trong điều kiện kiệt sức này thường vội vàng, dễ mắc lỗi và chỉ là giải pháp chắp vá vào phút chót cho việc quản lý thời gian kém.","g":"new"},{"id":"SSA101_Q239","t":"Why is 'Visualizing the Results' considered an effective motivation strategy?","o":[["A","It helps you fall asleep faster after studying","Nó giúp bạn ngủ nhanh hơn sau khi học"],["B","Keeping the benefits and end results in mind is extremely effective in keeping you motivated","Việc luôn nghĩ đến lợi ích và kết quả cuối cùng cực kỳ hiệu quả trong việc giữ động lực"],["C","It allows you to skip the planning phase of goal setting","Nó cho phép bạn bỏ qua giai đoạn lập kế hoạch khi đặt mục tiêu"],["D","It guarantees you will get an A in the class","Nó đảm bảo bạn sẽ đạt điểm A trong lớp"]],"a":"B","s":0,"tv":"Tại sao 'Visualizing the Results' considered an effective motivation strategy?","e":"\"Visualizing the Results\" is an incredibly powerful motivational technique because it directly links your current, often tedious work to a highly desirable future outcome. By vividly keeping the ultimate benefits—such as a degree or a dream career—at the forefront of your mind, you generate strong intrinsic motivation that helps you push through difficult periods and avoid burnout.","ev":"\"Hình dung kết quả\" là một kỹ thuật tạo động lực vô cùng mạnh mẽ bởi vì nó liên kết trực tiếp công việc hiện tại thường tẻ nhạt của bạn với một kết quả tương lai đáng mơ ước. Bằng cách luôn ghi nhớ sống động những lợi ích cuối cùng—như tấm bằng đại học hay sự nghiệp mơ ước—bạn tạo ra động lực nội tại mạnh mẽ giúp vượt qua giai đoạn khó khăn và tránh kiệt sức.","g":"new"},{"id":"SSA101_Q240","t":"Why is 'Learning About Yourself' considered a lifelong process in career planning?","o":[["A","Because career tests are unreliable","Vì các bài kiểm tra nghề nghiệp không đáng tin cậy"],["B","Because knowing yourself as a professional by discovering interests, skills, and values is something everyone should do on an ongoing basis","Vì việc hiểu bản thân với tư cách một người làm nghề bằng cách khám phá sở thích, kỹ năng và giá trị là điều mọi người nên làm liên tục"],["C","Because employers require you to retake personality tests every year","Vì nhà tuyển dụng yêu cầu bạn làm lại bài kiểm tra tính cách mỗi năm"],["D","Because it is required to maintain professional licensure","Vì nó bắt buộc để duy trì giấy phép hành nghề"]],"a":"B","s":0,"tv":"Tại sao 'Learning About Yourself' considered a lifelong process in career planning?","e":"\"Learning About Yourself\" is universally considered a lifelong process because human beings are highly dynamic. As you age and gain complex real-world experience, your core interests, professional skills, and personal values will inevitably shift. Regular self-reflection ensures that your long-term career choices continue to perfectly align with your current life stage.","ev":"\"Hiểu rõ bản thân\" được coi là một quá trình suốt đời bởi vì con người rất năng động. Khi bạn trưởng thành và tích lũy được nhiều kinh nghiệm thực tế phức tạp, sở thích cốt lõi, kỹ năng chuyên môn và giá trị cá nhân của bạn chắc chắn sẽ thay đổi. Việc thường xuyên tự nhìn nhận bản thân đảm bảo rằng những lựa chọn nghề nghiệp dài hạn của bạn tiếp tục phù hợp với giai đoạn cuộc sống hiện tại.","g":"new"},{"id":"SSA101_Q241","t":"Why is 'Information Literacy' essential for modern careers?","o":[["A","It allows you to read faster than everyone else.","Nó cho phép bạn đọc nhanh hơn mọi người."],["B","It is only required for IT workers.","Nó chỉ cần thiết cho nhân viên CNTT."],["C","Workers are expected to be proficient, ethical users and producers of information to solve problems in a connected world.","Người lao động được kỳ vọng là người dùng và người tạo ra thông tin thành thạo, có đạo đức để giải quyết vấn đề trong một thế giới kết nối."],["D","It helps you avoid using the internet.","Nó giúp bạn tránh dùng internet."]],"a":"C","s":0,"tv":"Tại sao 'năng lực thông tin' essential for modern careers?","e":"In today's highly digitized knowledge economy, professionals are constantly bombarded with immense volumes of data. Employers absolutely demand workers who can not only quickly locate credible information but also ethically synthesize it, avoid intellectual property violations, and utilize that accurate data to safely and effectively solve complex organizational problems.","ev":"Trong nền kinh tế tri thức số hóa hiện nay, các chuyên gia liên tục phải đối mặt với khối lượng dữ liệu khổng lồ. Nhà tuyển dụng yêu cầu những người lao động không chỉ có thể nhanh chóng tìm thấy thông tin đáng tin cậy mà còn phải tổng hợp nó một cách có đạo đức, tránh vi phạm sở hữu trí tuệ và sử dụng dữ liệu chính xác để giải quyết các vấn đề phức tạp của tổ chức.","g":"new"},{"id":"SSA101_Q242","t":"Why is it important to bring the book and reading notes to every class session?","o":[["A","To prove to the instructor that you bought the book.","Để chứng minh với giảng viên rằng bạn đã mua sách."],["B","To avoid having to listen to the lecture.","Để khỏi phải nghe bài giảng."],["C","To engage with the material, avoid distractions, and ask critical or clarifying questions.","Để tương tác với tài liệu, tránh xao nhãng và đặt các câu hỏi phản biện hoặc làm rõ."],["D","To read ahead for next week's class.","Để đọc trước cho lớp tuần sau."]],"a":"C","s":0,"tv":"Tại sao it important to bring the book and reading notes to every class session?","e":"Bringing your annotated textbook and pre-class notes directly into the lecture hall tightly bridges the gap between independent study and active classroom learning. Having these physical resources readily available allows you to immediately reference confusing sections, verify facts as the professor speaks, stay heavily focused on the material, and formulate much deeper, context-rich questions.","ev":"Việc mang sách giáo khoa đã ghi chú và ghi chép trước giờ học trực tiếp vào giảng đường sẽ giúp thu hẹp khoảng cách giữa việc tự học và học tập tích cực trên lớp. Việc có sẵn các tài liệu này cho phép bạn tra cứu ngay các phần khó hiểu, kiểm chứng thông tin khi giảng viên nói, duy trì sự tập trung và đặt ra những câu hỏi sâu sắc hơn.","g":"new"},{"id":"SSA101_Q243","t":"Why is volunteering recommended during the 'Exploring Options' phase of career planning?","o":[["A","Because it pays a very high salary.","Vì nó trả lương rất cao."],["B","Because it is required for graduation.","Vì nó bắt buộc để tốt nghiệp."],["C","Because it allows you to gain additional skills and real-world experience outside the classroom.","Vì nó cho phép bạn có thêm kỹ năng và kinh nghiệm thực tế ngoài lớp học."],["D","Because it completely replaces the need for a college degree.","Vì nó hoàn toàn thay thế nhu cầu có bằng đại học."]],"a":"C","s":0,"tv":"Tại sao volunteering recommended during the 'Exploring Options' phase of career planning?","e":"During the career exploration phase, students are still trying to determine their ideal professional fit. Volunteering provides a low-risk, hands-on opportunity to engage directly with an industry, allowing students to gain highly relevant real-world experience, develop practical new skills, and build professional networks outside the confines of a traditional academic classroom.","ev":"Trong giai đoạn tìm hiểu nghề nghiệp, sinh viên vẫn đang cố gắng xác định lĩnh vực chuyên môn phù hợp nhất với mình. Hoạt động tình nguyện mang đến cơ hội thực tiễn ít rủi ro để tương tác trực tiếp với một ngành nghề, giúp sinh viên tích lũy kinh nghiệm thực tế phù hợp, phát triển kỹ năng mới thiết thực và xây dựng mạng lưới quan hệ ngoài lớp học.","g":"new"},{"id":"SSA101_Q244","t":"Why should a student avoid taking 'short cuts' in the reading and note-taking cycle?","o":[["A","Because instructors will check your notebooks for a grade.","Vì giảng viên sẽ kiểm tra vở ghi của bạn để chấm điểm."],["B","Because each step is a building block in the continuous learning process, helping you become a stronger expert.","Vì mỗi bước là một viên gạch trong quá trình học liên tục, giúp bạn trở thành chuyên gia vững vàng hơn."],["C","Because taking shortcuts leads directly to academic suspension.","Vì đi tắt dẫn thẳng đến đình chỉ học."],["D","Because reading is the only way to pass the course.","Vì đọc là cách duy nhất để qua môn."]],"a":"B","s":0,"e":"Effective learning is not a simple transaction; it is a cumulative, structured cognitive process where surveying, reading, annotating, and reviewing interlock to build deep comprehension. Attempting to bypass these foundational steps—such as skimming without taking active notes—creates severe structural gaps in your knowledge base, ultimately guaranteeing poor performance when complex analysis is required on exams.","ev":"Học tập hiệu quả không phải là một giao dịch đơn giản; đó là một quá trình nhận thức tích lũy có cấu trúc, trong đó việc khảo sát, đọc, ghi chú và xem xét đan xen nhau để xây dựng sự hiểu biết sâu sắc. Việc cố gắng bỏ qua các bước nền tảng này—chẳng hạn như đọc lướt mà không ghi chú chủ động—sẽ tạo ra những lỗ hổng nghiêm trọng trong kiến thức nền tảng và dẫn đến kết quả kém khi thi.","g":"new","tv":"Tại sao sinh viên nên tránh 'đi tắt' trong chu trình đọc và ghi chép?"},{"id":"SSA101_Q245","t":"When creating a highly effective daily task list, which of the following practices is recommended for managing large and complex academic projects?","o":[["A","You should schedule the entire project to be completed in one extended work period to ensure that your train of thought remains entirely uninterrupted","Bạn nên lên lịch hoàn thành toàn bộ dự án trong một khoảng thời gian làm việc kéo dài để mạch suy nghĩ hoàn toàn không bị gián đoạn"],["B","You should break the large project down into smaller, specific, and measurable tasks that can each be comfortably completed within a single hour or less","Bạn nên chia dự án lớn thành các nhiệm vụ nhỏ hơn, cụ thể và đo lường được, mỗi nhiệm vụ có thể hoàn thành thoải mái trong một giờ hoặc ít hơn"],["C","You should prioritize the project only after all of your minor, less urgent tasks have been completed to clear your mind of any daily distractions","Bạn chỉ nên ưu tiên dự án sau khi hoàn thành mọi nhiệm vụ nhỏ, ít cấp bách hơn để dọn đầu óc khỏi mọi xao nhãng hằng ngày"],["D","You should leave the project off your daily task list entirely and instead rely strictly on the master semester schedule to track its eventual completion","Bạn nên loại hẳn dự án khỏi danh sách việc cần làm hằng ngày và chỉ dựa vào lịch tổng của học kỳ để theo dõi việc hoàn thành"]],"a":"B","s":0,"e":"Confronting a massive academic project all at once can quickly lead to feelings of overwhelm, cognitive fatigue, and severe procrastination. By strategically breaking the larger project down into several smaller, highly specific, and measurable tasks that can be comfortably completed in an hour or less, you create a clear, actionable roadmap. This approach ensures steady, consistent daily progress while providing immediate psychological rewards as each individual step is checked off your list.","ev":"Đối mặt với một dự án học thuật khổng lồ cùng một lúc có thể nhanh chóng dẫn đến cảm giác choáng ngợp, mệt mỏi về nhận thức và trì hoãn nghiêm trọng. Bằng cách chia nhỏ dự án lớn thành nhiều nhiệm vụ nhỏ hơn, cụ thể và có thể đo lường được trong vòng một giờ trở xuống, bạn tạo ra một lộ trình rõ ràng, giúp duy trì tiến độ hàng ngày ổn định và mang lại cảm giác thành tựu khi hoàn thành từng bước.","g":"new","tv":"Khi tạo danh sách việc cần làm hằng ngày hiệu quả, thực hành nào sau đây được khuyến nghị để quản lý các dự án học tập lớn và phức tạp?"},{"id":"SSA101_Q246","t":"When approaching a scholarly journal article for a research project, what is the recommended first step to determine if the article is relevant to your work?","o":[["A","You should immediately read the discussion section in its entirety, as this section contains the most detailed and comprehensive explanation of the research findings","Bạn nên đọc ngay toàn bộ phần thảo luận vì phần này chứa lời giải thích chi tiết và đầy đủ nhất về kết quả nghiên cứu"],["B","You should carefully review the literature review section to gather historical background information and find older reference materials related to your specific topic","Bạn nên xem kỹ phần tổng quan tài liệu để thu thập thông tin bối cảnh lịch sử và tìm các tài liệu tham khảo cũ liên quan đến chủ đề cụ thể của bạn"],["C","You should begin by reading the abstract and the provided keywords to quickly decide if the subject matter directly aligns with your current research project's goals","Bạn nên bắt đầu bằng việc đọc phần tóm tắt và từ khóa để nhanh chóng quyết định xem chủ đề có phù hợp trực tiếp với mục tiêu dự án nghiên cứu hiện tại của bạn không"],["D","You should focus primarily on the methodology section to understand exactly how the researchers gathered their data and determine if their statistical analysis is flawed","Bạn nên tập trung chủ yếu vào phần phương pháp để hiểu chính xác cách các nhà nghiên cứu thu thập dữ liệu và xác định phân tích thống kê của họ có sai sót không"]],"a":"C","s":0,"e":"Scholarly journal articles are exceptionally dense, highly technical documents that can take hours to fully comprehend line-by-line. Because the academic research phase requires rapidly filtering through dozens of potential sources, immediately reading the strictly localized abstract and keywords provides a fast, highly concentrated summary of the entire study. This allows you to instantly determine if the authors' specific subject matter practically aligns with your own research goals before unnecessarily investing hours into reading their complex methodology.","ev":"Các bài báo khoa học trên tạp chí chuyên ngành là những tài liệu cực kỳ cô đọng và mang tính kỹ thuật cao, có thể mất nhiều giờ để đọc hiểu từng dòng. Vì giai đoạn nghiên cứu đòi hỏi phải lọc nhanh hàng chục nguồn tài liệu tiềm năng, việc đọc ngay phần tóm tắt (abstract) và từ khóa (keywords) sẽ cung cấp bản tóm tắt nhanh chóng, giúp bạn xác định ngay bài báo có phù hợp với mục tiêu nghiên cứu của mình hay không.","g":"new","tv":"Khi tiếp cận một bài báo tạp chí học thuật cho dự án nghiên cứu, bước đầu tiên được khuyến nghị để xác định bài có liên quan đến công việc của bạn không là gì?"},{"id":"SSA101_Q247","t":"When sending an email to an online instructor, which of the following practices is recommended to ensure the communication is professional and effective?","o":[["A","You should include an informative subject line, use a formal professional greeting, and break your message into multiple paragraphs to ensure optimal readability","Bạn nên có dòng tiêu đề thông tin rõ ràng, dùng lời chào trang trọng chuyên nghiệp và chia thư thành nhiều đoạn để dễ đọc nhất"],["B","You should keep the message as short as humanly possible, omitting any greetings or sign-offs, to ensure you do not waste the instructor's highly valuable time","Bạn nên viết thư ngắn nhất có thể, bỏ lời chào và lời kết, để không lãng phí thời gian quý báu của giảng viên"],["C","You should expect a response within a few hours and send an immediate follow-up email on the exact same day if you have not yet received the requested information","Bạn nên mong đợi phản hồi trong vài giờ và gửi ngay email nhắc lại trong cùng ngày nếu chưa nhận được thông tin yêu cầu"],["D","You should write in a casual and conversational tone, using abbreviations and slang, to quickly build a friendly, relaxed, and approachable relationship with them","Bạn nên viết giọng thân mật, trò chuyện, dùng chữ viết tắt và tiếng lóng để nhanh chóng xây dựng mối quan hệ thân thiện, thoải mái và dễ gần với họ"]],"a":"A","s":0,"e":"Because online instructors manage hundreds of digital communications daily, adhering to strict professional email etiquette is absolutely essential for receiving timely and helpful responses. Including a highly specific subject line ensures your email is prioritized and routed correctly, while utilizing a formal greeting and structuring your request into clear, readable paragraphs demonstrates deep respect for the instructor's time and professional boundaries, fostering a highly positive academic relationship.","ev":"Vì giảng viên trực tuyến phải xử lý hàng trăm thư điện tử mỗi ngày, việc tuân thủ nghiêm ngặt các quy tắc ứng xử email chuyên nghiệp là vô cùng cần thiết để nhận được phản hồi kịp thời và hữu ích. Việc đặt tiêu đề email cụ thể, sử dụng lời chào trang trọng và chia nội dung thành các đoạn văn rõ ràng thể hiện sự tôn trọng thời gian của giảng viên và xây dựng mối quan hệ học thuật tích cực.","g":"new","tv":"Khi gửi email cho giảng viên trực tuyến, thực hành nào sau đây được khuyến nghị để đảm bảo giao tiếp chuyên nghiệp và hiệu quả?"},{"id":"SSA101_Q248","t":"How does 'Analytical Thinking' differ from 'Creative Thinking'?","o":[["A","Analytical thinking is only for math; creative thinking is only for art","Tư duy phân tích chỉ dành cho toán; tư duy sáng tạo chỉ dành cho nghệ thuật"],["B","Analytical thinking involves systematically breaking a problem into component parts for analysis, while creative thinking involves generating original and unconventional ideas","Tư duy phân tích là chia một vấn đề thành các thành phần một cách có hệ thống để phân tích, còn tư duy sáng tạo là tạo ra những ý tưởng độc đáo và khác thường"],["C","Analytical thinking is optional; creative thinking is mandatory","Tư duy phân tích là tùy chọn; tư duy sáng tạo là bắt buộc"],["D","Analytical thinking creates clutter; creative thinking organizes it","Tư duy phân tích tạo ra sự lộn xộn; tư duy sáng tạo sắp xếp nó"]],"a":"B","s":0,"tv":"How does 'tư duy phân tích' differ from 'tư duy sáng tạo'?","e":"Analytical thinking is a logical, convergent process where you systematically deconstruct complex information into smaller, manageable parts to understand how they function together and identify errors. In contrast, creative thinking is a divergent process that encourages looking fully outside existing frameworks to brainstorm unconventional ideas and synthesize completely original solutions that did not previously exist.","ev":"Tư duy phân tích là một quá trình logic, hội tụ, trong đó bạn phân tích một cách có hệ thống thông tin phức tạp thành các phần nhỏ hơn để hiểu cách chúng hoạt động cùng nhau và phát hiện lỗi. Ngược lại, tư duy sáng tạo là một quá trình phân kỳ khuyến khích việc suy nghĩ vượt ra ngoài khuôn khổ hiện có để đề xuất những ý tưởng độc đáo và tổng hợp các giải pháp hoàn toàn mới.","g":"new"},{"id":"SSA101_Q249","t":"According to the text, what is the link between financial health and personal life?","o":[["A","Financial health only determines what car you drive.","Sức khỏe tài chính chỉ quyết định bạn lái xe gì."],["B","Studies show that people with stronger finances are healthier, happier, have better marriages, and better cognitive functioning.","Các nghiên cứu cho thấy người có tài chính vững hơn thì khỏe mạnh hơn, hạnh phúc hơn, hôn nhân tốt hơn và chức năng nhận thức tốt hơn."],["C","There is no connection at all.","Hoàn toàn không có mối liên hệ nào."],["D","Having strong finances guarantees you will never be stressed.","Có tài chính vững mạnh đảm bảo bạn sẽ không bao giờ căng thẳng."]],"a":"B","s":0,"tv":"Theo the text, what is the link between financial health and personal life","e":"Financial instability is universally recognized as one of the leading causes of chronic, systemic stress in adults. Extensive sociological studies confirm that individuals who maintain strong financial health experience dramatically lower stress levels, leading directly to reduced anxiety, better cognitive functioning, healthier physical bodies, and significantly more stable marriages.","ev":"Tình trạng bất ổn tài chính được công nhận rộng rãi là một trong những nguyên nhân hàng đầu gây ra căng thẳng mãn tính, mang tính hệ thống ở người trưởng thành. Nhiều nghiên cứu xã hội học sâu rộng xác nhận rằng những người duy trì sức khỏe tài chính tốt có mức độ căng thẳng thấp hơn đáng kể, dẫn đến giảm lo âu, chức năng nhận thức tốt hơn, cơ thể khỏe mạnh hơn và hôn nhân ổn định hơn.","g":"new"},{"id":"SSA101_Q250","t":"According to the foundational definitions of AI literacy, how do \"Neural Networks\" primarily function within deep learning systems?","o":[["A","They explicitly program computers to perform a singular task by utilizing rigid rules and completely eliminating the need for ongoing inference.","Chúng lập trình rõ ràng cho máy tính thực hiện một nhiệm vụ duy nhất bằng các quy tắc cứng nhắc và loại bỏ hoàn toàn nhu cầu suy luận liên tục."],["B","They consist of interconnected nodes organized in layers that process inputs through activation functions to recognize complex patterns","Chúng gồm các nút kết nối với nhau được tổ chức thành các lớp, xử lý đầu vào qua các hàm kích hoạt để nhận ra các mẫu phức tạp"],["C","They focus exclusively on the direct interaction between advanced computer systems and human language through semantic analysis","Chúng tập trung hoàn toàn vào sự tương tác trực tiếp giữa các hệ thống máy tính tiên tiến và ngôn ngữ con người thông qua phân tích ngữ nghĩa"],["D","They generate novel content such as text, imagery, and audio by searching the internet for real-time data and synthesizing it instantly","Chúng tạo ra nội dung mới như văn bản, hình ảnh và âm thanh bằng cách tìm dữ liệu thời gian thực trên internet và tổng hợp ngay lập tức"]],"a":"B","s":0,"tv":"Theo the foundational definitions of năng lực AI, how do \"Neural Networks\" primarily function within deep learning systems","e":"Neural networks are architecturally inspired by the human brain; they absolutely do not rely on rigid, explicit programming. Instead, they consist of thousands of interconnected artificial \"nodes\" stacked in deep, hierarchical layers that process massive datasets through mathematical activation functions, allowing the system to independently recognize complex visual, audio, or textual patterns.","ev":"Mạng nơ-ron được lấy cảm hứng từ cấu trúc não người; chúng hoàn toàn không dựa vào lập trình cứng nhắc, tường minh. Thay vào đó, chúng bao gồm hàng nghìn \"nút\" nhân tạo được kết nối với nhau thành các lớp phân tầng sâu, xử lý tập dữ liệu lớn thông qua các hàm kích hoạt toán học, cho phép hệ thống tự động nhận diện các mẫu hình ảnh, âm thanh hoặc văn bản phức tạp.","g":"new"},{"id":"SSA101_Q251","t":"According to the Ebbinghaus Forgetting Curve research, what is the most effective method for successfully storing information in long-term memory?","o":[["A","Passively re-reading notes and highlighting textbooks continuously for several hours immediately preceding the scheduled academic examination","Đọc lại ghi chú một cách thụ động và đánh dấu sách giáo khoa liên tục trong nhiều giờ ngay trước kỳ thi đã lên lịch"],["B","Utilizing artificial intelligence chatbots to write detailed essays so the student can focus their mental energy entirely on other difficult subjects","Dùng chatbot AI viết các bài luận chi tiết để sinh viên dồn toàn bộ năng lượng tinh thần vào các môn khó khác"],["C","Actively recalling the information at strategically spaced intervals just before the brain would otherwise naturally forget the educational material","Chủ động nhớ lại thông tin ở những khoảng cách có chiến lược ngay trước khi não tự nhiên quên tài liệu học"],["D","Relying exclusively on intrinsic motivation and high attainment value to organically ensure the brain permanently encodes the new information","Chỉ dựa vào động lực nội tại và giá trị thành tựu cao để tự nhiên đảm bảo não mã hóa vĩnh viễn thông tin mới"]],"a":"C","s":0,"tv":"Theo the Ebbinghaus Forgetting Curve research, what is the most effective method for successfully storing information in trí nhớ dài hạn","e":"The Ebbinghaus Forgetting Curve proves that the human brain naturally discards new information exponentially fast if it is not actively reinforced. The scientifically proven method to effectively combat this is \"spaced repetition\"—the practice of deliberately forcing your brain to actively recall the material at increasingly longer intervals, which permanently encodes the data into long-term memory.","ev":"Đường cong quên lãng Ebbinghaus chứng minh rằng bộ não con người tự nhiên loại bỏ thông tin mới với tốc độ cấp số nhân nếu nó không được củng cố một cách chủ động. Phương pháp khoa học được chứng minh để chống lại điều này là \"lặp lại ngắt quãng\" (spaced repetition)—thực hành chủ động buộc não bộ nhớ lại tài liệu theo những khoảng thời gian dài dần, giúp mã hóa vĩnh viễn dữ liệu vào trí nhớ dài hạn.","g":"new"},{"id":"SSA101_Q252","t":"According to the guidelines for giving positive feedback to a team member, which of the following approaches is the most appropriate and effective?","o":[["A","You should completely avoid asking for permission before delivering the feedback, because waiting might cause the individual to forget the specific negative event","Bạn nên hoàn toàn không xin phép trước khi đưa phản hồi, vì chờ đợi có thể khiến người đó quên sự việc tiêu cực cụ thể"],["B","You should compare the team member's performance directly to other highly successful students in the group so they have a clear and measurable standard to aim for","Bạn nên so sánh trực tiếp thành tích của thành viên nhóm với những sinh viên thành công khác trong nhóm để họ có chuẩn mực rõ ràng, đo lường được để hướng tới"],["C","You should begin and end the discussion by highlighting what is working well, focus on specific behaviors that can be changed, and avoid using absolutes like \"never.\"","Bạn nên bắt đầu và kết thúc cuộc trao đổi bằng việc nêu điểm đang làm tốt, tập trung vào các hành vi cụ thể có thể thay đổi và tránh dùng từ tuyệt đối như \"không bao giờ\"."],["D","You should point out everything that went wrong all at once, using generalized statements about their overall attitude to ensure they understand the severe impact","Bạn nên chỉ ra mọi điều sai sót cùng một lúc, dùng những nhận định chung chung về thái độ của họ để đảm bảo họ hiểu tác động nghiêm trọng"]],"a":"C","s":0,"tv":"Theo the guidelines for giving positive feedback to a team member, which of the following approaches is the most appropriate and effective","e":"Delivering critical feedback within a collaborative group setting requires immense emotional intelligence to ensure the message is ultimately constructive rather than destructive. By actively \"sandwiching\" the needed corrective behavior between genuine highlights of what the teammate is currently doing well, you significantly lower their natural defensive barriers. Furthermore, explicitly avoiding harsh absolutes like \"always\" or \"never\" ensures the feedback remains entirely focused on actionable improvement rather than feeling like a personal attack.","ev":"Việc đưa ra phản hồi mang tính xây dựng trong môi trường làm việc nhóm đòi hỏi trí tuệ cảm xúc lớn để đảm bảo thông điệp mang tính xây dựng chứ không phải phá hoại. Bằng cách kết hợp góp ý cần cải thiện vào giữa những điểm tích cực mà đồng đội đang làm tốt và tránh các từ tuyệt đối như \"luôn luôn\" hay \"không bao giờ\", bạn giảm bớt rào cản phòng thủ và giúp phản hồi tập trung vào việc cải thiện hành vi cụ thể.","g":"new"},{"id":"SSA101_Q253","t":"According to Bloom's Taxonomy, which of the following activities best demonstrates a student operating at the \"Analyze\" level of the cognitive domain?","o":[["A","The student interprets the meaning of new information by translating it entirely into their own words and linking it to their personal background knowledge","Sinh viên diễn giải ý nghĩa thông tin mới bằng cách chuyển hoàn toàn sang lời của mình và liên kết với kiến thức nền cá nhân"],["B","The student takes information apart to explore relationships, continuously asks \"why,\" and examines how various independent components interact to form a complete system","Sinh viên tách thông tin ra để khám phá các mối quan hệ, liên tục hỏi \"tại sao\" và xem xét cách các thành phần độc lập tương tác để tạo thành một hệ thống hoàn chỉnh"],["C","The student uses the knowledge they have previously acquired to perform required tasks and resolve similar problems within a completely new practical situation","Sinh viên dùng kiến thức đã có để thực hiện các nhiệm vụ yêu cầu và giải quyết các vấn đề tương tự trong một tình huống thực tế hoàn toàn mới"],["D","The student integrates various pieces of familiar information together to generate a completely new product, perspective, or theoretical framework from the available data","Sinh viên tích hợp nhiều mẩu thông tin quen thuộc để tạo ra một sản phẩm, góc nhìn hoặc khung lý thuyết hoàn toàn mới từ dữ liệu có sẵn"]],"a":"B","s":0,"tv":"Theo Bloom's Taxonomy, which of the following activities best demonstrates a student operating at the \"Analyze\" level of the cognitive domain","e":"Reaching the \"Analyze\" cognitive level requires moving significantly beyond mere comprehension or basic application. At this advanced tier, the student systematically breaks down complex information into its fundamental underlying components, constantly questions the \"why,\" and critically examines exactly how those distinct individual parts logically interact to construct the broader organizational system.","ev":"Để đạt được trình độ nhận thức \"Phân tích\" cần phải vượt qua sự hiểu biết đơn thuần hoặc ứng dụng cơ bản. Ở cấp độ nâng cao này, sinh viên phân tích một cách có hệ thống thông tin phức tạp thành các thành phần cơ bản, liên tục đặt câu hỏi \"tại sao\" và xem xét kỹ cách các bộ phận riêng lẻ tương tác hợp lý để tạo nên hệ thống tổng thể.","g":"new"},{"id":"SSA101_Q254","t":"Before class, why is it useful to record questions about the assigned reading?","o":[["A","To show the professor you did the work","Để cho giảng viên thấy bạn đã làm bài"],["B","To establish a purpose for reading and to identify areas that need clarification during the lecture","Để xác lập mục đích đọc và xác định những phần cần làm rõ trong bài giảng"],["C","To avoid having to take notes during class","Để khỏi phải ghi chép trong lớp"],["D","To memorize the textbook verbatim","Để học thuộc nguyên văn sách giáo khoa"]],"a":"B","s":0,"e":"Actively writing down questions before a lecture forces your brain to engage deeply with the assigned text rather than reading it passively. This practice explicitly identifies your specific knowledge gaps, providing a clear, targeted purpose for listening during class and ensuring you know exactly what concepts to ask the professor to clarify.","ev":"Việc chủ động ghi lại các câu hỏi trước khi nghe giảng sẽ buộc não bộ của bạn phải tương tác sâu sắc với nội dung bài giảng thay vì chỉ đọc một cách thụ động. Cách làm này giúp bạn xác định rõ những lỗ hổng kiến thức cụ thể, tạo mục đích rõ ràng cho việc lắng nghe trong lớp và đảm bảo bạn biết chính xác những khái niệm nào cần hỏi giảng viên để làm rõ.","g":"new","tv":"Trước buổi học, tại sao việc ghi lại các câu hỏi về phần đọc được giao lại hữu ích?"},{"id":"SSA101_Q255","t":"Based on the study by Liang et al. (2023), which group of students is at the highest risk of being falsely accused by \"AI detectors\"?","o":[["A","Students possessing advanced English writing skills and an exceptionally rich vocabulary","Sinh viên có kỹ năng viết tiếng Anh nâng cao và vốn từ vựng đặc biệt phong phú"],["B","Minority students who lack digital literacy and have never previously utilized any AI tools","Sinh viên thiểu số thiếu kỹ năng số và chưa từng dùng bất kỳ công cụ AI nào"],["C","Students currently majoring in Computer Science, engineering, or other technology fields","Sinh viên đang học ngành Khoa học Máy tính, kỹ thuật hoặc các ngành công nghệ khác"],["D","Students who are non-native English writers demonstrating lower grammatical variability","Sinh viên viết tiếng Anh không phải ngôn ngữ mẹ đẻ, có độ biến đổi ngữ pháp thấp hơn"]],"a":"D","s":0,"e":"Because AI text detectors scan for characteristics like low sentence complexity and highly predictable grammatical patterns (low \"perplexity\"), non-native English speakers are disproportionately flagged. These students naturally write with a tighter, more formulaic vocabulary and less structural variability, inadvertently triggering the algorithms and placing them at severe risk of unjust academic penalties.","ev":"Vì các công cụ nhận diện văn bản bằng AI quét các đặc điểm như độ phức tạp câu thấp và các mẫu ngữ pháp dễ đoán (độ \"khó hiểu\" thấp), nên người viết tiếng Anh không phải là người bản ngữ bị gắn cờ với tỷ lệ cao bất cân xứng. Những sinh viên này thường viết với vốn từ vựng khuôn mẫu hơn và ít biến thể cấu trúc, vô tình kích hoạt thuật toán và đối mặt nguy cơ bị phạt học thuật oan uổng.","g":"new","tv":"Dựa trên nghiên cứu của Liang và cộng sự (2023), nhóm sinh viên nào có nguy cơ cao nhất bị \"công cụ phát hiện AI\" buộc tội sai?"},{"id":"SSA101_Q256","t":"Define the student term 'pulling an all-nighter'.","o":[["A","Spending the entire night socializing with friends in the dorms","Dành cả đêm giao lưu với bạn bè trong ký túc xá"],["B","Going without sleep for the entire night to use that time to finish an assignment","Thức trắng cả đêm để dùng thời gian đó hoàn thành một bài tập"],["C","Sleeping for more than 12 hours to catch up on rest","Ngủ hơn 12 tiếng để bù lại giấc nghỉ"],["D","Working a late-night shift at a part-time job","Làm ca đêm ở công việc bán thời gian"]],"a":"B","s":0,"e":"\"Pulling an all-nighter\" refers strictly to the detrimental practice of skipping a full night's sleep to continuously focus on studying or finishing an assignment. It is usually a desperate measure taken by students who have failed to manage their time effectively and have procrastinated to the point where they have no other available hours to meet a strict deadline.","ev":"\"Thức trắng đêm\" thực chất là hành động tai hại khi bỏ qua cả đêm ngủ để tập trung học tập hoặc hoàn thành bài tập. Đây thường là biện pháp tuyệt vọng của những sinh viên không quản lý thời gian hiệu quả và trì hoãn đến mức không còn thời gian nào khác để hoàn thành đúng hạn.","g":"new","tv":"Định nghĩa thuật ngữ sinh viên 'pulling an all-nighter' (thức trắng đêm)."},{"id":"SSA101_Q257","t":"During the \"Storming\" phase of Tuckman's Team Development model, what interpersonal and task-related behaviors are a team most likely to experience?","o":[["A","The members establish base-level expectations, identify common similarities, develop initial trust, and depend heavily on the team leader for overall project direction","Các thành viên thiết lập kỳ vọng cơ bản, xác định điểm chung, xây dựng niềm tin ban đầu và phụ thuộc nhiều vào trưởng nhóm để định hướng dự án"],["B","The members encounter anxiety regarding power and control, express differing opinions, challenge leadership, and potentially form small cliques or experience personal conflicts","Các thành viên gặp lo lắng về quyền lực và kiểm soát, bày tỏ ý kiến khác nhau, thách thức người lãnh đạo, và có thể hình thành các nhóm nhỏ hoặc xảy ra xung đột cá nhân"],["C","The members successfully negotiate their specific roles, build strong mutual appreciation, establish open feedback channels, and commit to the shared goals of the team","Các thành viên thương lượng thành công vai trò cụ thể, xây dựng sự trân trọng lẫn nhau, thiết lập kênh phản hồi cởi mở và cam kết với mục tiêu chung của nhóm"],["D","The members operate extremely efficiently with high motivation, share leadership roles based on individual strengths, and take tremendous pride in their collective success","Các thành viên làm việc cực kỳ hiệu quả với động lực cao, chia sẻ vai trò lãnh đạo dựa trên thế mạnh cá nhân và rất tự hào về thành công chung"]],"a":"B","s":0,"e":"The \"Storming\" phase is the highly turbulent, yet entirely necessary, second stage of successful team development. Because initial politeness transitions into actual work, team members inevitably encounter anxiety regarding power dynamics, clash over conflicting leadership styles, express wildly differing opinions, and potentially fracture into defensive cliques as they aggressively attempt to establish control and boundaries.","ev":"Giai đoạn \"xung đột\" (Storming) là giai đoạn thứ hai đầy biến động nhưng hoàn toàn cần thiết cho sự phát triển thành công của nhóm. Bởi vì sự lịch sự ban đầu chuyển sang công việc thực tế, các thành viên không tránh khỏi lo âu về quyền lực, va chạm phong cách lãnh đạo, bày tỏ ý kiến trái chiều và có thể hình thành phe nhóm phòng thủ khi cố gắng thiết lập quyền kiểm soát.","g":"new","tv":"Trong giai đoạn \"Bão tố\" (Storming) của mô hình Phát triển nhóm của Tuckman, nhóm có khả năng trải qua những hành vi giữa các cá nhân và liên quan đến nhiệm vụ nào nhất?"},{"id":"SSA101_Q258","t":"Define 'Metacognition'.","o":[["A","The process of thinking about how other people think","Quá trình suy nghĩ về cách người khác suy nghĩ"],["B","A type of rapid memorization technique","Một kỹ thuật ghi nhớ nhanh"],["C","The process of thinking about how you think, including planning, tracking, and assessing your own understanding","Quá trình suy nghĩ về cách bạn suy nghĩ, bao gồm lập kế hoạch, theo dõi và đánh giá sự hiểu biết của chính mình"],["D","A method for analyzing statistical data","Một phương pháp phân tích dữ liệu thống kê"]],"a":"C","s":0,"e":"Metacognition is formally defined as \"thinking about thinking.\" It is a vital higher-order cognitive skill where a student takes an objective step back to consciously plan their learning strategies, actively track their current level of comprehension, and honestly assess their own academic understanding to adjust their study habits for maximum efficiency.","ev":"Siêu nhận thức được định nghĩa chính thức là \"suy nghĩ về suy nghĩ\". Đó là một kỹ năng nhận thức bậc cao thiết yếu, trong đó học sinh thực hiện một bước lùi khách quan để lên kế hoạch chiến lược học tập, chủ động theo dõi mức độ hiểu bài hiện tại và tự đánh giá trung thực khả năng tiếp thu để điều chỉnh thói quen học tập đạt hiệu quả tối đa.","g":"new","tv":"Định nghĩa 'Siêu nhận thức' (Metacognition)."},{"id":"SSA101_Q259","t":"Define 'Net Worth' in the context of personal finance.","o":[["A","The total amount of income you earn in a year","Tổng số tiền thu nhập bạn kiếm được trong một năm"],["B","The value of your most expensive asset (like a car or house)","Giá trị của tài sản đắt nhất của bạn (như ô tô hoặc nhà)"],["C","The total measure of your wealth, calculated by subtracting what you owe from what you own","Thước đo tổng thể sự giàu có của bạn, tính bằng cách lấy những gì bạn sở hữu trừ đi những gì bạn nợ"],["D","The amount of money you have in your checking account","Số tiền bạn có trong tài khoản thanh toán"]],"a":"C","s":0,"e":"In structured personal finance, \"Net Worth\" is universally considered the single most accurate and comprehensive indicator of an individual's total financial health. It measures the absolute value of your holistic wealth by taking the total monetary value of everything you own and systematically subtracting the total burden of everything you owe.","ev":"Trong tài chính cá nhân có cấu trúc, \"Giá trị tài sản ròng\" được coi là chỉ số chính xác và toàn diện nhất về sức khỏe tài chính tổng thể của một cá nhân. Nó đo lường giá trị tuyệt đối của toàn bộ tài sản bằng cách lấy tổng giá trị tiền tệ của tất cả những gì bạn sở hữu và trừ đi một cách có hệ thống gánh nặng của tất cả những gì bạn nợ.","g":"new","tv":"Định nghĩa 'Giá trị ròng' (Net Worth) trong bối cảnh tài chính cá nhân."},{"id":"SSA101_Q260","t":"During the \"Norming\" stage of Tuckman's Team Development model, what characteristic behaviors and group dynamics are the team members most likely to exhibit?","o":[["A","The team members begin to experience high anxiety regarding power and control, express differing opinions, challenge leadership, and potentially form exclusive cliques","Các thành viên bắt đầu lo lắng cao về quyền lực và kiểm soát, bày tỏ ý kiến khác nhau, thách thức người lãnh đạo, và có thể hình thành các nhóm nhỏ loại trừ"],["B","The team members operate extremely efficiently with high motivation, share leadership roles based on individual strengths, and take tremendous pride in collective success","Các thành viên làm việc cực kỳ hiệu quả với động lực cao, chia sẻ vai trò lãnh đạo dựa trên thế mạnh cá nhân và rất tự hào về thành công chung"],["C","The team members establish base-level expectations, identify common similarities, develop initial trust, and depend heavily on the designated team leader for direction","Các thành viên thiết lập kỳ vọng cơ bản, xác định điểm chung, xây dựng niềm tin ban đầu và phụ thuộc nhiều vào trưởng nhóm được chỉ định để định hướng"],["D","The team members reach consensus on roles and problem-solving processes, build mutual trust, provide objective feedback, and commit strongly to shared collective goals.","Các thành viên đạt đồng thuận về vai trò và quy trình giải quyết vấn đề, xây dựng niềm tin lẫn nhau, đưa ra phản hồi khách quan và cam kết mạnh mẽ với mục tiêu chung của tập thể."]],"a":"D","s":0,"e":"Following the highly turbulent and heavily conflicted \"Storming\" phase, the \"Norming\" stage represents a critical structural stabilization period where the group finally begins functioning as a cohesive unit. During this vital stage, team members successfully negotiate their specific operational roles, freely establish universally accepted problem-solving processes, and build deep mutual trust. This newly established harmony allows them to provide highly objective feedback and strongly commit themselves entirely to their shared collective goals instead of individual egos.","ev":"Sau giai đoạn \"Xung đột\" đầy biến động và mâu thuẫn, giai đoạn \"Ổn định\" (Norming) là thời kỳ ổn định cấu trúc quan trọng khi nhóm bắt đầu hoạt động như một khối thống nhất. Trong giai đoạn này, các thành viên thương lượng thành công vai trò cụ thể, thiết lập quy trình giải quyết vấn đề chung, xây dựng lòng tin sâu sắc, đưa ra phản hồi khách quan và cam kết mạnh mẽ với mục tiêu chung của tập thể.","g":"new","tv":"Trong giai đoạn \"Ổn định\" (Norming) của mô hình Phát triển nhóm của Tuckman, các thành viên có khả năng thể hiện hành vi và động lực nhóm đặc trưng nào nhất?"},{"id":"SSA101_Q261","t":"In the context of 'Knowing Yourself' for time management, how does fatigue affect study?","o":[["A","It makes you read faster.","Nó khiến bạn đọc nhanh hơn."],["B","It helps your brain absorb information automatically.","Nó giúp não bạn hấp thụ thông tin tự động."],["C","If you are tired, your attention and retention will be much poorer than if you were well-rested.","Nếu bạn mệt, sự chú ý và khả năng ghi nhớ sẽ kém hơn nhiều so với khi bạn được nghỉ ngơi đầy đủ."],["D","It prevents test anxiety.","Nó ngăn chặn lo lắng khi thi."]],"a":"C","s":0,"tv":"In the context of 'Knowing Yourself' for quản lý thời gian, how does fatigue affect study?","e":"The human brain relies entirely on adequate rest to process, encode, and permanently store complex new information. When a student attempts to study while severely fatigued, their brain's cognitive bandwidth is drastically reduced, meaning their ability to maintain active attention plummets and long-term memory retention becomes almost mathematically impossible.","ev":"Não bộ con người hoàn toàn phụ thuộc vào sự nghỉ ngơi đầy đủ để xử lý, mã hóa và lưu trữ lâu dài những thông tin mới phức tạp. Khi một học sinh cố gắng học tập trong tình trạng mệt mỏi nghiêm trọng, khả năng nhận thức của não bộ sẽ giảm mạnh, dẫn đến khả năng duy trì sự tập trung giảm sút và việc ghi nhớ lâu dài trở nên gần như bất khả thi.","g":"new"},{"id":"SSA101_Q262","t":"In personal finance, what are 'Assets'?","o":[["A","The valuable things you own, such as earnings, savings, and investments","Những thứ có giá trị bạn sở hữu, như thu nhập, tiền tiết kiệm và khoản đầu tư"],["B","The money you owe to banks or credit card companies","Tiền bạn nợ ngân hàng hoặc công ty thẻ tín dụng"],["C","Your monthly variable expenses","Các chi phí biến đổi hằng tháng của bạn"],["D","The taxes deducted from your paycheck","Các khoản thuế bị khấu trừ khỏi lương của bạn"]],"a":"A","s":0,"e":"In the realm of personal finance, \"Assets\" refer strictly to measurable resources or items of significant economic value that you own outright or tightly control. Because they hold objective value, assets—which include cash savings, investments, real estate, and valuable physical property—can be reliably liquidated or leveraged to generate future financial benefits.","ev":"Trong lĩnh vực tài chính cá nhân, \"Tài sản\" được hiểu chính xác là các nguồn lực có thể đo lường được hoặc các vật phẩm có giá trị kinh tế đáng kể mà bạn sở hữu hoàn toàn hoặc kiểm soát chặt chẽ. Bởi vì chúng có giá trị khách quan, tài sản—bao gồm tiền tiết kiệm, đầu tư, bất động sản và tài sản vật chất có giá trị—có thể được thanh lý hoặc sử dụng để tạo ra lợi ích tài chính trong tương lai.","g":"new","tv":"Trong tài chính cá nhân, 'Tài sản' (Assets) là gì?"},{"id":"SSA101_Q263","t":"In the context of AI-assisted educational assessments, how is \"Criterion Validity\" formally defined by the scientific evaluation community?","o":[["A","It assesses whether the AI tool truly measures the underlying theoretical concept or specific academic trait that it was originally intended to measure","Nó đánh giá xem công cụ AI có thực sự đo được khái niệm lý thuyết hoặc đặc điểm học thuật cụ thể mà nó vốn được thiết kế để đo hay không"],["B","It examines whether the content of the AI assessment comprehensively covers the entire mathematical or literary range of the subject being evaluated","Nó xem xét liệu nội dung của bài đánh giá AI có bao quát toàn diện toàn bộ phạm vi toán học hoặc văn học của môn được đánh giá hay không"],["C","It evaluates whether the overall user interface of the AI tool appears friendly and intuitively aligned with the superficial goals of the standardized test","Nó đánh giá xem giao diện người dùng tổng thể của công cụ AI có trông thân thiện và phù hợp trực quan với các mục tiêu bề ngoài của bài kiểm tra chuẩn hóa hay không"],["D","It involves directly comparing the specific results generated by the AI assessment against other proven, established measures or actual real-world outcomes","Nó liên quan đến việc so sánh trực tiếp kết quả cụ thể do bài đánh giá AI tạo ra với các thước đo đã được chứng minh, thiết lập khác hoặc kết quả thực tế"]],"a":"D","s":0,"e":"In psychometric testing and educational evaluation, criterion validity is incredibly specific: it determines how well the results of an assessment predict or align with an external, already-established standard of success. Therefore, to ensure an AI grading tool is valid, developers must directly compare its automated scores against proven human evaluations or actual real-world student outcomes.","ev":"Trong kiểm tra tâm lý và đánh giá giáo dục, tính hiệu lực theo tiêu chí (criterion validity) xác định mức độ chính xác của kết quả đánh giá trong việc dự đoán hoặc phù hợp với một tiêu chuẩn thành công đã được thiết lập sẵn từ bên ngoài. Do đó, để đảm bảo công cụ chấm điểm AI hợp lệ, nhà phát triển phải so sánh trực tiếp điểm số tự động của nó với đánh giá của con người hoặc kết quả thực tế của sinh viên.","g":"new","tv":"Trong bối cảnh đánh giá giáo dục có hỗ trợ bởi AI, \"Giá trị tiêu chí\" (Criterion Validity) được cộng đồng đánh giá khoa học định nghĩa chính thức như thế nào?"},{"id":"SSA101_Q264","t":"In the SQ3R strategic reading method, what specific actions should a student take during the \"Recite\" (or second \"R\") phase?","o":[["A","The student should skim the learning objectives, read the chapter summary, and review the end-of-chapter study questions to get a general overview of the text","Sinh viên nên lướt qua mục tiêu học tập, đọc phần tóm tắt chương và xem lại các câu hỏi ôn tập cuối chương để có cái nhìn tổng quan về văn bản"],["B","The student should create a list of \"who, what, where, when, and why\" questions based directly on the primary headings found throughout the chapter text","Sinh viên nên lập danh sách các câu hỏi \"ai, cái gì, ở đâu, khi nào và tại sao\" dựa trực tiếp trên các tiêu đề chính trong chương"],["C","The student should read the text continuously without pausing until they have located all the specific answers to the questions they formulated in the previous step","Sinh viên nên đọc văn bản liên tục không dừng cho đến khi tìm thấy mọi câu trả lời cho các câu hỏi đã đặt ở bước trước"],["D","The student should say the answer to their question out loud and then write it down in their notes using their own personal words and phrasing","Sinh viên nên nói to câu trả lời cho câu hỏi của mình rồi viết vào ghi chú bằng từ ngữ và cách diễn đạt của riêng mình"]],"a":"D","s":0,"e":"The SQ3R reading strategy (Survey, Question, Read, Recite, Review) is meticulously designed to maximize advanced reading comprehension and long-term retention. During the \"Recite\" phase, actively saying the answer out loud and then manually writing it down in your own entirely personal phrasing forces your brain to deeply process the information rather than just passively scanning it. This crucial step immediately tests your real understanding and securely encodes the newly acquired knowledge into your memory.","ev":"Chiến lược đọc SQ3R (Khảo sát, Đặt câu hỏi, Đọc, Tóm tắt, Ôn tập) được thiết kế tỉ mỉ để tối đa hóa khả năng đọc hiểu nâng cao và ghi nhớ lâu dài. Trong giai đoạn \"Tóm tắt\" (Recite), việc chủ động nói to câu trả lời rồi tự viết lại bằng ngôn từ của riêng mình buộc não bộ phải xử lý sâu thông tin, kiểm tra ngay mức độ hiểu thực sự và mã hóa kiến thức vào trí nhớ.","g":"new","tv":"Trong phương pháp đọc chiến lược SQ3R, sinh viên nên thực hiện hành động cụ thể nào trong giai đoạn \"Recite\" (chữ \"R\" thứ hai)?"},{"id":"SSA101_Q265","t":"In the context of financial goals, what does it mean to 'align personal and financial goals'?","o":[["A","Recognizing that personal behaviors have financial consequences and planning your finances to support what you want to achieve in life.","Nhận ra rằng hành vi cá nhân có hậu quả tài chính và lập kế hoạch tài chính để hỗ trợ những gì bạn muốn đạt được trong cuộc sống."],["B","Putting all your money into a savings account.","Bỏ toàn bộ tiền vào tài khoản tiết kiệm."],["C","Borrowing as much money as possible to fund your personal lifestyle.","Vay càng nhiều tiền càng tốt để tài trợ cho lối sống cá nhân của bạn."],["D","Choosing a career based solely on salary.","Chọn nghề chỉ dựa trên mức lương."]],"a":"A","s":0,"e":"Money is not an end in itself; it is simply a tool used to facilitate your desired lifestyle. Aligning these goals means deeply understanding that your daily financial habits directly dictate your ability to achieve major personal milestones—like traveling, buying a home, or retiring comfortably—and deliberately structuring your budget to prioritize funding those specific aspirations.","ev":"Tiền bạc không phải là mục đích tự thân; nó chỉ đơn giản là một công cụ để hỗ trợ lối sống mà bạn mong muốn. Việc điều chỉnh các mục tiêu này có nghĩa là hiểu sâu sắc rằng thói quen tài chính hàng ngày của bạn trực tiếp quyết định khả năng đạt được các cột mốc cá nhân lớn—như du lịch, mua nhà hoặc nghỉ hưu thoải mái—và chủ động lập ngân sách để ưu tiên tài trợ cho những khát vọng đó.","g":"new","tv":"Trong bối cảnh mục tiêu tài chính, 'điều chỉnh mục tiêu cá nhân và tài chính cho phù hợp' có nghĩa là gì?"},{"id":"SSA101_Q266","t":"In the cases of Ellen Rae and Kris Kashtanova, why did the U.S. Copyright Office grant limited copyright to Rae but completely deny Kashtanova?","o":[["A","Because Rae used a text-generating AI (ChatGPT) while Kashtanova used an image-generating AI (Midjourney)","Vì Rae dùng AI tạo văn bản (ChatGPT) còn Kashtanova dùng AI tạo hình ảnh (Midjourney)"],["B","Because Rae significantly shifted, arranged, and manipulated the AI-generated outputs, while Kashtanova simply used the raw AI images with minor editing.","Vì Rae đã thay đổi, sắp xếp và chỉnh sửa đáng kể các sản phẩm do AI tạo ra, còn Kashtanova chỉ dùng các hình ảnh AI thô với chỉnh sửa nhỏ."],["C","Because Rae transparently declared her use of AI tools from the very beginning of the process, whereas Kashtanova deliberately attempted to hide her use of the software.","Vì Rae công khai minh bạch việc dùng công cụ AI ngay từ đầu, trong khi Kashtanova cố tình che giấu việc dùng phần mềm."],["D","Because ChatGPT allows commercial rights, whereas Midjourney does not.","Vì ChatGPT cho phép quyền thương mại, còn Midjourney thì không."]],"a":"B","s":0,"e":"Under current U.S. Copyright guidelines, the core doctrine demands a sufficient amount of human authorship to grant legal protection. The Copyright Office completely denied Kashtanova because her AI-generated images were simply raw outputs with minimal editing, whereas Rae successfully proved she engaged in extensive, highly transformational human manipulation and substantial arrangement of the AI's generated elements.","ev":"Theo hướng dẫn hiện hành về bản quyền của Hoa Kỳ, nguyên tắc cốt lõi đòi hỏi phải có đủ sự can thiệp của con người để được bảo hộ pháp lý. Văn phòng Bản quyền đã hoàn toàn từ chối Kashtanova vì hình ảnh do AI tạo ra của cô chỉ là sản phẩm thô với chỉnh sửa tối thiểu, trong khi Rae đã chứng minh được sự thao tác và sắp xếp mang tính chuyển đổi sâu rộng của con người đối với các yếu tố do AI tạo ra.","g":"new","tv":"Trong trường hợp của Ellen Rae và Kris Kashtanova, tại sao Văn phòng Bản quyền Hoa Kỳ cấp bản quyền hạn chế cho Rae nhưng từ chối hoàn toàn Kashtanova?"},{"id":"SSA101_Q267","t":"In the 'Seven Ways to Stay Motivated', why is 'Rewarding Yourself' important?","o":[["A","It allows you to spend more money.","Nó cho phép bạn tiêu nhiều tiền hơn."],["B","Humans are motivated by rewards, so rewarding yourself for a job well done helps maintain motivation and avoid procrastination.","Con người được thúc đẩy bởi phần thưởng, nên tự thưởng khi làm tốt giúp duy trì động lực và tránh trì hoãn."],["C","It replaces the need for setting long-term goals.","Nó thay thế nhu cầu đặt mục tiêu dài hạn."],["D","It guarantees you will get an A in the class.","Nó đảm bảo bạn sẽ đạt điểm A trong lớp."]],"a":"B","s":0,"e":"Human psychology is fundamentally driven by positive reinforcement; completing difficult or tedious academic tasks safely drains our willpower if it is not adequately replenished. By scheduling intentional, meaningful rewards after intense study sessions, you create a powerful neurological incentive that actively combats the temptation to procrastinate and helps sustain long-term academic endurance.","ev":"Tâm lý con người về cơ bản được thúc đẩy bởi sự củng cố tích cực; việc hoàn thành các nhiệm vụ học tập khó khăn hoặc tẻ nhạt sẽ làm cạn kiệt ý chí của chúng ta nếu không được bổ sung đầy đủ. Bằng cách lên lịch những phần thưởng có ý nghĩa sau các buổi học căng thẳng, bạn tạo ra động lực thần kinh mạnh mẽ giúp chống lại sự trì hoãn và duy trì sức bền học tập lâu dài.","g":"new","tv":"Trong 'Bảy cách để giữ động lực', tại sao 'Tự thưởng cho bản thân' lại quan trọng?"},{"id":"SSA101_Q268","t":"Within the Community of Inquiry (CoI) model, what is the primary function of \"Social Presence\" in an online learning environment?","o":[["A","It requires the instructor to curate the course content carefully and design meaningful activities that will lead students toward professional and intellectual development","Nó yêu cầu giảng viên biên soạn nội dung khóa học cẩn thận và thiết kế các hoạt động có ý nghĩa dẫn dắt sinh viên đến sự phát triển chuyên môn và trí tuệ"],["B","It demands that learners maintain a continuous process of critical thinking to construct new knowledge through direct interaction with the provided course materials","Nó đòi hỏi người học duy trì quá trình tư duy phản biện liên tục để xây dựng kiến thức mới thông qua tương tác trực tiếp với tài liệu khóa học"],["C","It creates a safe and supportive communication environment where students feel trusted enough to express their personal ideas and collaborate with their classmates","Nó tạo ra môi trường giao tiếp an toàn và hỗ trợ, nơi sinh viên cảm thấy đủ tin tưởng để bày tỏ ý tưởng cá nhân và hợp tác với bạn học"],["D","It involves the instructor directly answering student questions during office hours and challenging the students' assumptions to help them grow in their given field","Nó liên quan đến việc giảng viên trực tiếp trả lời câu hỏi của sinh viên trong giờ tiếp sinh viên và thách thức các giả định của sinh viên để giúp họ phát triển trong lĩnh vực của mình"]],"a":"C","s":0,"e":"The Community of Inquiry model asserts that effective online learning is impossible without genuine human connection. Social presence represents the ability of participants to project their actual personal characteristics into the digital space, creating a highly empathetic, safe, and deeply supportive environment where students feel emotionally secure enough to openly express ideas, take academic risks, and freely collaborate.","ev":"Mô hình Cộng đồng Tìm tòi khẳng định rằng việc học trực tuyến hiệu quả là không thể thiếu sự kết nối thực sự giữa người với người. Sự hiện diện xã hội thể hiện khả năng của người tham gia trong việc bộc lộ cá tính thực sự vào không gian số, tạo ra một môi trường đồng cảm, an toàn và hỗ trợ sâu sắc để sinh viên tự tin bày tỏ ý tưởng, chấp nhận rủi ro học thuật và tự do hợp tác.","g":"new","tv":"Trong mô hình Cộng đồng Tìm hiểu (CoI), chức năng chính của \"Sự hiện diện xã hội\" trong môi trường học trực tuyến là gì?"},{"id":"SSA101_Q269","t":"According to the text, what plays a central role in developing an effective identity as an online learner?","o":[["A","Time management skills","Kỹ năng quản lý thời gian"],["B","Information management","Quản lý thông tin"],["C","Social networking","Mạng xã hội"],["D","Memorization techniques","Kỹ thuật ghi nhớ"]],"a":"B","s":0,"tv":"Theo the text, what plays a central role in developing an effective identity as an online learner","e":"Information management plays the central role in building an effective identity as an online learner.","ev":"Quản lý thông tin đóng vai trò trung tâm trong việc xây dựng bản sắc người học trực tuyến hiệu quả."},{"id":"SSA101_Q270","t":"Which of the following is NOT mentioned as a key benefit of using an online notebook like OneNote or Evernote?","o":[["A","Synchronize notes across multiple devices","Đồng bộ ghi chú trên nhiều thiết bị"],["B","Clip and save relevant information from web sources","Cắt và lưu thông tin liên quan từ nguồn web"],["C","Automatically grade assignments","Tự động chấm điểm bài tập"],["D","Store PDFs and course documents for long-term access","Lưu PDF và tài liệu khóa học để truy cập lâu dài"]],"a":"C","s":0,"tv":"Điều nào sau đây KHÔNG phải là mentioned as a key benefit of using an online notebook like OneNote or Evernote?","e":"Online notebooks sync notes, clip web content and store documents, but they do not grade assignments.","ev":"Sổ ghi chú trực tuyến giúp đồng bộ ghi chú, cắt nội dung web và lưu tài liệu, nhưng không tự chấm bài tập."},{"id":"SSA101_Q271","t":"Why might online learners experience information overload?","o":[["A","Too few digital resources are available","Có quá ít tài nguyên số"],["B","The large volume of readings and abundance of digital resources","Khối lượng lớn các bài đọc và sự dồi dào của tài nguyên số"],["C","Lack of internet connection","Thiếu kết nối internet"],["D","Limited course materials provided by instructors","Giảng viên cung cấp tài liệu khóa học hạn chế"]],"a":"B","s":0,"tv":"Tại sao người học trực tuyến có thể bị quá tải thông tin?","e":"Too many readings and abundant digital resources cause information overload.","ev":"Khối lượng lớn các bài đọc và tài nguyên số dồi dào gây ra quá tải thông tin."},{"id":"SSA101_Q272","t":"In online learning, the role of the instructor is best described as:","o":[["A","The central figure who determines all content and direction","Nhân vật trung tâm quyết định mọi nội dung và định hướng"],["B","A guide who directs students toward learning experiences aligned with their goals","Người hướng dẫn dẫn dắt sinh viên đến các trải nghiệm học tập phù hợp với mục tiêu của họ"],["C","The person solely responsible for grading","Người chỉ chịu trách nhiệm chấm điểm"],["D","Someone who replaces peer support entirely","Người thay thế hoàn toàn sự hỗ trợ của bạn học"]],"a":"B","s":0,"tv":"Trong học trực tuyến, vai trò của giảng viên được mô tả đúng nhất là:","e":"The online instructor acts as a guide, directing students toward learning experiences that fit their goals.","ev":"Giảng viên trực tuyến đóng vai trò người hướng dẫn, dẫn dắt sinh viên đến các trải nghiệm học tập phù hợp mục tiêu."},{"id":"SSA101_Q273","t":"Which skill is NOT listed as a core skill for self-directed (independent) learning?","o":[["A","Define clear learning goals","Xác định mục tiêu học tập rõ ràng"],["B","Seek necessary support when required","Tìm kiếm sự hỗ trợ cần thiết khi cần"],["C","Memorize all lecture slides word-for-word","Học thuộc từng chữ toàn bộ slide bài giảng"],["D","Choose learning strategies that support personal understanding","Chọn chiến lược học hỗ trợ sự hiểu biết cá nhân"]],"a":"C","s":0,"tv":"Kỹ năng nào KHÔNG được liệt kê là kỹ năng cốt lõi của việc tự học (học độc lập)?","e":"Self-directed learning is about goals, support and strategies, not memorizing slides word for word.","ev":"Tự học tập trung vào mục tiêu, sự hỗ trợ và chiến lược, chứ không phải học thuộc từng chữ các slide."},{"id":"SSA101_Q274","t":"Metacognition is best defined as:","o":[["A","Memorizing facts quickly","Ghi nhớ sự kiện nhanh"],["B","Thinking about your thinking","Suy nghĩ về cách mình suy nghĩ"],["C","Group discussion skills","Kỹ năng thảo luận nhóm"],["D","Using advanced software tools","Sử dụng các công cụ phần mềm nâng cao"]],"a":"B","s":0,"tv":"Siêu nhận thức được định nghĩa đúng nhất là:","e":"Metacognition is thinking about your own thinking.","ev":"Siêu nhận thức là suy nghĩ về chính quá trình tư duy của mình."},{"id":"SSA101_Q275","t":"In the Plan-Monitor-Evaluate model, the \"Monitoring\" stage primarily involves:","o":[["A","Setting initial learning goals","Đặt mục tiêu học tập ban đầu"],["B","Asking \"How am I doing at learning this?\"","Tự hỏi \"Mình đang học việc này ra sao?\""],["C","Reflecting after receiving final grades","Suy ngẫm sau khi nhận điểm cuối cùng"],["D","Choosing which course to enroll in","Chọn môn học để đăng ký"]],"a":"B","s":0,"tv":"Trong mô hình Lập kế hoạch – Theo dõi – Đánh giá, giai đoạn \"Theo dõi\" chủ yếu bao gồm:","e":"Monitoring means asking yourself how well you are learning while you are learning.","ev":"Theo dõi là tự hỏi mình đang học tốt đến đâu ngay trong lúc học."},{"id":"SSA101_Q276","t":"Which question is an example from the \"Evaluating\" stage of the Plan-Monitor-Evaluate model?","o":[["A","What do I need to learn?","Mình cần học gì?"],["B","How am I going to learn the material?","Mình sẽ học tài liệu bằng cách nào?"],["C","Did I learn the material effectively?","Mình đã học tài liệu hiệu quả chưa?"],["D","What remains unclear right now?","Hiện giờ còn điều gì chưa rõ?"]],"a":"C","s":0,"tv":"Câu hỏi nào là ví dụ từ giai đoạn \"Đánh giá\" của mô hình Lập kế hoạch – Theo dõi – Đánh giá?","e":"Evaluating looks back at results, so \"Did I learn the material effectively?\" is an evaluation question.","ev":"Giai đoạn đánh giá nhìn lại kết quả, nên \"Mình đã học hiệu quả chưa?\" là câu hỏi đánh giá."},{"id":"SSA101_Q277","t":"According to Bloom's Taxonomy, which level comes immediately after \"Understanding\"?","o":[["A","Remembering","Ghi nhớ"],["B","Applying","Áp dụng"],["C","Analyzing","Phân tích"],["D","Creating","Sáng tạo"]],"a":"B","s":0,"tv":"Theo Bloom's Taxonomy, which level comes immediately after \"Understanding\"","e":"In Bloom's Taxonomy the order is Remember, Understand, Apply, so Applying follows Understanding.","ev":"Trong thang Bloom thứ tự là Ghi nhớ, Hiểu, Áp dụng, nên Áp dụng đứng ngay sau Hiểu."},{"id":"SSA101_Q278","t":"A question such as \"What is the definition of global warming?\" belongs to which level of Bloom's Taxonomy?","o":[["A","Understanding","Hiểu"],["B","Applying","Áp dụng"],["C","Remembering","Ghi nhớ"],["D","Evaluating","Đánh giá"]],"a":"C","s":0,"tv":"Một câu hỏi như \"Định nghĩa của hiện tượng nóng lên toàn cầu là gì?\" thuộc cấp độ nào trong thang Bloom?","e":"Asking for a definition only requires recalling facts, which is the Remembering level.","ev":"Hỏi định nghĩa chỉ cần nhớ lại sự kiện, tức cấp độ Ghi nhớ."},{"id":"SSA101_Q279","t":"Which type of question is associated with the \"Analyze\" level of Bloom's Taxonomy?","o":[["A","What is the definition of…?","Định nghĩa của… là gì?"],["B","What is the relationship between… and …?","Mối quan hệ giữa… và … là gì?"],["C","What are my own examples of…?","Ví dụ của riêng tôi về… là gì?"],["D","What will happen if temperatures continue to rise?","Điều gì sẽ xảy ra nếu nhiệt độ tiếp tục tăng?"]],"a":"B","s":0,"tv":"Loại câu hỏi nào gắn với cấp độ \"Phân tích\" trong thang Bloom?","e":"Analyze-level questions ask about relationships between parts.","ev":"Câu hỏi cấp độ Phân tích hỏi về mối quan hệ giữa các thành phần."},{"id":"SSA101_Q280","t":"An \"Evaluate\" level question typically includes judgment using criteria such as:","o":[["A","What are the steps to…?","Các bước để… là gì?"],["B","Effective or ineffective? Why?","Hiệu quả hay không hiệu quả? Tại sao?"],["C","How does the process occur?","Quá trình diễn ra như thế nào?"],["D","Who discovered…?","Ai đã phát hiện ra…?"]],"a":"B","s":0,"tv":"Một câu hỏi cấp độ \"Đánh giá\" thường bao gồm sự nhận định theo các tiêu chí như:","e":"Evaluate-level questions require judging with criteria, such as effective or ineffective and why.","ev":"Câu hỏi cấp độ Đánh giá yêu cầu nhận định theo tiêu chí, ví dụ hiệu quả hay không và tại sao."},{"id":"SSA101_Q281","t":"The \"Create\" level of Bloom's Taxonomy involves:","o":[["A","Simply listing facts","Chỉ liệt kê sự kiện"],["B","Generating new ideas or establishing new connections","Tạo ra ý tưởng mới hoặc thiết lập các kết nối mới"],["C","Explaining in your own words","Giải thích bằng lời của mình"],["D","Comparing two theories","So sánh hai lý thuyết"]],"a":"B","s":0,"tv":"Cấp độ \"Sáng tạo\" của thang Bloom bao gồm:","e":"The Create level means producing new ideas or making new connections.","ev":"Cấp độ Sáng tạo là tạo ra ý tưởng mới hoặc thiết lập các kết nối mới."},{"id":"SSA101_Q282","t":"Which reading strategy is recommended depending on the objective of the reading activity?","o":[["A","Always doing close reading for every text","Luôn đọc kỹ cho mọi văn bản"],["B","Skimming, focusing on key sections, or close reading","Đọc lướt, tập trung vào các phần chính, hoặc đọc kỹ"],["C","Only reading summaries written by others","Chỉ đọc bản tóm tắt do người khác viết"],["D","Ignoring the purpose and reading everything fully","Bỏ qua mục đích và đọc toàn bộ mọi thứ"]],"a":"B","s":0,"tv":"Chiến lược đọc nào được khuyến nghị tùy theo mục tiêu của hoạt động đọc?","e":"The reading strategy should match the purpose: skim, focus on key sections, or read closely.","ev":"Chiến lược đọc nên phù hợp mục đích: đọc lướt, tập trung phần chính hoặc đọc kỹ."},{"id":"SSA101_Q283","t":"The text suggests that university-level learning especially emphasizes:","o":[["A","Memorization of all details","Ghi nhớ mọi chi tiết"],["B","Higher-order thinking skills (applying, analyzing, evaluating, creating)","Các kỹ năng tư duy bậc cao (áp dụng, phân tích, đánh giá, sáng tạo)"],["C","Passive listening only","Chỉ nghe thụ động"],["D","Copying notes from classmates","Chép ghi chú của bạn học"]],"a":"B","s":0,"tv":"Văn bản gợi ý rằng việc học ở bậc đại học đặc biệt nhấn mạnh:","e":"University learning emphasizes higher-order thinking: applying, analyzing, evaluating and creating.","ev":"Học đại học nhấn mạnh tư duy bậc cao: áp dụng, phân tích, đánh giá và sáng tạo."},{"id":"SSA101_Q284","t":"According to the text, which stage of team development is often misunderstood as dysfunction but is actually a normal part?","o":[["A","Forming","Hình thành"],["B","Storming","Bão tố"],["C","Norming","Ổn định"],["D","Performing","Thực hiện"]],"a":"B","s":0,"tv":"Theo the text, which stage of team development is often misunderstood as dysfunction but is actually a normal part","e":"Storming is often mistaken for dysfunction but is a normal stage of team development.","ev":"Giai đoạn Bão tố thường bị hiểu nhầm là nhóm trục trặc nhưng thực ra là một phần bình thường của quá trình phát triển nhóm."},{"id":"SSA101_Q285","t":"In the \"Forming\" stage, which characteristic is NOT typically present?","o":[["A","Low commitment to the team","Cam kết thấp với nhóm"],["B","Unclear roles and responsibilities","Vai trò và trách nhiệm chưa rõ ràng"],["C","High trust among members","Niềm tin cao giữa các thành viên"],["D","Lack of group history","Thiếu lịch sử làm việc nhóm"]],"a":"C","s":0,"tv":"Trong giai đoạn \"Hình thành\", đặc điểm nào thường KHÔNG xuất hiện?","e":"High trust takes time to build, so it is not typical of the Forming stage.","ev":"Niềm tin cao cần thời gian xây dựng nên không điển hình ở giai đoạn Hình thành."},{"id":"SSA101_Q286","t":"During the \"Storming\" stage, what tends to increase among team members?","o":[["A","Trust and appreciation","Niềm tin và sự trân trọng"],["B","Conflict and competition","Xung đột và cạnh tranh"],["C","Efficient operations","Hoạt động hiệu quả"],["D","Shared leadership","Lãnh đạo chia sẻ"]],"a":"B","s":0,"tv":"Trong giai đoạn \"Bão tố\", điều gì có xu hướng tăng lên giữa các thành viên nhóm?","e":"Storming brings more conflict and competition as members challenge each other.","ev":"Giai đoạn Bão tố làm xung đột và cạnh tranh tăng lên khi các thành viên thách thức nhau."},{"id":"SSA101_Q287","t":"Which action step is recommended to move from \"Norming\" to \"Performing\"?","o":[["A","Define the team mission and goals","Xác định sứ mệnh và mục tiêu của nhóm"],["B","Encourage shared leadership and responsibility","Khuyến khích lãnh đạo và trách nhiệm chia sẻ"],["C","Clarify roles during initial meetings","Làm rõ vai trò trong các cuộc họp đầu tiên"],["D","Actively reinforce positive behavior to reduce conflict","Chủ động củng cố hành vi tích cực để giảm xung đột"]],"a":"B","s":0,"tv":"Bước hành động nào được khuyến nghị để chuyển từ \"Ổn định\" sang \"Thực hiện\"?","e":"Moving from Norming to Performing is supported by encouraging shared leadership and responsibility.","ev":"Chuyển từ Ổn định sang Thực hiện được hỗ trợ bằng cách khuyến khích lãnh đạo và trách nhiệm chia sẻ."},{"id":"SSA101_Q288","t":"In the Community of Inquiry framework, what are the two key roles learners assume?","o":[["A","Teaching presence and content creation","Sự hiện diện giảng dạy và sáng tạo nội dung"],["B","Maintaining cognitive presence and developing social presence","Duy trì sự hiện diện nhận thức và phát triển sự hiện diện xã hội"],["C","Instructor guidance and peer competition","Hướng dẫn của giảng viên và cạnh tranh giữa bạn học"],["D","Memorization and individual testing","Ghi nhớ và kiểm tra cá nhân"]],"a":"B","s":0,"tv":"Trong khung Cộng đồng Tìm hiểu, hai vai trò chính mà người học đảm nhận là gì?","e":"Learners maintain cognitive presence and develop social presence in the Community of Inquiry.","ev":"Người học duy trì sự hiện diện nhận thức và phát triển sự hiện diện xã hội trong Cộng đồng Tìm hiểu."},{"id":"SSA101_Q289","t":"Cognitive presence in a learning community primarily involves:","o":[["A","Using emoticons to express emotions","Dùng biểu tượng cảm xúc để thể hiện cảm xúc"],["B","An ongoing process of critical thinking and constructing new knowledge","Một quá trình liên tục của tư duy phản biện và xây dựng kiến thức mới"],["C","Focusing only on individual exams","Chỉ tập trung vào các kỳ thi cá nhân"],["D","Avoiding discussions with peers","Tránh thảo luận với bạn học"]],"a":"B","s":0,"tv":"Sự hiện diện nhận thức trong một cộng đồng học tập chủ yếu bao gồm:","e":"Cognitive presence is the ongoing process of critical thinking and building new knowledge.","ev":"Sự hiện diện nhận thức là quá trình liên tục của tư duy phản biện và xây dựng kiến thức mới."},{"id":"SSA101_Q290","t":"Social presence is supported online by strategies such as:","o":[["A","Ignoring group work","Phớt lờ làm việc nhóm"],["B","Using emoticons to convey nuances and emotions","Dùng biểu tượng cảm xúc để truyền đạt sắc thái và cảm xúc"],["C","Limiting communication to the instructor","Giới hạn giao tiếp chỉ với giảng viên"],["D","Focusing solely on task completion","Chỉ tập trung hoàn thành nhiệm vụ"]],"a":"B","s":0,"tv":"Sự hiện diện xã hội trực tuyến được hỗ trợ bằng các chiến lược như:","e":"Emoticons help convey tone and emotion online, which supports social presence.","ev":"Biểu tượng cảm xúc giúp truyền đạt sắc thái và cảm xúc trực tuyến, từ đó hỗ trợ sự hiện diện xã hội."},{"id":"SSA101_Q291","t":"Which of the following is NOT one of the five basic elements of effective teamwork mentioned in the text?","o":[["A","Positive interdependence","Sự phụ thuộc tích cực lẫn nhau"],["B","Individual accountability","Trách nhiệm cá nhân"],["C","Group processing","Xử lý nhóm"],["D","Financial incentives","Khuyến khích tài chính"]],"a":"D","s":0,"tv":"Điều nào sau đây KHÔNG phải là one of the five basic elements of effective teamwork mentioned in the text?","e":"The five basic elements of teamwork do not include financial incentives.","ev":"Năm yếu tố cơ bản của làm việc nhóm hiệu quả không bao gồm khuyến khích tài chính."},{"id":"SSA101_Q292","t":"Positive interdependence means that team members believe:","o":[["A","Individual success is possible without group success","Thành công cá nhân có thể đạt được mà không cần thành công của nhóm"],["B","They are linked together in a shared outcome; success is mutual","Họ gắn kết với nhau trong một kết quả chung; thành công là của cả nhóm"],["C","Only the leader is responsible for results","Chỉ người lãnh đạo chịu trách nhiệm về kết quả"],["D","Competition among members drives performance","Cạnh tranh giữa các thành viên thúc đẩy hiệu suất"]],"a":"B","s":0,"tv":"Sự phụ thuộc tích cực lẫn nhau (positive interdependence) có nghĩa là các thành viên nhóm tin rằng:","e":"Positive interdependence means members are linked in a shared outcome, so success is mutual.","ev":"Phụ thuộc tích cực nghĩa là các thành viên gắn kết trong một kết quả chung nên thành công là của cả nhóm."},{"id":"SSA101_Q293","t":"What does \"group processing\" involve at the end of a working period?","o":[["A","Ignoring past performance","Phớt lờ kết quả trước đây"],["B","Evaluating the group's functioning and identifying improvements","Đánh giá hoạt động của nhóm và xác định các điểm cần cải thiện"],["C","Assigning blame to individuals","Quy trách nhiệm cho cá nhân"],["D","Focusing only on final grades","Chỉ tập trung vào điểm số cuối cùng"]],"a":"B","s":0,"tv":"\"Xử lý nhóm\" (group processing) bao gồm điều gì vào cuối một giai đoạn làm việc?","e":"Group processing means evaluating how the group worked and finding ways to improve.","ev":"Xử lý nhóm là đánh giá cách nhóm đã làm việc và xác định điểm cần cải thiện."},{"id":"SSA101_Q294","t":"In the \"Performing\" stage, teams demonstrate:","o":[["A","High dependency on the leader","Sự phụ thuộc cao vào người lãnh đạo"],["B","A strong \"we\" orientation and superior performance","Định hướng \"chúng ta\" mạnh mẽ và hiệu suất vượt trội"],["C","Frequent unresolved conflicts","Thường xuyên xung đột chưa được giải quyết"],["D","Unclear shared goals","Mục tiêu chung không rõ ràng"]],"a":"B","s":0,"tv":"Trong giai đoạn \"Thực hiện\", các nhóm thể hiện:","e":"In the Performing stage teams have a strong \"we\" orientation and perform at a high level.","ev":"Ở giai đoạn Thực hiện, nhóm có định hướng \"chúng ta\" mạnh và hiệu suất vượt trội."},{"id":"SSA101_Q295","t":"When planning for successful teamwork, what should teams do in the \"Forming\" stage regarding interpersonal tasks?","o":[["A","Express differences aggressively","Bày tỏ sự khác biệt một cách hung hăng"],["B","Initiate contact, build connections, and develop trust","Chủ động liên hệ, xây dựng kết nối và phát triển niềm tin"],["C","Delegate all tasks immediately","Giao toàn bộ nhiệm vụ ngay lập tức"],["D","Focus only on project deadlines","Chỉ tập trung vào hạn chót dự án"]],"a":"B","s":0,"tv":"Khi lập kế hoạch cho làm việc nhóm thành công, nhóm nên làm gì ở giai đoạn \"Hình thành\" về các nhiệm vụ liên cá nhân?","e":"In Forming, teams should start contact, build connections and develop trust.","ev":"Ở giai đoạn Hình thành, nhóm nên chủ động liên hệ, xây dựng kết nối và phát triển niềm tin."},{"id":"SSA101_Q296","t":"A team charter, as mentioned for effective communication, typically includes commitments to:","o":[["A","Blame individuals for problems","Đổ lỗi cho cá nhân khi có vấn đề"],["B","Respect, active listening, and constructive feedback","Sự tôn trọng, lắng nghe chủ động và phản hồi mang tính xây dựng"],["C","Avoid conflict at all costs","Tránh xung đột bằng mọi giá"],["D","Work independently without discussion","Làm việc độc lập không thảo luận"]],"a":"B","s":0,"tv":"Bản điều lệ nhóm (team charter), như được đề cập cho giao tiếp hiệu quả, thường bao gồm các cam kết về:","e":"A team charter commits members to respect, active listening and constructive feedback.","ev":"Điều lệ nhóm cam kết các thành viên tôn trọng, lắng nghe chủ động và phản hồi mang tính xây dựng."},{"id":"SSA101_Q297","t":"In the framework for working together, a \"shared vision\" is described as:","o":[["A","A past-oriented summary of achievements","Bản tóm tắt thành tựu hướng về quá khứ"],["B","A future-oriented statement of purpose aligned with members' values","Một tuyên bố mục đích hướng về tương lai, phù hợp với giá trị của các thành viên"],["C","An administrative job description","Một bản mô tả công việc hành chính"],["D","A list of unrelated personal goals","Danh sách các mục tiêu cá nhân không liên quan"]],"a":"B","s":0,"tv":"Trong khung làm việc cùng nhau, \"tầm nhìn chung\" được mô tả là:","e":"A shared vision is a future-oriented statement of purpose that fits members' values.","ev":"Tầm nhìn chung là tuyên bố mục đích hướng tới tương lai, phù hợp với giá trị của các thành viên."},{"id":"SSA101_Q298","t":"Continuous improvement in teamwork is achieved through:","o":[["A","Large, drastic changes only","Chỉ những thay đổi lớn, mạnh mẽ"],["B","Small, incremental changes with planning, implementation, and verification","Những thay đổi nhỏ, tăng dần với lập kế hoạch, thực hiện và kiểm tra"],["C","Avoiding any evaluation of progress","Tránh mọi đánh giá về tiến độ"],["D","Focusing solely on individual rewards","Chỉ tập trung vào phần thưởng cá nhân"]],"a":"B","s":0,"tv":"Sự cải tiến liên tục trong làm việc nhóm đạt được thông qua:","e":"Continuous improvement comes from small, incremental changes with planning, implementation and checking.","ev":"Cải tiến liên tục đến từ những thay đổi nhỏ, tăng dần với lập kế hoạch, thực hiện và kiểm tra."},{"id":"SSA101_Q299","t":"According to the text, building an effective relationship with instructors primarily supports:","o":[["A","Avoiding all course assignments","Tránh mọi bài tập của khóa học"],["B","Success in an online learning environment","Thành công trong môi trường học trực tuyến"],["C","Reducing the need for feedback","Giảm nhu cầu phản hồi"],["D","Limiting communication to email only","Giới hạn giao tiếp chỉ qua email"]],"a":"B","s":0,"tv":"Theo the text, building an effective relationship with instructors primarily supports:","e":"A good relationship with instructors mainly supports success in an online learning environment.","ev":"Mối quan hệ tốt với giảng viên chủ yếu hỗ trợ thành công trong môi trường học trực tuyến."},{"id":"SSA101_Q300","t":"Why is it important to understand the purpose behind learning activities designed by the instructor?","o":[["A","To skip unnecessary readings","Để bỏ qua các bài đọc không cần thiết"],["B","To increase motivation, improve focus, and stay aligned with course expectations","Để tăng động lực, cải thiện sự tập trung và bám sát kỳ vọng của khóa học"],["C","To memorize content faster","Để học thuộc nội dung nhanh hơn"],["D","To avoid participating in discussions","Để tránh tham gia thảo luận"]],"a":"B","s":0,"tv":"Tại sao it important to understand the purpose behind learning activities designed by the instructor?","e":"Knowing the purpose of activities raises motivation, sharpens focus and keeps you aligned with expectations.","ev":"Hiểu mục đích của các hoạt động giúp tăng động lực, cải thiện tập trung và bám sát kỳ vọng của khóa học."},{"id":"SSA101_Q301","t":"Which of the following is recommended as a way to engage through direct interaction with instructors?","o":[["A","Ignoring office hours completely","Hoàn toàn bỏ qua giờ tiếp sinh viên"],["B","Taking advantage of face-to-face meetings or online office hours","Tận dụng các buổi gặp trực tiếp hoặc giờ tiếp sinh viên trực tuyến"],["C","Only contacting instructors after the course ends","Chỉ liên hệ giảng viên sau khi khóa học kết thúc"],["D","Relying solely on classmates for clarification","Chỉ dựa vào bạn học để được làm rõ"]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là recommended as a way to engage through direct interaction with instructors?","e":"Face-to-face meetings and online office hours are recommended for direct interaction with instructors.","ev":"Các buổi gặp trực tiếp và giờ tiếp sinh viên trực tuyến được khuyến nghị để tương tác trực tiếp với giảng viên."},{"id":"SSA101_Q302","t":"The text suggests using email to contact instructors because it is considered:","o":[["A","An informal and casual tool","Một công cụ không chính thức và thân mật"],["B","A professional communication tool","Một công cụ giao tiếp chuyên nghiệp"],["C","Unnecessary in online courses","Không cần thiết trong các khóa học trực tuyến"],["D","Only for submitting late assignments","Chỉ để nộp bài trễ"]],"a":"B","s":0,"tv":"Văn bản gợi ý dùng email để liên hệ giảng viên vì nó được xem là:","e":"Email is considered a professional communication tool for contacting instructors.","ev":"Email được xem là công cụ giao tiếp chuyên nghiệp để liên hệ giảng viên."},{"id":"SSA101_Q303","t":"What is the main benefit of carefully reviewing instructor feedback on assignments?","o":[["A","To argue against the grade received","Để tranh luận về điểm đã nhận"],["B","To identify areas for improvement and support continuous skill development","Để xác định các điểm cần cải thiện và hỗ trợ phát triển kỹ năng liên tục"],["C","To avoid future assignments","Để tránh các bài tập sau này"],["D","To compare feedback with classmates only","Chỉ để so sánh phản hồi với bạn học"]],"a":"B","s":0,"tv":"Lợi ích chính của việc xem kỹ phản hồi của giảng viên về bài tập là gì?","e":"Reviewing feedback carefully shows what to improve and supports continuous skill development.","ev":"Xem kỹ phản hồi cho thấy điểm cần cải thiện và hỗ trợ phát triển kỹ năng liên tục."},{"id":"SSA101_Q304","t":"In an online course, the instructor's \"teaching presence\" primarily involves:","o":[["A","Avoiding all student questions","Tránh mọi câu hỏi của sinh viên"],["B","Designing meaningful learning experiences and supporting student engagement","Thiết kế các trải nghiệm học tập có ý nghĩa và hỗ trợ sự tham gia của sinh viên"],["C","Letting students design the course structure","Để sinh viên tự thiết kế cấu trúc khóa học"],["D","Focusing only on final exams","Chỉ tập trung vào kỳ thi cuối kỳ"]],"a":"B","s":0,"tv":"Trong một khóa học trực tuyến, \"sự hiện diện giảng dạy\" của giảng viên chủ yếu bao gồm:","e":"Teaching presence means designing meaningful learning experiences and supporting student engagement.","ev":"Sự hiện diện giảng dạy là thiết kế các trải nghiệm học tập có ý nghĩa và hỗ trợ sự tham gia của sinh viên."},{"id":"SSA101_Q305","t":"Which role of the online instructor involves guiding students by answering questions and challenging assumptions?","o":[["A","Designer","Người thiết kế"],["B","Facilitator","Người điều phối"],["C","Director","Người chỉ đạo"],["D","Evaluator","Người đánh giá"]],"a":"C","s":0,"tv":"Vai trò nào của giảng viên trực tuyến liên quan đến việc hướng dẫn sinh viên bằng cách trả lời câu hỏi và thách thức các giả định?","e":"The Director role guides students by answering questions and challenging their assumptions.","ev":"Vai trò Người chỉ đạo hướng dẫn sinh viên bằng cách trả lời câu hỏi và thách thức các giả định."},{"id":"SSA101_Q306","t":"In the \"Designer\" role, instructors primarily:","o":[["A","Ignore course objectives","Phớt lờ mục tiêu khóa học"],["B","Design the course structure and guide students to relevant, accurate learning resources","Thiết kế cấu trúc khóa học và hướng sinh viên đến các tài nguyên học tập phù hợp, chính xác"],["C","Only grade assignments","Chỉ chấm bài tập"],["D","Avoid selecting readings","Tránh chọn tài liệu đọc"]],"a":"B","s":0,"tv":"Ở vai trò \"Người thiết kế\", giảng viên chủ yếu:","e":"As Designer, the instructor builds the course structure and points students to relevant, accurate resources.","ev":"Ở vai trò Người thiết kế, giảng viên xây dựng cấu trúc khóa học và hướng sinh viên đến tài nguyên phù hợp, chính xác."},{"id":"SSA101_Q307","t":"The \"Facilitator\" role of an online instructor focuses on:","o":[["A","Creating unstructured activities","Tạo các hoạt động không có cấu trúc"],["B","Designing assignments and activities to support intellectual, personal, and professional growth","Thiết kế bài tập và hoạt động để hỗ trợ sự phát triển trí tuệ, cá nhân và nghề nghiệp"],["C","Limiting student interaction","Hạn chế tương tác của sinh viên"],["D","Focusing only on theoretical content","Chỉ tập trung vào nội dung lý thuyết"]],"a":"B","s":0,"tv":"Vai trò \"Người điều phối\" của giảng viên trực tuyến tập trung vào:","e":"The Facilitator designs assignments and activities that support intellectual, personal and professional growth.","ev":"Người điều phối thiết kế bài tập và hoạt động hỗ trợ sự phát triển về trí tuệ, cá nhân và nghề nghiệp."},{"id":"SSA101_Q308","t":"Which action demonstrates active participation and interest in the course material?","o":[["A","Checking the course site only once a month","Chỉ vào trang khóa học một lần mỗi tháng"],["B","Participating actively in discussions and activities","Tham gia tích cực vào các thảo luận và hoạt động"],["C","Submitting assignments without reviewing instructions","Nộp bài mà không xem lại hướng dẫn"],["D","Avoiding all contact with the instructor","Tránh mọi liên hệ với giảng viên"]],"a":"B","s":0,"tv":"Hành động nào thể hiện sự tham gia tích cực và quan tâm đến tài liệu khóa học?","e":"Taking an active part in discussions and activities shows interest and engagement.","ev":"Tham gia tích cực vào thảo luận và hoạt động thể hiện sự quan tâm và gắn kết."},{"id":"SSA101_Q309","t":"To stay aware of course expectations and changes, students should:","o":[["A","Ignore announcements","Phớt lờ thông báo"],["B","Check the course site frequently for updates","Thường xuyên kiểm tra trang khóa học để cập nhật"],["C","Rely only on classmates for information","Chỉ dựa vào bạn học để biết thông tin"],["D","Wait until the end of the term","Chờ đến cuối học kỳ"]],"a":"B","s":0,"tv":"Để nắm được kỳ vọng và thay đổi của khóa học, sinh viên nên:","e":"Students should check the course site often to stay aware of expectations and changes.","ev":"Sinh viên nên thường xuyên kiểm tra trang khóa học để nắm kỳ vọng và các thay đổi."},{"id":"SSA101_Q310","t":"Office hours are useful for:","o":[["A","Socializing unrelated to the course","Giao lưu không liên quan đến khóa học"],["B","Clarifying academic difficulties and strengthening professional relationships","Làm rõ khó khăn học tập và củng cố mối quan hệ chuyên nghiệp"],["C","Submitting all assignments late","Nộp tất cả bài tập trễ"],["D","Avoiding feedback on work","Tránh phản hồi về bài làm"]],"a":"B","s":0,"tv":"Giờ tiếp sinh viên hữu ích để:","e":"Office hours help clarify academic difficulties and strengthen professional relationships.","ev":"Giờ tiếp sinh viên giúp làm rõ khó khăn học tập và củng cố mối quan hệ chuyên nghiệp."},{"id":"SSA101_Q311","t":"The text emphasizes that effective communication with instructors helps students:","o":[["A","Avoid learning the content","Tránh học nội dung"],["B","Fully benefit from instructional support throughout the learning process","Hưởng lợi đầy đủ từ sự hỗ trợ giảng dạy trong suốt quá trình học"],["C","Reduce the amount of work required","Giảm khối lượng công việc cần làm"],["D","Focus only on grades","Chỉ tập trung vào điểm số"]],"a":"B","s":0,"tv":"Văn bản nhấn mạnh rằng giao tiếp hiệu quả với giảng viên giúp sinh viên:","e":"Good communication lets students benefit fully from instructional support throughout learning.","ev":"Giao tiếp tốt giúp sinh viên hưởng lợi đầy đủ từ sự hỗ trợ giảng dạy trong suốt quá trình học."},{"id":"SSA101_Q312","t":"In the Community of Inquiry model mentioned in Part 3, the instructor's role supports:","o":[["A","Passive learning only","Chỉ việc học thụ động"],["B","Student engagement and the active role of learners in the environment","Sự tham gia của sinh viên và vai trò chủ động của người học trong môi trường"],["C","Elimination of all assignments","Việc loại bỏ mọi bài tập"],["D","Instructor-centered lectures exclusively","Các bài giảng lấy giảng viên làm trung tâm hoàn toàn"]],"a":"B","s":0,"tv":"Trong mô hình Cộng đồng Tìm hiểu được nhắc ở Phần 3, vai trò của giảng viên hỗ trợ:","e":"The instructor's role supports student engagement and the active role of learners.","ev":"Vai trò của giảng viên hỗ trợ sự tham gia của sinh viên và vai trò chủ động của người học."},{"id":"SSA101_Q313","t":"Each course component in an online environment, according to the instructor's Facilitator role, is chosen:","o":[["A","Randomly without purpose","Ngẫu nhiên, không có mục đích"],["B","Intentionally to contribute to student development","Có chủ ý để góp phần vào sự phát triển của sinh viên"],["C","Only for entertainment","Chỉ để giải trí"],["D","To increase student workload unnecessarily","Để tăng khối lượng công việc của sinh viên một cách không cần thiết"]],"a":"B","s":0,"tv":"Theo vai trò Người điều phối của giảng viên, mỗi thành phần khóa học trong môi trường trực tuyến được chọn:","e":"Each course component is chosen on purpose to contribute to student development.","ev":"Mỗi thành phần của khóa học được chọn có chủ ý để góp phần vào sự phát triển của sinh viên."},{"id":"SSA101_Q314","t":"Why is flexibility in online courses particularly important for many learners?","o":[["A","It eliminates the need for any schedule","Nó loại bỏ nhu cầu có bất kỳ lịch trình nào"],["B","It allows balancing work, family, or other commitments while studying","Nó cho phép cân bằng công việc, gia đình hoặc các cam kết khác trong khi học"],["C","It reduces the total workload automatically","Nó tự động giảm tổng khối lượng công việc"],["D","It requires less effort in planning","Nó đòi hỏi ít nỗ lực lập kế hoạch hơn"]],"a":"B","s":0,"tv":"Tại sao flexibility in online courses particularly important for many learners?","e":"Flexibility lets learners balance study with work, family or other commitments.","ev":"Sự linh hoạt cho phép người học cân bằng việc học với công việc, gia đình hoặc các cam kết khác."},{"id":"SSA101_Q315","t":"What is the main purpose of creating a master semester schedule?","o":[["A","To focus only on daily tasks","Để chỉ tập trung vào các nhiệm vụ hằng ngày"],["B","To provide an \"overview at a glance\" of all academic requirements and stay on track","Để có \"cái nhìn tổng quan chỉ trong một lần nhìn\" về mọi yêu cầu học tập và đi đúng hướng"],["C","To replace weekly reviews completely","Để thay thế hoàn toàn việc ôn tập hằng tuần"],["D","To avoid using course presentations","Để tránh dùng các bài thuyết trình của khóa học"]],"a":"B","s":0,"tv":"Mục đích chính của creating a master semester schedule là gì?","e":"A master semester schedule gives an overview at a glance of all academic requirements so you stay on track.","ev":"Lịch tổng học kỳ cho cái nhìn tổng quan về mọi yêu cầu học tập để bạn đi đúng hướng."},{"id":"SSA101_Q316","t":"In Step 1 of designing a semester schedule, what should the table include?","o":[["A","Only one column for all days","Chỉ một cột cho tất cả các ngày"],["B","Seven columns for days of the week and one row for each week of the semester","Bảy cột cho các ngày trong tuần và một hàng cho mỗi tuần của học kỳ"],["C","Rows for months instead of weeks","Các hàng cho tháng thay vì tuần"],["D","No labels for days or weeks","Không có nhãn cho ngày hay tuần"]],"a":"B","s":0,"tv":"Ở Bước 1 của việc thiết kế lịch học kỳ, bảng nên bao gồm những gì?","e":"The table has seven columns for the days of the week and one row per week of the semester.","ev":"Bảng có bảy cột cho các ngày trong tuần và một hàng cho mỗi tuần của học kỳ."},{"id":"SSA101_Q317","t":"When populating the semester schedule (Step 3), what should be recorded for graded assignments?","o":[["A","Only the due date","Chỉ ngày đến hạn"],["B","The course name, task details, and its value (points/weight)","Tên môn học, chi tiết nhiệm vụ và giá trị của nó (điểm/trọng số)"],["C","Personal opinions about the task","Ý kiến cá nhân về nhiệm vụ"],["D","Only personal events","Chỉ các sự kiện cá nhân"]],"a":"B","s":0,"tv":"Khi điền vào lịch học kỳ (Bước 3), cần ghi lại những gì cho các bài tập có chấm điểm?","e":"Graded assignments should record the course name, task details and value (points or weight).","ev":"Bài tập có chấm điểm nên ghi tên môn, chi tiết nhiệm vụ và giá trị (điểm/trọng số)."},{"id":"SSA101_Q318","t":"According to the text, approximately how many hours per week should each university course require for study?","o":[["A","3–5 hours","3–5 giờ"],["B","9–12 hours","9–12 giờ"],["C","20+ hours","20+ giờ"],["D","Only during class time","Chỉ trong giờ học"]],"a":"B","s":0,"tv":"Theo the text, approximately how many hours per week should each university course require for study","e":"Each university course is expected to need roughly 9–12 hours of study per week.","ev":"Mỗi môn đại học được kỳ vọng cần khoảng 9–12 giờ học mỗi tuần."},{"id":"SSA101_Q319","t":"Why is it recommended to plan multiple shorter study sessions rather than one long block?","o":[["A","To increase cognitive overload","Để tăng quá tải nhận thức"],["B","To improve focus and retention","Để cải thiện sự tập trung và ghi nhớ"],["C","To avoid any routine","Để tránh mọi thói quen"],["D","To reduce the total study time","Để giảm tổng thời gian học"]],"a":"B","s":0,"tv":"Tại sao it recommended to plan multiple shorter study sessions rather than one long block?","e":"Several shorter sessions improve focus and retention compared with one long block.","ev":"Nhiều buổi học ngắn cải thiện sự tập trung và ghi nhớ hơn một buổi học dài."},{"id":"SSA101_Q320","t":"What should be included in a weekly schedule to support well-being?","o":[["A","No time for rest","Không có thời gian nghỉ ngơi"],["B","Daily time for physical activity and time blocks for rest/recreation on weekends","Thời gian vận động mỗi ngày và các khối thời gian nghỉ ngơi/giải trí vào cuối tuần"],["C","Only academic tasks","Chỉ các nhiệm vụ học tập"],["D","Unlimited OPEN blocks without limits","Các khối thời gian TRỐNG không giới hạn"]],"a":"B","s":0,"tv":"Nên đưa gì vào lịch tuần để hỗ trợ sức khỏe tinh thần và thể chất?","e":"A healthy weekly schedule includes daily physical activity and rest or recreation time on weekends.","ev":"Lịch tuần lành mạnh gồm thời gian vận động mỗi ngày và thời gian nghỉ ngơi/giải trí vào cuối tuần."},{"id":"SSA101_Q321","t":"The weekly review (WR) for each course is best scheduled:","o":[["A","At the beginning of the week","Vào đầu tuần"],["B","Preferably at the end of the week","Tốt nhất là vào cuối tuần"],["C","Only once per month","Chỉ một lần mỗi tháng"],["D","During class time only","Chỉ trong giờ học"]],"a":"B","s":0,"tv":"Buổi ôn tập hằng tuần (WR) cho mỗi môn nên được lên lịch tốt nhất:","e":"The weekly review is best placed at the end of the week, after the week's material has been covered.","ev":"Ôn tập hằng tuần tốt nhất đặt vào cuối tuần, sau khi đã học xong tài liệu của tuần."},{"id":"SSA101_Q322","t":"Studying in smaller blocks of time helps primarily by:","o":[["A","Increasing cognitive overload","Tăng quá tải nhận thức"],["B","Covering material in manageable segments and reducing overload","Bao quát tài liệu theo từng phần dễ quản lý và giảm quá tải"],["C","Focusing on the entire workload at once","Tập trung vào toàn bộ khối lượng công việc cùng lúc"],["D","Eliminating the need for planning","Loại bỏ nhu cầu lập kế hoạch"]],"a":"B","s":0,"tv":"Học theo các khối thời gian nhỏ giúp chủ yếu bằng cách:","e":"Smaller blocks cover material in manageable pieces and reduce overload.","ev":"Các khối thời gian nhỏ giúp học tài liệu theo từng phần dễ quản lý và giảm quá tải."},{"id":"SSA101_Q323","t":"Which strategy is suggested for using small blocks of time productively during commuting?","o":[["A","Ignoring study completely","Hoàn toàn bỏ qua việc học"],["B","Scanning/skimming readings, using flash cards, or listening to audio recordings","Quét/lướt các bài đọc, dùng thẻ ghi nhớ hoặc nghe ghi âm"],["C","Watching full-length movies","Xem phim dài"],["D","Only social media browsing","Chỉ lướt mạng xã hội"]],"a":"B","s":0,"tv":"Chiến lược nào được gợi ý để tận dụng hiệu quả các khoảng thời gian ngắn khi đi lại?","e":"Commuting time can be used to skim readings, use flash cards or listen to audio recordings.","ev":"Thời gian đi lại có thể dùng để lướt bài đọc, dùng thẻ ghi nhớ hoặc nghe ghi âm."},{"id":"SSA101_Q324","t":"When creating a daily to-do list, which three key questions should be considered for each task?","o":[["A","Who, what, where","Ai, cái gì, ở đâu"],["B","When to complete, how much time required, is it a priority","Khi nào hoàn thành, cần bao nhiêu thời gian, có phải ưu tiên không"],["C","Why, how, if","Tại sao, như thế nào, nếu"],["D","Cost, location, people involved","Chi phí, địa điểm, những người liên quan"]],"a":"B","s":0,"tv":"Khi tạo danh sách việc cần làm hằng ngày, nên cân nhắc ba câu hỏi chính nào cho mỗi nhiệm vụ?","e":"For each task ask when it must be done, how much time it needs and whether it is a priority.","ev":"Với mỗi nhiệm vụ cần hỏi khi nào hoàn thành, cần bao nhiêu thời gian và có phải ưu tiên không."},{"id":"SSA101_Q325","t":"At the end of the day, what should be done with incomplete tasks on the to-do list?","o":[["A","Ignore them permanently","Bỏ qua chúng vĩnh viễn"],["B","Evaluate, reschedule to another day if necessary, or remove if no longer important","Đánh giá, dời sang ngày khác nếu cần, hoặc xóa nếu không còn quan trọng"],["C","Blame external factors only","Chỉ đổ lỗi cho các yếu tố bên ngoài"],["D","Double the workload tomorrow","Nhân đôi khối lượng công việc ngày mai"]],"a":"B","s":0,"tv":"Cuối ngày, nên làm gì với các nhiệm vụ chưa hoàn thành trong danh sách việc cần làm?","e":"Incomplete tasks should be evaluated, rescheduled if needed, or removed if no longer important.","ev":"Các nhiệm vụ chưa xong nên được đánh giá, dời lịch nếu cần hoặc xóa nếu không còn quan trọng."},{"id":"SSA101_Q326","t":"Which is NOT listed as an advantage of a paper planner for daily task management?","o":[["A","Does not require learning new technology","Không cần học công nghệ mới"],["B","Reduces distractions from digital apps","Giảm xao nhãng từ các ứng dụng số"],["C","Easy to share tasks during group projects","Dễ chia sẻ nhiệm vụ trong các dự án nhóm"],["D","Flexible and adaptable to preferences","Linh hoạt và thích ứng theo sở thích"]],"a":"C","s":0,"tv":"Điều nào KHÔNG được liệt kê là ưu điểm của sổ kế hoạch giấy trong quản lý nhiệm vụ hằng ngày?","e":"Paper planners are hard to share, so easy sharing during group projects is not one of their advantages.","ev":"Sổ giấy khó chia sẻ nên việc dễ chia sẻ nhiệm vụ trong dự án nhóm không phải là ưu điểm của nó."},{"id":"SSA101_Q327","t":"One key benefit of an online calendar (e.g., Google Calendar) mentioned in the text is:","o":[["A","It cannot be accessed on multiple devices","Nó không thể truy cập trên nhiều thiết bị"],["B","It integrates tasks and commitments into a single view and facilitates sharing events","Nó tích hợp nhiệm vụ và cam kết vào một giao diện duy nhất và giúp chia sẻ sự kiện dễ dàng"],["C","It only handles small tasks well","Nó chỉ xử lý tốt các nhiệm vụ nhỏ"],["D","It requires payment for basic use","Nó yêu cầu trả phí cho việc sử dụng cơ bản"]],"a":"B","s":0,"tv":"Một lợi ích chính của lịch trực tuyến (ví dụ Google Calendar) được nhắc trong văn bản là:","e":"An online calendar puts tasks and commitments in one view and makes sharing events easy.","ev":"Lịch trực tuyến gom nhiệm vụ và cam kết vào một giao diện và giúp chia sẻ sự kiện dễ dàng."},{"id":"SSA101_Q328","t":"Online forums in courses primarily contribute to the development of:","o":[["A","Only cognitive presence","Chỉ sự hiện diện nhận thức"],["B","Social presence and cognitive presence within the learning community","Sự hiện diện xã hội và sự hiện diện nhận thức trong cộng đồng học tập"],["C","Teaching presence exclusively","Riêng sự hiện diện giảng dạy"],["D","Individual memorization skills","Kỹ năng ghi nhớ cá nhân"]],"a":"B","s":0,"tv":"Các diễn đàn trực tuyến trong khóa học chủ yếu góp phần phát triển:","e":"Online forums develop both social presence and cognitive presence in the learning community.","ev":"Diễn đàn trực tuyến phát triển cả sự hiện diện xã hội lẫn sự hiện diện nhận thức trong cộng đồng học tập."},{"id":"SSA101_Q329","t":"According to the Level 3 (Most Successful) rubric criteria, a good forum post should:","o":[["A","Be posted only once per course","Chỉ đăng một lần trong mỗi khóa học"],["B","Reflect thoughtful reflection on readings, engage with colleagues' postings, and contribute to class understanding","Phản ánh sự suy ngẫm sâu sắc về bài đọc, tương tác với bài đăng của bạn học và đóng góp vào sự hiểu biết của lớp"],["C","Focus solely on personal opinions without references","Chỉ tập trung vào ý kiến cá nhân mà không có tài liệu tham khảo"],["D","Contain multiple grammatical errors for authenticity","Chứa nhiều lỗi ngữ pháp để tạo sự chân thực"]],"a":"B","s":0,"tv":"Theo the Level 3 (Most Successful) rubric criteria, a good forum post should:","e":"A top-level forum post reflects thoughtfully on readings, engages with peers and adds to class understanding.","ev":"Bài đăng diễn đàn đạt mức cao nhất suy ngẫm sâu về bài đọc, tương tác với bạn học và đóng góp cho sự hiểu biết của lớp."},{"id":"SSA101_Q330","t":"Which tip is NOT recommended for participating effectively in online forums?","o":[["A","Establish a regular posting schedule","Thiết lập lịch đăng bài đều đặn"],["B","Use overly informal language to build rapport","Dùng ngôn ngữ quá thân mật để tạo thiện cảm"],["C","Make explicit connections between posts and course content","Kết nối rõ ràng giữa bài đăng và nội dung khóa học"],["D","Respond respectfully and constructively, even with alternative viewpoints","Phản hồi tôn trọng và mang tính xây dựng, ngay cả với quan điểm khác biệt"]],"a":"B","s":0,"tv":"Lời khuyên nào KHÔNG được khuyến nghị để tham gia diễn đàn trực tuyến hiệu quả?","e":"Overly informal language is not recommended in course forums, which expect a respectful, professional tone.","ev":"Ngôn ngữ quá thân mật không được khuyến nghị vì diễn đàn khóa học cần giọng điệu tôn trọng, chuyên nghiệp."},{"id":"SSA101_Q331","t":"Effective feedback when giving it must include all of the following EXCEPT:","o":[["A","Identify what is being done correctly and well","Xác định những gì đang làm đúng và tốt"],["B","Explain how performance can be improved","Giải thích cách có thể cải thiện hiệu suất"],["C","Suggest possible next steps","Gợi ý các bước tiếp theo có thể làm"],["D","Compare the person's work to others in the class","So sánh bài làm của người đó với những người khác trong lớp"]],"a":"D","s":0,"tv":"Khi đưa ra phản hồi hiệu quả, phải bao gồm tất cả những điều sau NGOẠI TRỪ:","e":"Effective feedback focuses on the person's own work and does not compare them with classmates.","ev":"Phản hồi hiệu quả tập trung vào bài làm của chính người đó và không so sánh với bạn học."},{"id":"SSA101_Q332","t":"When receiving feedback, why is it important to suspend immediate reactions?","o":[["A","To avoid understanding the feedback","Để tránh hiểu phản hồi"],["B","Emotional reactions like defensiveness can interfere with fully understanding the information","Phản ứng cảm xúc như phòng thủ có thể cản trở việc hiểu đầy đủ thông tin"],["C","To immediately argue against the feedback","Để lập tức tranh cãi lại phản hồi"],["D","Because feedback is always negative","Vì phản hồi luôn tiêu cực"]],"a":"B","s":0,"tv":"Khi nhận phản hồi, tại sao việc tạm gác phản ứng tức thời lại quan trọng?","e":"Emotional reactions such as defensiveness can stop you from fully understanding the feedback.","ev":"Phản ứng cảm xúc như phòng thủ có thể cản trở việc hiểu đầy đủ phản hồi."},{"id":"SSA101_Q333","t":"Positive feedback is most effective when it is:","o":[["A","Based on rumours rather than facts","Dựa trên tin đồn thay vì sự thật"],["B","Offered at an appropriate time, includes recognition of strengths and suggestions, targets changeable behavior, and addresses one point at a time","Được đưa ra đúng lúc, ghi nhận điểm mạnh và gợi ý, nhắm vào hành vi có thể thay đổi và chỉ đề cập một điểm mỗi lần"],["C","Given without prior agreement or permission","Được đưa ra mà không có sự đồng ý hay cho phép trước"],["D","Delivered under high stress conditions","Được truyền đạt trong điều kiện căng thẳng cao"]],"a":"B","s":0,"tv":"Phản hồi tích cực hiệu quả nhất khi nó:","e":"Positive feedback works best when it is well-timed, names strengths, targets changeable behavior and covers one point at a time.","ev":"Phản hồi tích cực hiệu quả nhất khi đúng lúc, nêu điểm mạnh, nhắm hành vi có thể thay đổi và chỉ một điểm mỗi lần."},{"id":"SSA101_Q334","t":"Before giving feedback, it is important to:","o":[["A","Offer it without gathering facts","Đưa ra mà không thu thập sự kiện"],["B","Obtain mutual agreement to engage in feedback and gather relevant facts/perspectives","Có được sự đồng thuận của cả hai bên để trao đổi phản hồi và thu thập các sự kiện/góc nhìn liên quan"],["C","Use absolute language like \"always\" or \"never\"","Dùng ngôn ngữ tuyệt đối như \"luôn luôn\" hoặc \"không bao giờ\""],["D","Compare the recipient to classmates","So sánh người nhận với bạn học"]],"a":"B","s":0,"tv":"Trước khi đưa ra phản hồi, điều quan trọng là:","e":"Before giving feedback, agree to have the conversation and gather relevant facts and perspectives.","ev":"Trước khi phản hồi, cần có sự đồng thuận để trao đổi và thu thập các sự kiện, góc nhìn liên quan."},{"id":"SSA101_Q335","t":"ePortfolios emphasize reflection on:","o":[["A","Only the final product or grade","Chỉ sản phẩm cuối cùng hoặc điểm số"],["B","The learning process rather than focusing solely on final products","Quá trình học tập thay vì chỉ tập trung vào sản phẩm cuối cùng"],["C","Technical tool usage exclusively","Chỉ việc sử dụng công cụ kỹ thuật"],["D","Competition with other students","Cạnh tranh với sinh viên khác"]],"a":"B","s":0,"tv":"Hồ sơ điện tử (ePortfolio) nhấn mạnh sự suy ngẫm về:","e":"ePortfolios stress reflecting on the learning process, not just final products.","ev":"ePortfolio nhấn mạnh suy ngẫm về quá trình học thay vì chỉ sản phẩm cuối cùng."},{"id":"SSA101_Q336","t":"Which of the following is a key benefit of maintaining an ePortfolio?","o":[["A","It replaces the need for any course assignments","Nó thay thế nhu cầu làm bất kỳ bài tập nào của khóa học"],["B","It provides documented evidence of learning for future study programs or employment","Nó cung cấp bằng chứng được ghi lại về việc học cho các chương trình học hoặc công việc trong tương lai"],["C","It focuses only on weekly grades","Nó chỉ tập trung vào điểm số hằng tuần"],["D","It eliminates the need for reflection","Nó loại bỏ nhu cầu suy ngẫm"]],"a":"B","s":0,"tv":"Lựa chọn nào sau đây là a key benefit of maintaining an ePortfolio?","e":"An ePortfolio gives documented evidence of learning for future study or employment.","ev":"ePortfolio cung cấp bằng chứng có ghi lại về việc học cho các chương trình học hoặc công việc sau này."},{"id":"SSA101_Q337","t":"Commonly mentioned tools for creating ePortfolios in the text are:","o":[["A","Microsoft Word and Excel","Microsoft Word và Excel"],["B","Mahara and WordPress","Mahara và WordPress"],["C","Email and forums only","Chỉ email và diễn đàn"],["D","Paper notebooks","Sổ tay giấy"]],"a":"B","s":0,"tv":"Các công cụ thường được nhắc để tạo ePortfolio trong văn bản là:","e":"Mahara and WordPress are the tools mentioned for building ePortfolios.","ev":"Mahara và WordPress là các công cụ được nhắc đến để tạo ePortfolio."},{"id":"SSA101_Q338","t":"Email is described as a primary method of communication in online learning because it is:","o":[["A","Always requiring instant replies","Luôn yêu cầu trả lời ngay"],["B","Familiar, convenient, easy to access, and supports active participation with instructors","Quen thuộc, tiện lợi, dễ truy cập và hỗ trợ sự tham gia tích cực với giảng viên"],["C","Only used for formal complaints","Chỉ dùng cho khiếu nại chính thức"],["D","Informal and casual in tone","Không trang trọng và thân mật về giọng điệu"]],"a":"B","s":0,"tv":"Email được mô tả là phương thức giao tiếp chính trong học trực tuyến vì nó:","e":"Email is familiar, convenient and easy to access, and it supports active participation with instructors.","ev":"Email quen thuộc, tiện lợi, dễ truy cập và hỗ trợ sự tham gia tích cực với giảng viên."},{"id":"SSA101_Q339","t":"When writing professional emails to instructors, which practice should be avoided?","o":[["A","Using a clear and informative subject line","Dùng dòng tiêu đề rõ ràng, nhiều thông tin"],["B","Sending excessively brief messages that may seem impolite","Gửi thư quá ngắn có thể trông thiếu lịch sự"],["C","Proofreading for grammar and organizing into clear paragraphs","Soát ngữ pháp và chia thành các đoạn rõ ràng"],["D","Maintaining a formal and professional tone","Giữ giọng điệu trang trọng và chuyên nghiệp"]],"a":"B","s":0,"tv":"Khi viết email chuyên nghiệp cho giảng viên, nên tránh thực hành nào?","e":"Messages that are too brief can seem impolite and should be avoided.","ev":"Thư quá ngắn có thể bị xem là thiếu lịch sự nên cần tránh."},{"id":"SSA101_Q340","t":"Before sending an email to an instructor, students should first:","o":[["A","Immediately send without checking","Gửi ngay mà không kiểm tra"],["B","Review course materials such as the syllabus, assignment descriptions, or lecture notes","Xem lại tài liệu khóa học như đề cương, mô tả bài tập hoặc ghi chú bài giảng"],["C","Ask classmates for the answer instead","Hỏi bạn học đáp án thay vì tự tìm"],["D","Wait until the last minute","Chờ đến phút cuối"]],"a":"B","s":0,"tv":"Trước khi gửi email cho giảng viên, sinh viên nên làm gì trước tiên?","e":"Check course materials like the syllabus first, because the answer may already be there.","ev":"Hãy xem lại tài liệu khóa học như đề cương trước, vì câu trả lời có thể đã có sẵn ở đó."},{"id":"SSA101_Q341","t":"Regarding email response times from instructors, the text advises:","o":[["A","Expecting immediate replies within minutes","Mong đợi trả lời ngay trong vài phút"],["B","Responses may take 1–3 days, and follow-up only after at least 5 days","Phản hồi có thể mất 1–3 ngày, và chỉ nhắc lại sau ít nhất 5 ngày"],["C","Sending multiple follow-ups the same day","Gửi nhiều email nhắc lại trong cùng một ngày"],["D","Assuming no response means the question is ignored","Cho rằng không có phản hồi nghĩa là câu hỏi bị bỏ qua"]],"a":"B","s":0,"tv":"Về thời gian giảng viên phản hồi email, văn bản khuyên:","e":"Instructors may take 1–3 days to reply, so follow up only after at least 5 days.","ev":"Giảng viên có thể mất 1–3 ngày để trả lời, nên chỉ nhắc lại sau ít nhất 5 ngày."},{"id":"SSA101_Q342","t":"In forum participation, Level 1 (Unsuccessful) posts are characterized by:","o":[["A","Consistent posting and clear writing","Đăng bài đều đặn và viết rõ ràng"],["B","Lack of understanding of readings, no engagement with classmates, irrelevance, inconsistency, and poor writing structure","Thiếu hiểu biết về bài đọc, không tương tác với bạn học, không liên quan, không nhất quán và cấu trúc viết kém"],["C","Strong contributions to class understanding","Đóng góp mạnh cho sự hiểu biết của lớp"],["D","Regular interaction and professional style","Tương tác thường xuyên và phong cách chuyên nghiệp"]],"a":"B","s":0,"tv":"Trong việc tham gia diễn đàn, các bài đăng Mức 1 (Không thành công) có đặc điểm:","e":"Level 1 posts show poor understanding of readings, no engagement, irrelevance, inconsistency and weak structure.","ev":"Bài Mức 1 thể hiện hiểu bài đọc kém, không tương tác, lạc đề, thiếu nhất quán và cấu trúc viết yếu."},{"id":"SSA101_Q343","t":"According to the text, what should be done immediately upon receiving an assignment?","o":[["A","Start writing without reading it fully","Bắt đầu viết mà không đọc kỹ"],["B","Read the assignment carefully right away","Đọc kỹ bài tập ngay lập tức"],["C","Wait until the deadline approaches","Chờ đến khi hạn chót gần đến"],["D","Ask classmates for the requirements","Hỏi bạn học các yêu cầu"]],"a":"B","s":0,"tv":"Theo the text, what should be done immediately upon receiving an assignment","e":"You should read the assignment carefully as soon as you receive it.","ev":"Bạn nên đọc kỹ bài tập ngay khi nhận được."},{"id":"SSA101_Q344","t":"If any part of the assignment requirements is unclear, the recommended action is to:","o":[["A","Ignore it and proceed anyway","Phớt lờ và cứ tiếp tục"],["B","Request clarification from the instructor","Yêu cầu giảng viên làm rõ"],["C","Assume your own interpretation","Giả định cách hiểu của riêng bạn"],["D","Change the assignment topic","Đổi chủ đề bài tập"]],"a":"B","s":0,"tv":"Nếu bất kỳ phần nào của yêu cầu bài tập chưa rõ, hành động được khuyến nghị là:","e":"If any requirement is unclear, ask the instructor to clarify it.","ev":"Nếu yêu cầu nào chưa rõ, hãy nhờ giảng viên làm rõ."},{"id":"SSA101_Q345","t":"Which of the following is NOT listed as a key question to ask when interpreting an assignment?","o":[["A","What is the required task?","Nhiệm vụ yêu cầu là gì?"],["B","What is the purpose of the task?","Mục đích của nhiệm vụ là gì?"],["C","How much will this affect my final grade?","Việc này sẽ ảnh hưởng đến điểm cuối kỳ của tôi bao nhiêu?"],["D","What referencing style must be used?","Phải dùng kiểu trích dẫn tham khảo nào?"]],"a":"C","s":0,"tv":"Điều nào sau đây KHÔNG phải là listed as a key question to ask when interpreting an assignment?","e":"Interpreting an assignment focuses on task, purpose and referencing style, not on how it affects your final grade.","ev":"Việc diễn giải bài tập tập trung vào nhiệm vụ, mục đích và kiểu trích dẫn, chứ không phải ảnh hưởng đến điểm cuối kỳ."},{"id":"SSA101_Q346","t":"The term \"analyze\" falls under which category of common academic task terms?","o":[["A","Identification terms","Thuật ngữ nhận diện"],["B","Description terms","Thuật ngữ mô tả"],["C","Relation terms","Thuật ngữ quan hệ"],["D","Evaluation terms","Thuật ngữ đánh giá"]],"a":"C","s":0,"tv":"Thuật ngữ \"phân tích\" (analyze) thuộc loại thuật ngữ nhiệm vụ học thuật phổ biến nào?","e":"\"Analyze\" is a relation term because it asks you to examine how parts relate to one another.","ev":"\"Phân tích\" là thuật ngữ quan hệ vì yêu cầu xem xét các thành phần liên hệ với nhau thế nào."},{"id":"SSA101_Q347","t":"Which category of academic task terms includes \"justify,\" \"prove,\" and \"demonstrate\"?","o":[["A","Description terms","Thuật ngữ mô tả"],["B","Demonstration terms","Thuật ngữ chứng minh (demonstration)"],["C","Evaluation terms","Thuật ngữ đánh giá"],["D","Identification terms","Thuật ngữ nhận diện"]],"a":"B","s":0,"tv":"Loại thuật ngữ nhiệm vụ học thuật nào bao gồm \"biện minh\", \"chứng minh\" và \"thể hiện\"?","e":"Justify, prove and demonstrate belong to the demonstration terms.","ev":"Biện minh, chứng minh và thể hiện thuộc nhóm thuật ngữ chứng minh (demonstration)."},{"id":"SSA101_Q348","t":"A rubric is best defined as:","o":[["A","A list of optional suggestions for the assignment","Danh sách các gợi ý tùy chọn cho bài tập"],["B","An assessment tool outlining how the work will be graded and the criteria for success","Công cụ đánh giá nêu cách chấm bài và các tiêu chí để thành công"],["C","The final grade sheet from the instructor","Bảng điểm cuối cùng của giảng viên"],["D","A template for formatting the paper","Mẫu định dạng cho bài viết"]],"a":"B","s":0,"tv":"Thang chấm (rubric) được định nghĩa đúng nhất là:","e":"A rubric is an assessment tool that shows how the work will be graded and the criteria for success.","ev":"Rubric là công cụ đánh giá cho biết bài sẽ được chấm thế nào và các tiêu chí để thành công."},{"id":"SSA101_Q349","t":"When should the rubric be reviewed for the first time according to the text?","o":[["A","Only after submitting the assignment","Chỉ sau khi nộp bài"],["B","Carefully before beginning the assignment","Xem kỹ trước khi bắt đầu làm bài"],["C","During the final proofreading stage","Trong giai đoạn đọc soát lần cuối"],["D","After receiving the graded feedback","Sau khi nhận phản hồi đã chấm"]],"a":"B","s":0,"tv":"Theo văn bản, khi nào nên xem thang chấm lần đầu tiên?","e":"Review the rubric carefully before starting the assignment so you know what is expected.","ev":"Hãy xem kỹ rubric trước khi bắt đầu làm bài để biết điều được kỳ vọng."},{"id":"SSA101_Q350","t":"After completing a draft, the rubric should primarily be used for:","o":[["A","Ignoring minor issues","Bỏ qua các vấn đề nhỏ"],["B","Self-evaluation by grading the work against each criterion and revising weak areas","Tự đánh giá bằng cách chấm bài theo từng tiêu chí và sửa lại các phần yếu"],["C","Sharing with classmates only","Chỉ chia sẻ với bạn học"],["D","Calculating the expected grade without changes","Tính điểm dự kiến mà không thay đổi gì"]],"a":"B","s":0,"tv":"Sau khi hoàn thành bản nháp, thang chấm chủ yếu nên được dùng để:","e":"After a draft, use the rubric to grade your own work criterion by criterion and fix weak areas.","ev":"Sau khi có bản nháp, hãy dùng rubric tự chấm từng tiêu chí và sửa các phần yếu."},{"id":"SSA101_Q351","t":"One major benefit of regularly using a rubric for self-assessment is that it helps:","o":[["A","Avoid all instructor feedback","Tránh mọi phản hồi của giảng viên"],["B","Develop accurate self-assessment skills and align self-evaluation closer to instructor expectations over time","Phát triển kỹ năng tự đánh giá chính xác và đưa việc tự đánh giá gần hơn với kỳ vọng của giảng viên theo thời gian"],["C","Reduce the need to revise work","Giảm nhu cầu sửa bài"],["D","Focus only on final products","Chỉ tập trung vào sản phẩm cuối cùng"]],"a":"B","s":0,"tv":"Một lợi ích lớn của việc thường xuyên dùng thang chấm để tự đánh giá là giúp:","e":"Regular rubric self-assessment builds accurate self-evaluation that moves closer to the instructor's expectations.","ev":"Thường xuyên tự đánh giá bằng rubric rèn kỹ năng tự đánh giá chính xác, ngày càng gần với kỳ vọng của giảng viên."},{"id":"SSA101_Q352","t":"When breaking down a large assignment (e.g., a research paper), each step should be:","o":[["A","As broad and general as possible","Rộng và chung chung nhất có thể"],["B","Specific, realistic, and achievable within one day or a single work session","Cụ thể, thực tế và có thể đạt được trong một ngày hoặc một buổi làm việc"],["C","Combined into one massive task","Gộp thành một nhiệm vụ khổng lồ"],["D","Left unplanned until the deadline","Không lập kế hoạch cho đến hạn chót"]],"a":"B","s":0,"tv":"Khi chia nhỏ một bài tập lớn (ví dụ bài nghiên cứu), mỗi bước nên:","e":"Each step should be specific, realistic and doable in one day or one work session.","ev":"Mỗi bước nên cụ thể, thực tế và làm được trong một ngày hoặc một buổi làm việc."},{"id":"SSA101_Q353","t":"Why are broad goals like \"work on research paper\" considered insufficient?","o":[["A","They are too specific","Chúng quá cụ thể"],["B","They are insufficiently defined and may increase procrastination","Chúng chưa được xác định đủ rõ và có thể làm tăng sự trì hoãn"],["C","They guarantee high grades","Chúng đảm bảo điểm cao"],["D","They require no planning","Chúng không cần lập kế hoạch"]],"a":"B","s":0,"tv":"Tại sao các mục tiêu rộng như \"làm bài nghiên cứu\" bị coi là không đủ?","e":"Broad goals are vague and can increase procrastination.","ev":"Mục tiêu rộng thì mơ hồ và có thể làm tăng sự trì hoãn."},{"id":"SSA101_Q354","t":"Typical steps in a research paper assignment plan include all of the following EXCEPT:","o":[["A","Reviewing instructions and selecting a topic","Xem lại hướng dẫn và chọn chủ đề"],["B","Conducting research and taking notes","Thực hiện nghiên cứu và ghi chép"],["C","Drafting sections, revising, and submitting","Viết nháp các phần, chỉnh sửa và nộp bài"],["D","Waiting for classmates to finish first","Chờ bạn học làm xong trước"]],"a":"D","s":0,"tv":"Các bước điển hình trong kế hoạch bài nghiên cứu bao gồm tất cả những điều sau NGOẠI TRỪ:","e":"Waiting for classmates to finish first is not a step in planning a research paper.","ev":"Chờ bạn học làm xong trước không phải là một bước trong kế hoạch bài nghiên cứu."},{"id":"SSA101_Q355","t":"According to the text, feedback from instructors should be viewed primarily as:","o":[["A","Pure criticism to be ignored","Sự chỉ trích thuần túy cần bỏ qua"],["B","An opportunity for development and personal growth rather than just criticism","Một cơ hội phát triển và trưởng thành cá nhân, chứ không chỉ là sự chỉ trích"],["C","A final judgment with no room for improvement","Một phán quyết cuối cùng không còn chỗ để cải thiện"],["D","Only relevant for the current assignment","Chỉ liên quan đến bài tập hiện tại"]],"a":"B","s":0,"tv":"Theo the text, feedback from instructors should be viewed primarily as:","e":"Instructor feedback should be seen as a chance to grow, not just criticism.","ev":"Phản hồi của giảng viên nên được xem là cơ hội phát triển, không chỉ là chỉ trích."},{"id":"SSA101_Q356","t":"Mid-course reflection (e.g., after midterm exams or major assignments) is useful for:","o":[["A","Avoiding any changes to study habits","Tránh mọi thay đổi trong thói quen học"],["B","Evaluating current performance, target grades, and effectiveness of preparation strategies, then revising approaches","Đánh giá thành tích hiện tại, điểm mục tiêu và hiệu quả của các chiến lược chuẩn bị, rồi điều chỉnh cách tiếp cận"],["C","Focusing only on past successes","Chỉ tập trung vào những thành công trong quá khứ"],["D","Ignoring available support resources","Phớt lờ các nguồn hỗ trợ có sẵn"]],"a":"B","s":0,"tv":"Việc suy ngẫm giữa khóa học (ví dụ sau thi giữa kỳ hoặc bài tập lớn) hữu ích để:","e":"Mid-course reflection reviews performance and strategies so you can revise your approach.","ev":"Suy ngẫm giữa khóa học giúp xem lại thành tích và chiến lược để điều chỉnh cách tiếp cận."},{"id":"SSA101_Q357","t":"The quote \"We all need people who will give us feedback. That's how we improve.\" (Bill Gates) is used in the text to emphasize that:","o":[["A","Feedback is unnecessary in online learning","Phản hồi là không cần thiết trong học trực tuyến"],["B","Feedback is an essential component of the learning process for improvement","Phản hồi là một thành phần thiết yếu của quá trình học để tiến bộ"],["C","Only grades matter, not comments","Chỉ điểm số quan trọng, không phải nhận xét"],["D","Feedback should be avoided to prevent stress","Nên tránh phản hồi để không bị căng thẳng"]],"a":"B","s":0,"tv":"Câu trích \"Tất cả chúng ta đều cần những người đưa ra phản hồi cho mình. Đó là cách chúng ta tiến bộ.\" (Bill Gates) được dùng trong văn bản để nhấn mạnh rằng:","e":"The quote stresses that feedback is an essential part of the learning process for improving.","ev":"Câu trích nhấn mạnh phản hồi là thành phần thiết yếu của quá trình học để tiến bộ."},{"id":"SSA101_Q358","t":"Why is taking structured notes considered more effective than simply re-reading online content?","o":[["A","Re-reading is always faster","Đọc lại luôn nhanh hơn"],["B","Notes enable faster review of key concepts, require critical engagement, and strengthen retention","Ghi chú giúp ôn nhanh hơn các khái niệm chính, đòi hỏi sự tham gia phản biện và củng cố trí nhớ"],["C","Notes eliminate the need to access the original text","Ghi chú loại bỏ nhu cầu truy cập văn bản gốc"],["D","Re-reading requires no intentional effort","Đọc lại không cần nỗ lực có chủ đích"]],"a":"B","s":0,"tv":"Tại sao taking structured notes considered more effective than simply re-reading online content?","e":"Structured notes speed up review, demand critical engagement and strengthen retention.","ev":"Ghi chú có cấu trúc giúp ôn nhanh hơn, đòi hỏi tư duy phản biện và củng cố trí nhớ."},{"id":"SSA101_Q359","t":"Which of the following is NOT mentioned as a possible note-taking method for online readings?","o":[["A","Handwritten notes with underlining and margin annotations","Ghi chú viết tay có gạch chân và chú thích bên lề"],["B","Typewritten notes in an electronic notebook","Ghi chú gõ trong sổ tay điện tử"],["C","Recording audio summaries only","Chỉ ghi âm bản tóm tắt"],["D","Digital annotation tools like Hypothes.is","Công cụ chú thích số như Hypothes.is"]],"a":"C","s":0,"tv":"Điều nào sau đây KHÔNG phải là mentioned as a possible note-taking method for online readings?","e":"Audio-only summaries are not listed as a note-taking method for online readings.","ev":"Chỉ ghi âm bản tóm tắt không được liệt kê là phương pháp ghi chú cho các bài đọc trực tuyến."},{"id":"SSA101_Q360","t":"To use Hypothes.is for annotating online texts, what is the first step after installing the Chrome extension?","o":[["A","Start annotating without an account","Bắt đầu chú thích mà không cần tài khoản"],["B","Create a free account with email, username, password, and activate via email confirmation","Tạo tài khoản miễn phí bằng email, tên người dùng, mật khẩu và kích hoạt qua xác nhận email"],["C","Purchase a premium subscription","Mua gói trả phí cao cấp"],["D","Share annotations publicly without login","Chia sẻ chú thích công khai mà không cần đăng nhập"]],"a":"B","s":0,"tv":"Để dùng Hypothes.is chú thích văn bản trực tuyến, bước đầu tiên sau khi cài tiện ích Chrome là gì?","e":"After installing the extension, first create a free account and activate it through email confirmation.","ev":"Sau khi cài tiện ích, bước đầu tiên là tạo tài khoản miễn phí và kích hoạt qua email xác nhận."},{"id":"SSA101_Q361","t":"In Hypothes.is, annotations are public by default, but users can control visibility by:","o":[["A","Deleting them after use","Xóa chúng sau khi dùng"],["B","Creating private groups for collaborative or personal notes","Tạo các nhóm riêng tư cho ghi chú cộng tác hoặc cá nhân"],["C","Making all annotations invisible","Làm mọi chú thích vô hình"],["D","Avoiding highlighting altogether","Tránh hoàn toàn việc đánh dấu"]],"a":"B","s":0,"tv":"Trong Hypothes.is, các chú thích mặc định là công khai, nhưng người dùng có thể kiểm soát khả năng hiển thị bằng cách:","e":"Private groups let users control who sees their annotations.","ev":"Nhóm riêng tư cho phép người dùng kiểm soát ai xem được chú thích của mình."},{"id":"SSA101_Q362","t":"When highlighting in online texts, the text advises to avoid:","o":[["A","Highlighting any key information","Đánh dấu bất kỳ thông tin quan trọng nào"],["B","Over-highlighting; limit to essential content only","Đánh dấu quá mức; chỉ giới hạn ở nội dung thiết yếu"],["C","Using annotations alongside highlights","Dùng chú thích cùng với đánh dấu"],["D","Collaborating on highlights","Cộng tác trên các đánh dấu"]],"a":"B","s":0,"tv":"Khi đánh dấu trong văn bản trực tuyến, văn bản khuyên nên tránh:","e":"Avoid over-highlighting and limit highlights to essential content.","ev":"Tránh đánh dấu quá mức và chỉ giới hạn ở nội dung thiết yếu."},{"id":"SSA101_Q363","t":"In online learning, why is there typically a larger volume of written material compared to traditional courses?","o":[["A","To reduce reading time","Để giảm thời gian đọc"],["B","It supports development of lifelong learning skills through purposeful selection and management","Nó hỗ trợ phát triển kỹ năng học tập suốt đời thông qua việc lựa chọn và quản lý có mục đích"],["C","To make courses more difficult","Để làm khóa học khó hơn"],["D","Reading is optional in online courses","Việc đọc là tùy chọn trong các khóa học trực tuyến"]],"a":"B","s":0,"tv":"Trong học trực tuyến, tại sao thường có khối lượng tài liệu viết lớn hơn so với các khóa học truyền thống?","e":"The larger volume builds lifelong learning skills through purposeful selection and management of material.","ev":"Khối lượng lớn giúp phát triển kỹ năng học suốt đời thông qua việc chọn lọc và quản lý tài liệu có mục đích."},{"id":"SSA101_Q364","t":"Before beginning any text, learners should first:","o":[["A","Read the entire document sequentially","Đọc toàn bộ tài liệu theo thứ tự"],["B","Clearly define their purpose for reading to determine the appropriate strategy","Xác định rõ mục đích đọc để chọn chiến lược phù hợp"],["C","Skip to the conclusion","Nhảy đến phần kết luận"],["D","Highlight everything immediately","Đánh dấu mọi thứ ngay lập tức"]],"a":"B","s":0,"tv":"Trước khi bắt đầu bất kỳ văn bản nào, người học nên trước tiên:","e":"First define your purpose for reading, which tells you which strategy to use.","ev":"Trước hết hãy xác định rõ mục đích đọc, từ đó chọn chiến lược phù hợp."},{"id":"SSA101_Q365","t":"The SQ3R method is recommended because it:","o":[["A","Encourages passive reading","Khuyến khích đọc thụ động"],["B","Provides a structured approach for efficient, purposeful, and active reading","Cung cấp cách tiếp cận có cấu trúc để đọc hiệu quả, có mục đích và chủ động"],["C","Requires reading every word in sequence","Yêu cầu đọc từng từ theo thứ tự"],["D","Eliminates the need for notes","Loại bỏ nhu cầu ghi chú"]],"a":"B","s":0,"tv":"Phương pháp SQ3R được khuyến nghị vì nó:","e":"SQ3R gives a structured way to read efficiently, purposefully and actively.","ev":"SQ3R cung cấp cách đọc có cấu trúc, hiệu quả, có mục đích và chủ động."},{"id":"SSA101_Q366","t":"In the \"Survey\" step of SQ3R, what should learners do first?","o":[["A","Read the entire chapter in detail","Đọc chi tiết toàn bộ chương"],["B","Skim the chapter, starting with Learning Objectives, headings, diagrams, and the chapter summary","Lướt qua chương, bắt đầu với Mục tiêu học tập, các tiêu đề, sơ đồ và phần tóm tắt chương"],["C","Create questions without overview","Đặt câu hỏi mà không xem tổng quan"],["D","Recite the content aloud immediately","Đọc to nội dung ngay lập tức"]],"a":"B","s":0,"tv":"Ở bước \"Survey\" (Khảo sát) của SQ3R, người học nên làm gì trước tiên?","e":"Survey means skimming the chapter first: objectives, headings, diagrams and the summary.","ev":"Khảo sát là lướt qua chương trước: mục tiêu, tiêu đề, sơ đồ và phần tóm tắt."},{"id":"SSA101_Q367","t":"The \"Question\" step in SQ3R involves:","o":[["A","Ignoring headings","Bỏ qua các tiêu đề"],["B","Formulating questions based on headings and key concepts to guide focused reading","Đặt câu hỏi dựa trên tiêu đề và các khái niệm chính để định hướng việc đọc tập trung"],["C","Only reading without questions","Chỉ đọc mà không có câu hỏi"],["D","Reciting answers before reading","Đọc thuộc câu trả lời trước khi đọc"]],"a":"B","s":0,"tv":"Bước \"Question\" (Đặt câu hỏi) trong SQ3R bao gồm:","e":"Question means turning headings and key concepts into questions that guide focused reading.","ev":"Đặt câu hỏi là biến các tiêu đề và khái niệm chính thành câu hỏi để định hướng việc đọc tập trung."},{"id":"SSA101_Q368","t":"During the \"Read\" step of SQ3R, learners should:","o":[["A","Read passively for enjoyment","Đọc thụ động để giải trí"],["B","Read actively to locate answers to formulated questions, focusing on key paragraphs and terms","Đọc chủ động để tìm câu trả lời cho các câu hỏi đã đặt, tập trung vào các đoạn và thuật ngữ chính"],["C","Skip sections that seem difficult","Bỏ qua các phần có vẻ khó"],["D","Highlight everything uniformly","Đánh dấu mọi thứ như nhau"]],"a":"B","s":0,"tv":"Trong bước \"Read\" (Đọc) của SQ3R, người học nên:","e":"Read actively to find answers to your questions, focusing on key paragraphs and terms.","ev":"Đọc chủ động để tìm câu trả lời cho các câu hỏi đã đặt, tập trung vào đoạn và thuật ngữ chính."},{"id":"SSA101_Q369","t":"In the \"Recite\" step, what is the key action after reading a section?","o":[["A","Immediately move to the next section","Chuyển ngay sang phần tiếp theo"],["B","Restate main ideas in your own words (paraphrase) before recording notes","Diễn đạt lại các ý chính bằng lời của mình (paraphrase) trước khi ghi chú"],["C","Copy the text verbatim","Sao chép nguyên văn văn bản"],["D","Avoid any note-taking","Tránh mọi việc ghi chú"]],"a":"B","s":0,"tv":"Ở bước \"Recite\" (Đọc lại thành lời), hành động chính sau khi đọc một phần là gì?","e":"After each section, restate the main ideas in your own words before writing notes.","ev":"Sau mỗi phần, hãy diễn đạt lại các ý chính bằng lời của mình trước khi ghi chú."},{"id":"SSA101_Q370","t":"The final \"Review\" step of SQ3R involves:","o":[["A","Never revisiting the chapter","Không bao giờ xem lại chương"],["B","Revisit notes for the entire chapter, identify connections, and address gaps in understanding","Xem lại ghi chú của toàn bộ chương, xác định các kết nối và giải quyết những chỗ chưa hiểu"],["C","Only reviewing highlights","Chỉ xem lại các phần đã đánh dấu"],["D","Starting a new chapter immediately","Bắt đầu chương mới ngay lập tức"]],"a":"B","s":0,"tv":"Bước \"Review\" (Ôn lại) cuối cùng của SQ3R bao gồm:","e":"Review means revisiting your notes for the whole chapter, finding connections and closing gaps.","ev":"Ôn lại là xem lại ghi chú của cả chương, tìm các kết nối và lấp những chỗ chưa hiểu."},{"id":"SSA101_Q371","t":"After determining a journal article is relevant, what is a recommended next step before detailed reading?","o":[["A","Read the full text sequentially","Đọc toàn văn theo thứ tự"],["B","Scan by reviewing headings, bold/italic terms, charts/graphs, and record bibliographic information","Quét bằng cách xem các tiêu đề, thuật ngữ in đậm/nghiêng, biểu đồ/đồ thị và ghi lại thông tin thư mục"],["C","Skip to the references only","Chỉ nhảy đến phần tài liệu tham khảo"],["D","Annotate without scanning","Chú thích mà không quét trước"]],"a":"B","s":0,"tv":"Sau khi xác định một bài báo tạp chí có liên quan, bước tiếp theo được khuyến nghị trước khi đọc chi tiết là gì?","e":"Scan the headings, bold or italic terms and charts, and record bibliographic information before detailed reading.","ev":"Hãy quét tiêu đề, thuật ngữ in đậm/nghiêng, biểu đồ và ghi lại thông tin thư mục trước khi đọc chi tiết."},{"id":"SSA101_Q372","t":"In the Plan-Monitor-Evaluate model of metacognitive learning, what specific activity takes place during the \"Evaluation\" phase of the learning cycle?","o":[["A","You identify the specific steps you must take to move toward your goal, choose the learning strategies you will use, and actively reach out for support when necessary","Bạn xác định các bước cụ thể phải thực hiện để tiến tới mục tiêu, chọn chiến lược học sẽ dùng và chủ động tìm sự hỗ trợ khi cần"],["B","You continuously track what you have successfully learned, recognize what you do not yet know, and assess whether your current study strategies are functioning properly","Bạn liên tục theo dõi những gì đã học thành công, nhận ra những gì chưa biết và đánh giá xem các chiến lược học hiện tại có đang hoạt động đúng không"],["C","You reflect on how well you met your learning objectives after completing a unit of study and consider how your exam preparation strategies could be improved next time","Bạn suy ngẫm xem mình đã đạt mục tiêu học tập tốt đến đâu sau khi hoàn thành một đơn vị học và cân nhắc cách cải thiện chiến lược chuẩn bị thi lần sau"],["D","You carefully curate the course content and design meaningful collaborative activities that will lead your fellow team members toward professional and personal growth","Bạn biên soạn cẩn thận nội dung khóa học và thiết kế các hoạt động hợp tác có ý nghĩa để dẫn dắt các thành viên trong nhóm đến sự phát triển nghề nghiệp và cá nhân"]],"a":"C","s":0,"e":"The \"Evaluation\" phase acts as the critical final step in the metacognitive learning cycle, occurring strictly after an academic task, unit, or rigorous exam is fully completed. During this phase, a student must brutally and honestly reflect on whether they actually achieved their initial learning objectives. By objectively analyzing exactly what study strategies worked and which preparation methods completely failed, the student can highly effectively adapt and optimize their approach for the next academic challenge.","ev":"Giai đoạn \"Đánh giá\" đóng vai trò là bước cuối cùng quan trọng trong chu trình học tập siêu nhận thức, diễn ra ngay sau khi một nhiệm vụ học tập, một học phần hoặc một kỳ thi kết thúc. Trong giai đoạn này, sinh viên phải tự suy ngẫm trung thực xem mình có đạt được mục tiêu học tập ban đầu hay không và phân tích chiến lược nào hiệu quả hoặc thất bại để tối ưu hóa cho lần tiếp theo.","g":"new","tv":"Trong mô hình Lập kế hoạch – Theo dõi – Đánh giá của việc học siêu nhận thức, hoạt động cụ thể nào diễn ra trong giai đoạn \"Đánh giá\" của chu trình học?"}],"mocks":[],"sets":[{"id":"new","name":"Source của Thành","short":"Source của Thành","desc":"Bộ câu hỏi mới, lấy từ source của Thành.","icon":"🆕"},{"id":"src","name":"Source cũ","short":"Source cũ","desc":"Các câu hỏi từ nguồn đề cũ.","icon":"📚"}]};
